typedef struct pcore_browse_history {
    char entries[PCORE_BROWSE_HISTORY_MAX][PCORE_BROWSE_HISTORY_URL_MAX];
    char states[PCORE_BROWSE_HISTORY_MAX][PCORE_BROWSE_HISTORY_STATE_MAX];
    unsigned long document_ids[PCORE_BROWSE_HISTORY_MAX];
    unsigned long next_document_id;
    int count;
    int index;
} pcore_browse_history;

static pcore_browse_history g_browse_history;
static HANDLE g_browse_history_product = NULL;

/* Implemented next to the host scrollbar code below.  The Browser history
 * handle owns per-entry viewport snapshots; these helpers only apply one to
 * the host window and clamp it against the current document. */
static int pcore_scroll_to_xy(HWND hwnd, int target_x, int target_y);
static void pcore_browser_script_sync_scroll(void);
static void pcore_browser_script_notify_resize(void);

/* The product DLL owns URL/state/document-id history and viewport snapshots.
 * This fixed-size host mirror carries URL/state/document ids for legacy
 * assertions; navigation and scroll policy remain in the product API. */
static int pcore_browse_history_product_ensure(void)
{
    if (g_browse_history_product == NULL) {
        g_browse_history_product = PBrowser_HistoryCreate();
    }
    return (g_browse_history_product != NULL) ? 0 : 1;
}

static void pcore_browse_history_product_sync(void)
{
    int i;
    int count;
    int index;
    const char *url;
    const char *state;

    if (g_browse_history_product == NULL) {
        memset(&g_browse_history, 0, sizeof(g_browse_history));
        g_browse_history.index = -1;
        return;
    }
    count = PBrowser_HistoryCount(g_browse_history_product);
    index = PBrowser_HistoryIndex(g_browse_history_product);
    if (count < 0 || count > PCORE_BROWSE_HISTORY_MAX) {
        memset(&g_browse_history, 0, sizeof(g_browse_history));
        g_browse_history.index = -1;
        return;
    }
    memset(&g_browse_history, 0, sizeof(g_browse_history));
    g_browse_history.index = -1;
    g_browse_history.count = count;
    g_browse_history.index = index;
    for (i = 0; i < count; i++) {
        url = PBrowser_HistoryEntryUrl(g_browse_history_product, i);
        state = PBrowser_HistoryEntryState(g_browse_history_product, i);
        if (url != NULL) {
            strcpy(g_browse_history.entries[i], url);
        }
        if (state != NULL) {
            strcpy(g_browse_history.states[i], state);
        }
        g_browse_history.document_ids[i] =
                PBrowser_HistoryEntryDocumentId(
                g_browse_history_product, i);
    }
}

static void pcore_browse_history_save_scroll(void)
{
    if (g_browse_history_product != NULL &&
            g_browse_history.index >= 0 &&
            g_browse_history.index < g_browse_history.count) {
        (void) PBrowser_HistorySetEntryScroll(g_browse_history_product,
                g_browse_history.index,
                (g_scroll_x >= 0) ? g_scroll_x : 0,
                (g_scroll_y >= 0) ? g_scroll_y : 0);
    }
}

static int pcore_browse_history_scroll_at(int index, int *out_x, int *out_y)
{
    int scroll_x;
    int scroll_y;

    if (out_x != NULL) {
        *out_x = 0;
    }
    if (out_y != NULL) {
        *out_y = 0;
    }
    if (g_browse_history_product != NULL && index >= 0 &&
            index < g_browse_history.count &&
            PBrowser_HistoryEntryScroll(g_browse_history_product, index,
            &scroll_x, &scroll_y) == PBROWSER_OK) {
        if (out_x != NULL) {
            *out_x = scroll_x;
        }
        if (out_y != NULL) {
            *out_y = scroll_y;
        }
        return PBROWSER_OK;
    }
    return PBROWSER_ERROR_ARGUMENT;
}

static int pcore_browse_history_restore_scroll(HWND hwnd, int index)
{
    int scroll_x;
    int scroll_y;
    int restoration_mode;

    /* The Browser owns history.scrollRestoration. A manual page policy
     * deliberately leaves the current host viewport untouched; any
     * fragment reveal or explicit script scroll remains a separate path. */
    restoration_mode = PBROWSER_SCROLL_RESTORATION_AUTO;
    if (g_browser_script_session.session != NULL &&
            PBrowser_ScriptSessionGetScrollRestoration(
            g_browser_script_session.session, &restoration_mode) ==
            PSCRIPT_OK && restoration_mode ==
            PBROWSER_SCROLL_RESTORATION_MANUAL) {
        return 1;
    }

    if (pcore_browse_history_scroll_at(index, &scroll_x, &scroll_y) !=
            PBROWSER_OK) {
        scroll_x = 0;
        scroll_y = 0;
    }
    return pcore_scroll_to_xy(hwnd, scroll_x, scroll_y);
}

static void pcore_browse_history_product_destroy(void)
{
    if (g_browse_history_product != NULL) {
        PBrowser_HistoryDestroy(g_browse_history_product);
        g_browse_history_product = NULL;
    }
    memset(&g_browse_history, 0, sizeof(g_browse_history));
    g_browse_history.index = -1;
}

static void pcore_browse_history_reset(void)
{
    if (pcore_browse_history_product_ensure() != 0) {
        memset(&g_browse_history, 0, sizeof(g_browse_history));
        g_browse_history.index = -1;
        return;
    }
    PBrowser_HistoryReset(g_browse_history_product);
    pcore_browse_history_product_sync();
}

static const char *pcore_browse_history_current(void)
{
    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryCurrentUrl(g_browse_history_product);
    }
    if (g_browse_history.index < 0 ||
            g_browse_history.index >= g_browse_history.count) {
        return NULL;
    }
    return g_browse_history.entries[g_browse_history.index];
}

static const char *pcore_browse_history_state_at(int index)
{
    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryEntryState(g_browse_history_product, index);
    }
    if (index < 0 || index >= g_browse_history.count ||
            g_browse_history.states[index][0] == '\0') {
        return "null";
    }
    return g_browse_history.states[index];
}

static const char *pcore_browse_history_current_state(void)
{
    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryCurrentState(g_browse_history_product);
    }
    return pcore_browse_history_state_at(g_browse_history.index);
}

static unsigned long pcore_browse_history_new_document_id(void)
{
    g_browse_history.next_document_id++;
    if (g_browse_history.next_document_id == 0) {
        g_browse_history.next_document_id++;
    }
    return g_browse_history.next_document_id;
}

static int pcore_browse_history_same_document_target(int target_index)
{
    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryIsSameDocumentTarget(
                g_browse_history_product, target_index);
    }
    if (target_index < 0 || target_index >= g_browse_history.count ||
            target_index == g_browse_history.index ||
            g_browse_history.index < 0 ||
            g_browse_history.index >= g_browse_history.count ||
            g_browse_history.document_ids[target_index] == 0) {
        return 0;
    }
    return g_browse_history.document_ids[target_index] ==
            g_browse_history.document_ids[g_browse_history.index];
}

static int pcore_browse_history_same_base_url(const char *left,
        const char *right)
{
    const char *left_hash;
    const char *right_hash;
    size_t left_length;
    size_t right_length;

    if (g_browse_history_product != NULL) {
        return PBrowser_HistorySameBaseUrl(left, right);
    }

    if (left == NULL || right == NULL || left[0] == '\0' ||
            right[0] == '\0') {
        return 0;
    }
    left_hash = strchr(left, '#');
    right_hash = strchr(right, '#');
    left_length = (left_hash != NULL) ?
            (size_t) (left_hash - left) : strlen(left);
    right_length = (right_hash != NULL) ?
            (size_t) (right_hash - right) : strlen(right);
    return left_length == right_length &&
            memcmp(left, right, left_length) == 0;
}

/* Browser fragment navigation may arrive from an anchor as a fragment-only
 * href.  The product browser layer deliberately keeps that borrowed href
 * unchanged; the host expands it against the visible document URL before
 * applying the same-base history guard. */
static int pcore_browser_script_normalize_fragment_url(
        const pcore_browser_script_bridge *bridge, const char *url,
        char *out_url, int out_capacity)
{
    const char *hash;
    size_t base_length;
    size_t fragment_length;

    if (bridge == NULL || url == NULL || url[0] == '\0' ||
            out_url == NULL || out_capacity <= 0) {
        return 0;
    }
    if (url[0] != '#') {
        if (strlen(url) >= (size_t) out_capacity) {
            return 0;
        }
        memcpy(out_url, url, strlen(url) + 1);
        return 1;
    }
    if (bridge->history_url == NULL || bridge->history_url[0] == '\0') {
        return 0;
    }
    hash = strchr(bridge->history_url, '#');
    base_length = (hash != NULL) ?
            (size_t) (hash - bridge->history_url) :
            strlen(bridge->history_url);
    fragment_length = strlen(url);
    if (base_length + fragment_length >= (size_t) out_capacity) {
        return 0;
    }
    memcpy(out_url, bridge->history_url, base_length);
    memcpy(out_url + base_length, url, fragment_length + 1);
    return 1;
}

/* History state URLs may change the path/query, but must remain same-origin.
 * This intentionally compares the textual scheme/authority boundary, with
 * only HTTP/HTTPS default-port normalization; it is a narrow browser-script
 * bridge rule, not a complete URL parser. */
static const char *pcore_browse_history_trim_default_port(
        const char *scheme, size_t scheme_length,
        const char *authority_start, const char *authority_end)
{
    const char *cursor;
    const char *colon;
    int colon_count;
    size_t port_length;

    colon = NULL;
    colon_count = 0;
    for (cursor = authority_start; cursor < authority_end; cursor++) {
        if (*cursor == ':') {
            colon = cursor;
            colon_count++;
        }
    }
    if (colon_count != 1 || colon == NULL ||
            (scheme_length != 4 && scheme_length != 5)) {
        return authority_end;
    }
    port_length = (size_t) (authority_end - colon - 1);
    if (scheme_length == 4 && _strnicmp(scheme, "http", 4) == 0 &&
            port_length == 2 && memcmp(colon + 1, "80", 2) == 0) {
        return colon;
    }
    if (scheme_length == 5 && _strnicmp(scheme, "https", 5) == 0 &&
            port_length == 3 && memcmp(colon + 1, "443", 3) == 0) {
        return colon;
    }
    return authority_end;
}

static int pcore_browse_history_same_origin_url(const char *left,
        const char *right)
{
    const char *left_scheme;
    const char *right_scheme;
    const char *left_authority;
    const char *right_authority;
    const char *left_end;
    const char *right_end;
    size_t left_scheme_length;
    size_t right_scheme_length;
    size_t left_length;
    size_t right_length;

    if (g_browse_history_product != NULL) {
        return PBrowser_HistorySameOriginUrl(left, right);
    }

    if (left == NULL || right == NULL || left[0] == '\0' ||
            right[0] == '\0') {
        return 0;
    }
    left_scheme = strstr(left, "://");
    right_scheme = strstr(right, "://");
    if (left_scheme == NULL || right_scheme == NULL) {
        return 0;
    }
    left_scheme_length = (size_t) (left_scheme - left);
    right_scheme_length = (size_t) (right_scheme - right);
    if (left_scheme_length != right_scheme_length ||
            _strnicmp(left, right, left_scheme_length) != 0) {
        return 0;
    }
    left_authority = left_scheme + 3;
    right_authority = right_scheme + 3;
    left_end = left_authority;
    while (*left_end != '\0' && *left_end != '/' &&
            *left_end != '?' && *left_end != '#') {
        left_end++;
    }
    right_end = right_authority;
    while (*right_end != '\0' && *right_end != '/' &&
            *right_end != '?' && *right_end != '#') {
        right_end++;
    }
    left_end = pcore_browse_history_trim_default_port(left,
            left_scheme_length, left_authority, left_end);
    right_end = pcore_browse_history_trim_default_port(right,
            right_scheme_length, right_authority, right_end);
    left_length = (size_t) (left_end - left_authority);
    right_length = (size_t) (right_end - right_authority);
    return left_length == right_length &&
            _strnicmp(left_authority, right_authority, left_length) == 0;
}

static int pcore_browse_history_replace_state_url(const char *url,
        const char *state_json)
{
    HANDLE parsed;
    int rc;

    if (g_browse_history_product != NULL) {
        pcore_browse_history_save_scroll();
        rc = PBrowser_HistoryReplaceState(
                g_browse_history_product, url, state_json);
        pcore_browse_history_product_sync();
        return rc;
    }

    if (pcore_browse_history_current() == NULL || url == NULL ||
            url[0] == '\0' ||
            strlen(url) >= PCORE_BROWSE_HISTORY_URL_MAX ||
            !pcore_browse_history_same_origin_url(
            pcore_browse_history_current(), url) || state_json == NULL ||
            state_json[0] == '\0' ||
            strlen(state_json) >= PCORE_BROWSE_HISTORY_STATE_MAX) {
        return 1;
    }
    parsed = PJson_Parse(state_json);
    if (parsed == NULL) {
        return 1;
    }
    PJson_Free(parsed);
    strcpy(g_browse_history.entries[g_browse_history.index], url);
    strcpy(g_browse_history.states[g_browse_history.index], state_json);
    return 0;
}

static int pcore_browse_history_replace_state(const char *state_json)
{
    if (g_browse_history_product != NULL) {
        return pcore_browse_history_replace_state_url(
                pcore_browse_history_current(), state_json);
    }
    return pcore_browse_history_replace_state_url(
            pcore_browse_history_current(), state_json);
}

static int pcore_browse_history_push_state(const char *url,
        const char *state_json)
{
    HANDLE parsed;
    int i;

    if (g_browse_history_product != NULL) {
        pcore_browse_history_save_scroll();
        i = PBrowser_HistoryPushState(g_browse_history_product, url,
                state_json);
        pcore_browse_history_product_sync();
        return i;
    }

    if (pcore_browse_history_current() == NULL || url == NULL ||
            url[0] == '\0' || strlen(url) >= PCORE_BROWSE_HISTORY_URL_MAX ||
            !pcore_browse_history_same_origin_url(
            pcore_browse_history_current(), url) ||
            state_json == NULL || state_json[0] == '\0' ||
            strlen(state_json) >= PCORE_BROWSE_HISTORY_STATE_MAX) {
        return 1;
    }
    parsed = PJson_Parse(state_json);
    if (parsed == NULL) {
        return 1;
    }
    PJson_Free(parsed);
    if (g_browse_history.index + 1 < g_browse_history.count) {
        g_browse_history.count = g_browse_history.index + 1;
    }
    if (g_browse_history.count >= PCORE_BROWSE_HISTORY_MAX) {
        for (i = 1; i < g_browse_history.count; i++) {
            memcpy(g_browse_history.entries[i - 1],
                    g_browse_history.entries[i],
                    PCORE_BROWSE_HISTORY_URL_MAX);
            memcpy(g_browse_history.states[i - 1],
                    g_browse_history.states[i],
                    PCORE_BROWSE_HISTORY_STATE_MAX);
            g_browse_history.document_ids[i - 1] =
                    g_browse_history.document_ids[i];
        }
        g_browse_history.count--;
        g_browse_history.index--;
    }
    strcpy(g_browse_history.entries[g_browse_history.count], url);
    strcpy(g_browse_history.states[g_browse_history.count], state_json);
    g_browse_history.document_ids[g_browse_history.count] =
            g_browse_history.document_ids[g_browse_history.index];
    g_browse_history.count++;
    g_browse_history.index = g_browse_history.count - 1;
    return 0;
}

static int pcore_browse_history_commit_new(const char *url)
{
    int i;

    if (g_browse_history_product != NULL) {
        i = PBrowser_HistoryCommitNavigation(
                g_browse_history_product, url,
                PBROWSER_HISTORY_METHOD_GET,
                PBROWSER_HISTORY_TARGET_NEW);
        pcore_browse_history_product_sync();
        return i;
    }

    if (url == NULL || url[0] == '\0' ||
            strlen(url) >= PCORE_BROWSE_HISTORY_URL_MAX) {
        return 1;
    }
    if (pcore_browse_history_current() != NULL &&
            strcmp(pcore_browse_history_current(), url) == 0) {
        g_browse_history.document_ids[g_browse_history.index] =
                pcore_browse_history_new_document_id();
        return 0;
    }
    if (g_browse_history.index + 1 < g_browse_history.count) {
        g_browse_history.count = g_browse_history.index + 1;
    }
    if (g_browse_history.count >= PCORE_BROWSE_HISTORY_MAX) {
        for (i = 1; i < g_browse_history.count; i++) {
            memcpy(g_browse_history.entries[i - 1],
                    g_browse_history.entries[i],
                    PCORE_BROWSE_HISTORY_URL_MAX);
            memcpy(g_browse_history.states[i - 1],
                    g_browse_history.states[i],
                    PCORE_BROWSE_HISTORY_STATE_MAX);
            g_browse_history.document_ids[i - 1] =
                    g_browse_history.document_ids[i];
        }
        g_browse_history.count--;
        g_browse_history.index--;
    }
    strcpy(g_browse_history.entries[g_browse_history.count], url);
    strcpy(g_browse_history.states[g_browse_history.count], "null");
    g_browse_history.document_ids[g_browse_history.count] =
            pcore_browse_history_new_document_id();
    g_browse_history.count++;
    g_browse_history.index = g_browse_history.count - 1;
    return 0;
}

static const char *pcore_browse_history_back_target(int *target_index)
{
    int target;

    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryBackTarget(g_browse_history_product,
                target_index);
    }

    if (target_index == NULL || g_browse_history.index <= 0 ||
            g_browse_history.index >= g_browse_history.count) {
        return NULL;
    }
    target = g_browse_history.index - 1;
    *target_index = target;
    return g_browse_history.entries[target];
}

static const char *pcore_browse_history_forward_target(int *target_index)
{
    int target;

    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryForwardTarget(g_browse_history_product,
                target_index);
    }

    if (target_index == NULL || g_browse_history.index < 0 ||
            g_browse_history.index + 1 >= g_browse_history.count) {
        return NULL;
    }
    target = g_browse_history.index + 1;
    *target_index = target;
    return g_browse_history.entries[target];
}

static const char *pcore_browse_history_go_target(int delta,
        int *target_index)
{
    int target;

    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryGoTarget(g_browse_history_product, delta,
                target_index);
    }

    if (target_index == NULL || g_browse_history.index < 0 ||
            g_browse_history.index >= g_browse_history.count ||
            delta < -(PCORE_BROWSE_HISTORY_MAX - 1) ||
            delta > PCORE_BROWSE_HISTORY_MAX - 1) {
        return NULL;
    }
    target = g_browse_history.index + delta;
    if (target < 0 || target >= g_browse_history.count) {
        return NULL;
    }
    *target_index = target;
    return g_browse_history.entries[target];
}

static int pcore_browse_history_commit_target(int target_index)
{
    int rc;

    if (g_browse_history_product != NULL) {
        rc = PBrowser_HistoryCommitTarget(
                g_browse_history_product, target_index);
        pcore_browse_history_product_sync();
        return rc;
    }
    if (target_index < 0 || target_index >= g_browse_history.count) {
        return 1;
    }
    g_browse_history.index = target_index;
    return 0;
}

static int pcore_browse_history_commit_target_document(int target_index)
{
    int rc;

    if (g_browse_history_product != NULL) {
        if (target_index < 0 || target_index >= g_browse_history.count) {
            return 1;
        }
        rc = PBrowser_HistoryCommitTargetDocument(
                g_browse_history_product, target_index);
        pcore_browse_history_product_sync();
        return rc;
    }
    if (pcore_browse_history_commit_target(target_index) != 0) {
        return 1;
    }
    g_browse_history.document_ids[target_index] =
            pcore_browse_history_new_document_id();
    return 0;
}

static int pcore_browse_history_replace_current(const char *url)
{
    int rc;

    if (g_browse_history_product != NULL) {
        rc = PBrowser_HistoryReplaceCurrent(
                g_browse_history_product, url);
        pcore_browse_history_product_sync();
        return rc;
    }
    if (url == NULL || url[0] == '\0' ||
            strlen(url) >= PCORE_BROWSE_HISTORY_URL_MAX) {
        return 1;
    }
    if (pcore_browse_history_current() == NULL) {
        return pcore_browse_history_commit_new(url);
    }
    strcpy(g_browse_history.entries[g_browse_history.index], url);
    strcpy(g_browse_history.states[g_browse_history.index], "null");
    g_browse_history.document_ids[g_browse_history.index] =
            pcore_browse_history_new_document_id();
    return 0;
}

static int pcore_browse_history_commit_navigation(const char *url,
        int method, int target_index)
{
    if (method != 1) {
        return 1;
    }
    if (target_index == PCORE_BROWSE_HISTORY_TARGET_REPLACE_CURRENT) {
        return pcore_browse_history_replace_current(url);
    }
    if (target_index >= 0) {
        return pcore_browse_history_commit_target_document(target_index);
    }
    return pcore_browse_history_commit_new(url);
}

static int pcore_browse_history_commit_navigation_with_state(
        const char *url, int method, int target_index,
        const char *state_json)
{
    int rc;

    if (g_browse_history_product != NULL) {
        rc = PBrowser_HistoryCommitNavigationWithState(
                g_browse_history_product, url, method, target_index,
                state_json);
        pcore_browse_history_product_sync();
        return rc;
    }
    if (pcore_browse_history_commit_navigation(url, method,
            target_index) != 0) {
        return 1;
    }
    if (state_json != NULL &&
            pcore_browse_history_replace_state(state_json) != 0) {
        return 1;
    }
    return 0;
}

static int pcore_browse_history_commit_navigation_with_bridge(
        const char *url, int method, int target_index,
        const pcore_browser_script_bridge *bridge)
{
    int i;

    if (pcore_browse_history_commit_navigation(url, method,
            target_index) != 0) {
        return 1;
    }
    if (bridge == NULL) {
        return 0;
    }
    if (bridge->history_state_changed &&
            pcore_browse_history_replace_state_url(
            bridge->history_entry_url, bridge->history_state_json) != 0) {
        return 1;
    }
    for (i = 0; i < bridge->history_push_count; i++) {
        if (pcore_browse_history_push_state(bridge->history_push_urls[i],
                bridge->history_push_states[i]) != 0) {
            return 1;
        }
    }
    return 0;
}

static int pcore_browse_history_exposed_length(void)
{
    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryCount(g_browse_history_product) > 0 ?
                PBrowser_HistoryCount(g_browse_history_product) : 1;
    }
    return (g_browse_history.count > 0) ? g_browse_history.count : 1;
}

static int pcore_browse_history_navigation_length(const char *url,
        int method, int target_index)
{
    int count;

    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryNavigationLength(
                g_browse_history_product, url, method, target_index);
    }

    count = g_browse_history.count;
    if (method != 1) {
        return (count > 0) ? count : 1;
    }
    if (target_index == PCORE_BROWSE_HISTORY_TARGET_REPLACE_CURRENT ||
            target_index >= 0) {
        return (count > 0) ? count : 1;
    }
    if (url == NULL || url[0] == '\0' ||
            strlen(url) >= PCORE_BROWSE_HISTORY_URL_MAX) {
        return (count > 0) ? count : 1;
    }
    if (pcore_browse_history_current() != NULL &&
            strcmp(pcore_browse_history_current(), url) == 0) {
        return (count > 0) ? count : 1;
    }
    if (g_browse_history.index + 1 < count) {
        count = g_browse_history.index + 1;
    }
    if (count < PCORE_BROWSE_HISTORY_MAX) {
        count++;
    }
    return (count > 0) ? count : 1;
}

static int pcore_browse_history_navigation_index(const char *url,
        int method, int target_index)
{
    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryNavigationIndex(
                g_browse_history_product, url, method, target_index);
    }
    if (method != 1) {
        return (g_browse_history.index >= 0) ?
                g_browse_history.index : 0;
    }
    if (target_index == PCORE_BROWSE_HISTORY_TARGET_REPLACE_CURRENT) {
        return (g_browse_history.index >= 0) ?
                g_browse_history.index : 0;
    }
    if (target_index >= 0) {
        return target_index;
    }
    if (pcore_browse_history_current() != NULL && url != NULL &&
            strcmp(pcore_browse_history_current(), url) == 0) {
        return g_browse_history.index;
    }
    return pcore_browse_history_navigation_length(url, method,
            target_index) - 1;
}

static const char *pcore_browse_history_navigation_state(const char *url,
        int method, int target_index)
{
    if (g_browse_history_product != NULL) {
        return PBrowser_HistoryNavigationState(
                g_browse_history_product, url, method, target_index);
    }
    if (method != 1) {
        return "null";
    }
    if (target_index == PCORE_BROWSE_HISTORY_TARGET_REPLACE_CURRENT) {
        return "null";
    }
    if (target_index >= 0) {
        return pcore_browse_history_state_at(target_index);
    }
    if (pcore_browse_history_current() != NULL && url != NULL &&
            strcmp(pcore_browse_history_current(), url) == 0) {
        return pcore_browse_history_current_state();
    }
    return "null";
}

typedef struct pcore_native_edit {
    HWND hwnd;
    unsigned int text_index;
    unsigned int contenteditable_index;
    unsigned long target_token;
    int content_editable;
    int multiline;
    char *content_editable_id;
    int native_change_expected;
    int native_mutation_in_progress;
    int native_cut_default_in_progress;
    int native_selection_direction;
    int native_selection_direction_valid;
    int native_selection_mouse_active;
    int native_selection_mouse_anchor;
    int native_selection_mouse_anchor_valid;
    int native_selection_keyboard_active;
    int native_selection_keyboard_anchor;
    int native_selection_keyboard_anchor_valid;
    int native_selection_shift_down;
    unsigned int pending_high_surrogate;
    UINT pending_high_message;
    LPARAM pending_high_lparam;
    int composition_active;
    int composition_committing;
    char *composition_data;
    WNDPROC original_proc;
} pcore_native_edit;

/* Resolve one native EDIT's current Core geometry. Form controls retain the
 * historical TextInputInfo path; contenteditable entries use the bounded
 * layout snapshot and are addressed by editing-host index. */
static int pcore_native_edit_geometry_info(
        const pcore_native_edit *native_edit, int *out_x, int *out_y,
        int *out_width, int *out_height, int *out_password,
        int *out_disabled)
{
    PCoreTextInputInfo text_info;
    PCoreContentEditableTargetInfo content_info;

    if (native_edit == NULL || g_render_doc == NULL) {
        return 0;
    }
    if (native_edit->content_editable) {
        memset(&content_info, 0, sizeof(content_info));
        content_info.size = sizeof(content_info);
        if (PCore_ContentEditableTargetInfo(g_render_doc,
                native_edit->contenteditable_index, &content_info,
                NULL, 0, NULL, 0) != 0) {
            return 0;
        }
        if (out_x != NULL) {
            *out_x = content_info.x;
        }
        if (out_y != NULL) {
            *out_y = content_info.y;
        }
        if (out_width != NULL) {
            *out_width = content_info.width;
        }
        if (out_height != NULL) {
            *out_height = content_info.height;
        }
        if (out_password != NULL) {
            *out_password = 0;
        }
        if (out_disabled != NULL) {
            *out_disabled = 0;
        }
        return 1;
    }
    memset(&text_info, 0, sizeof(text_info));
    if (PCore_TextInputInfo(g_render_doc, native_edit->text_index,
            &text_info, NULL, 0) != 0) {
        return 0;
    }
    if (out_x != NULL) {
        *out_x = text_info.x;
    }
    if (out_y != NULL) {
        *out_y = text_info.y;
    }
    if (out_width != NULL) {
        *out_width = text_info.width;
    }
    if (out_height != NULL) {
        *out_height = text_info.height;
    }
    if (out_password != NULL) {
        *out_password = text_info.password;
    }
    if (out_disabled != NULL) {
        *out_disabled = text_info.disabled;
    }
    return 1;
}

/* WM EDIT stores CRLF for multiline values while the Core/Browser boundary
 * exposes JavaScript UTF-16 offsets over logical LF text. Keep the small
 * selection bridge in the host's platform adapter and translate the one
 * line-ending difference at the boundary. */
static int pcore_native_edit_selection_load_text(HWND hwnd, WCHAR **out_text,
        int *out_length)
{
    WCHAR *text;
    int length;

    if (hwnd == NULL || out_text == NULL || out_length == NULL) {
        return 0;
    }
    *out_text = NULL;
    *out_length = 0;
    length = GetWindowTextLengthW(hwnd);
    if (length < 0) {
        return 0;
    }
    text = (WCHAR *) malloc((size_t) (length + 1) * sizeof(WCHAR));
    if (text == NULL) {
        return 0;
    }
    if (GetWindowTextW(hwnd, text, length + 1) < 0) {
        free(text);
        return 0;
    }
    text[length] = L'\0';
    *out_text = text;
    *out_length = length;
    return 1;
}

static int pcore_native_edit_selection_position(const WCHAR *text,
        int text_length, int position, int to_native)
{
    int i;
    int logical;

    if (text == NULL || text_length < 0) {
        return 0;
    }
    if (position < 0) {
        position = 0;
    }
    if (to_native) {
        logical = 0;
        i = 0;
        while (i < text_length && logical < position) {
            if (text[i] == L'\r' && i + 1 < text_length &&
                    text[i + 1] == L'\n') {
                i += 2;
            } else {
                i++;
            }
            logical++;
        }
        return i;
    }
    if (position > text_length) {
        position = text_length;
    }
    logical = 0;
    i = 0;
    while (i < text_length && i < position) {
        if (text[i] == L'\r' && i + 1 < text_length &&
                text[i + 1] == L'\n') {
            if (i + 1 >= position) {
                return logical + 1;
            }
            i += 2;
        } else {
            i++;
        }
        logical++;
    }
    return logical;
}

static int pcore_native_edit_selection_snapshot(
        const pcore_native_edit *native_edit, int *out_start, int *out_end,
        int *out_direction)
{
    DWORD native_start;
    DWORD native_end;
    WCHAR *text;
    int text_length;
    int start;
    int end;

    if (native_edit == NULL || native_edit->hwnd == NULL ||
            out_start == NULL || out_end == NULL || out_direction == NULL) {
        return 0;
    }
    native_start = 0;
    native_end = 0;
    SendMessage(native_edit->hwnd, EM_GETSEL, (WPARAM) &native_start,
            (LPARAM) &native_end);
    if (native_start > (DWORD) INT_MAX) {
        native_start = (DWORD) INT_MAX;
    }
    if (native_end > (DWORD) INT_MAX) {
        native_end = (DWORD) INT_MAX;
    }
    if (!pcore_native_edit_selection_load_text(native_edit->hwnd, &text,
            &text_length)) {
        return 0;
    }
    start = pcore_native_edit_selection_position(text, text_length,
            (int) native_start, 0);
    end = pcore_native_edit_selection_position(text, text_length,
            (int) native_end, 0);
    free(text);
    if (end < start) {
        end = start;
    }
    *out_start = start;
    *out_end = end;
    *out_direction = native_edit->native_selection_direction_valid ?
            native_edit->native_selection_direction :
            PBROWSER_SCRIPT_CONTENT_SELECTION_NONE;
    return 1;
}

static int pcore_native_edit_selection_apply(pcore_native_edit *native_edit,
        int start, int end, int direction)
{
    WCHAR *text;
    int text_length;
    int native_start;
    int native_end;

    if (native_edit == NULL || native_edit->hwnd == NULL || start < 0 ||
            end < 0 || direction < PBROWSER_SCRIPT_CONTENT_SELECTION_NONE ||
            direction > PBROWSER_SCRIPT_CONTENT_SELECTION_BACKWARD) {
        return 0;
    }
    if (!pcore_native_edit_selection_load_text(native_edit->hwnd, &text,
            &text_length)) {
        return 0;
    }
    native_start = pcore_native_edit_selection_position(text, text_length,
            start, 1);
    native_end = pcore_native_edit_selection_position(text, text_length,
            end, 1);
    free(text);
    if (native_end < native_start) {
        native_end = native_start;
    }
    SendMessage(native_edit->hwnd, EM_SETSEL, (WPARAM) native_start,
            (LPARAM) native_end);
    native_edit->native_selection_direction = direction;
    native_edit->native_selection_direction_valid = 1;
    return 1;
}

/* Return the native WM EDIT range before translating its CRLF offsets. The
 * ordered range is enough to infer which endpoint a simple mouse drag moved
 * because the anchor is kept separately by the subclass. */
static int pcore_native_edit_selection_native_range(
        const pcore_native_edit *native_edit, int *out_start, int *out_end)
{
    DWORD native_start;
    DWORD native_end;

    if (native_edit == NULL || native_edit->hwnd == NULL ||
            out_start == NULL || out_end == NULL) {
        return 0;
    }
    native_start = 0;
    native_end = 0;
    SendMessage(native_edit->hwnd, EM_GETSEL, (WPARAM) &native_start,
            (LPARAM) &native_end);
    if (native_start > (DWORD) INT_MAX || native_end > (DWORD) INT_MAX) {
        return 0;
    }
    *out_start = (int) native_start;
    *out_end = (int) native_end;
    return 1;
}

/* The browser input bridge uses logical LF text while the WinCE clipboard
 * contract uses CRLF.  Normalize the small borrowed payload in place before
 * handing it to Browser; never truncate a payload that would exceed the
 * browser transaction slot. */
static int pcore_native_edit_clipboard_normalize_utf8(char *value,
        int capacity)
{
    int source_index;
    int target_index;
    int length;

    if (value == NULL || capacity < 1) {
        return -1;
    }
    length = (int) strlen(value);
    source_index = 0;
    target_index = 0;
    while (source_index < length) {
        if (value[source_index] == '\r') {
            if (target_index + 1 >= capacity) {
                return -1;
            }
            value[target_index++] = '\n';
            source_index++;
            if (source_index < length && value[source_index] == '\n') {
                source_index++;
            }
        } else {
            if (target_index + 1 >= capacity) {
                return -1;
            }
            value[target_index++] = value[source_index++];
        }
    }
    value[target_index] = '\0';
    return target_index;
}

/* Copy the ordered native selection as the UTF-8 data for deleteByCut.  This
 * deliberately stays in the platform adapter: Core and Browser expose the
 * logical text/selection contract, while only the host knows the WM EDIT
 * range and its CRLF representation. */
static int pcore_native_edit_selection_utf8(
        const pcore_native_edit *native_edit, char *out, int capacity,
        int *out_has_selection)
{
    WCHAR *text;
    WCHAR *selected;
    char *utf8;
    int text_length;
    int native_start;
    int native_end;
    int selected_length;
    int utf8_length;
    int normalized_length;

    if (native_edit == NULL || out == NULL || capacity < 1 ||
            out_has_selection == NULL) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_INVALID_ARGUMENT);
        return 0;
    }
    out[0] = '\0';
    *out_has_selection = 0;
    if (!pcore_native_edit_selection_native_range(native_edit,
            &native_start, &native_end) ||
            !pcore_native_edit_selection_load_text(native_edit->hwnd,
            &text, &text_length)) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_SELECTION_FAILED);
        return 0;
    }
    if (native_start < 0 || native_end < 0 || native_start > text_length ||
            native_end > text_length) {
        free(text);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_SELECTION_FAILED);
        return 0;
    }
    if (native_end < native_start) {
        selected_length = native_start - native_end;
        native_start = native_end;
    } else {
        selected_length = native_end - native_start;
    }
    if (selected_length == 0) {
        free(text);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_COLLAPSED_SELECTION);
        return 1;
    }
    selected = (WCHAR *) malloc((size_t) (selected_length + 1) *
            sizeof(WCHAR));
    if (selected == NULL) {
        free(text);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_ALLOC_FAILED);
        return 0;
    }
    memcpy(selected, text + native_start,
            (size_t) selected_length * sizeof(WCHAR));
    selected[selected_length] = L'\0';
    free(text);
    utf8 = wide_to_utf8_alloc(selected);
    free(selected);
    if (utf8 == NULL) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_CONVERSION_FAILED);
        return 0;
    }
    utf8_length = (int) strlen(utf8);
    if (utf8_length >= capacity) {
        free(utf8);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OVERSIZE);
        return 0;
    }
    normalized_length = pcore_native_edit_clipboard_normalize_utf8(utf8,
            capacity);
    if (normalized_length < 0 || normalized_length >= capacity) {
        free(utf8);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OVERSIZE);
        return 0;
    }
    memcpy(out, utf8, (size_t) normalized_length + 1);
    free(utf8);
    *out_has_selection = 1;
    pcore_native_edit_clipboard_status_set(
            PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OK);
    return 1;
}

/* Read only CF_UNICODETEXT. Windows CE intentionally does not synthesize
 * formats, so accepting an unavailable/non-Unicode format would make the
 * native default action diverge from the Browser beforeinput data. The
 * returned text is copied while the clipboard is open and is never retained
 * as a clipboard-owned handle. */
static int pcore_native_edit_clipboard_get_utf8(HWND owner, char *out,
        int capacity)
{
    HANDLE data_handle;
    WCHAR *source;
    WCHAR *copy;
    char *utf8;
    UINT memory_bytes;
    int max_chars;
    int source_length;
    int utf8_length;
    int normalized_length;

    if (owner == NULL || out == NULL || capacity < 1) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_INVALID_ARGUMENT);
        return 0;
    }
    out[0] = '\0';
    if (!OpenClipboard(owner)) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OPEN_FAILED);
        return 0;
    }
    data_handle = GetClipboardData(CF_UNICODETEXT);
    if (data_handle == NULL) {
        CloseClipboard();
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_NO_UNICODE_FORMAT);
        return 0;
    }
    memory_bytes = GlobalSize((HGLOBAL) data_handle);
    if (memory_bytes < sizeof(WCHAR)) {
        CloseClipboard();
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_INVALID_SIZE);
        return 0;
    }
    max_chars = (int) (memory_bytes / sizeof(WCHAR));
    if (max_chars > PCORE_NATIVE_EDIT_CLIPBOARD_WIDE_CAP) {
        max_chars = PCORE_NATIVE_EDIT_CLIPBOARD_WIDE_CAP;
    }
    source = (WCHAR *) GlobalLock((HGLOBAL) data_handle);
    if (source == NULL) {
        CloseClipboard();
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_LOCK_FAILED);
        return 0;
    }
    source_length = 0;
    while (source_length < max_chars && source[source_length] != L'\0') {
        source_length++;
    }
    if (source_length >= max_chars) {
        GlobalUnlock((HGLOBAL) data_handle);
        CloseClipboard();
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_UNTERMINATED);
        return 0;
    }
    copy = (WCHAR *) malloc((size_t) (source_length + 1) *
            sizeof(WCHAR));
    if (copy == NULL) {
        GlobalUnlock((HGLOBAL) data_handle);
        CloseClipboard();
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_ALLOC_FAILED);
        return 0;
    }
    memcpy(copy, source, (size_t) (source_length + 1) * sizeof(WCHAR));
    GlobalUnlock((HGLOBAL) data_handle);
    CloseClipboard();
    utf8 = wide_to_utf8_alloc(copy);
    free(copy);
    if (utf8 == NULL) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_CONVERSION_FAILED);
        return 0;
    }
    utf8_length = (int) strlen(utf8);
    if (utf8_length >= capacity) {
        free(utf8);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OVERSIZE);
        return 0;
    }
    normalized_length = pcore_native_edit_clipboard_normalize_utf8(utf8,
            capacity);
    if (normalized_length < 0 || normalized_length >= capacity) {
        free(utf8);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OVERSIZE);
        return 0;
    }
    memcpy(out, utf8, (size_t) normalized_length + 1);
    free(utf8);
    pcore_native_edit_clipboard_status_set(
            PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OK);
    return 1;
}

/* Write one clipboard format after preparing and copying the data. Allocate
 * and lock the new handle before EmptyClipboard so an allocation/lock
 * failure cannot erase the caller's existing clipboard. */
static int pcore_native_edit_clipboard_set_bytes(HWND owner, UINT format,
        const void *bytes, int byte_count)
{
    HANDLE data_handle;
    void *locked;
    int open;

    if (owner == NULL || bytes == NULL || byte_count < 1) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_INVALID_ARGUMENT);
        return 0;
    }
    data_handle = (HANDLE) LocalAlloc(LMEM_MOVEABLE | LMEM_ZEROINIT,
            (UINT) byte_count);
    if (data_handle == NULL) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_ALLOC_FAILED);
        return 0;
    }
    locked = (void *) GlobalLock((HGLOBAL) data_handle);
    if (locked == NULL) {
        GlobalFree((HGLOBAL) data_handle);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_LOCK_FAILED);
        return 0;
    }
    memcpy(locked, bytes, (size_t) byte_count);
    GlobalUnlock((HGLOBAL) data_handle);
    open = OpenClipboard(owner) ? 1 : 0;
    if (!open) {
        GlobalFree((HGLOBAL) data_handle);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OPEN_FAILED);
        return 0;
    }
    if (!EmptyClipboard()) {
        GlobalFree((HGLOBAL) data_handle);
        CloseClipboard();
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_EMPTY_FAILED);
        return 0;
    }
    if (SetClipboardData(format, data_handle) == NULL) {
        GlobalFree((HGLOBAL) data_handle);
        CloseClipboard();
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_SET_FAILED);
        return 0;
    }
    CloseClipboard();
    pcore_native_edit_clipboard_status_set(
            PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OK);
    return 1;
}

/* Seed a deterministic Unicode clipboard for the native fixture. The host
 * is the owner because Windows CE rejects SetClipboardData for a window in
 * another process; ownership of the LocalAlloc handle transfers to the
 * clipboard only after SetClipboardData succeeds. */
static int pcore_native_edit_clipboard_set_utf8(HWND owner, const char *text)
{
    WCHAR *source;
    WCHAR *normalized;
    WCHAR *locked;
    HANDLE data_handle;
    int source_length;
    int target_length;
    int i;
    int open;

    if (owner == NULL || text == NULL) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_INVALID_ARGUMENT);
        return 0;
    }
    source = utf8_to_wide_alloc(text);
    if (source == NULL) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_CONVERSION_FAILED);
        return 0;
    }
    source_length = 0;
    while (source[source_length] != L'\0') {
        source_length++;
        if (source_length >= PCORE_NATIVE_EDIT_CLIPBOARD_WIDE_CAP) {
            free(source);
            pcore_native_edit_clipboard_status_set(
                    PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OVERSIZE);
            return 0;
        }
    }
    target_length = source_length;
    for (i = 0; i < source_length; i++) {
        if (source[i] == L'\n') {
            if (target_length >= PCORE_NATIVE_EDIT_CLIPBOARD_WIDE_CAP - 1) {
                free(source);
                pcore_native_edit_clipboard_status_set(
                        PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OVERSIZE);
                return 0;
            }
            target_length++;
        }
    }
    normalized = (WCHAR *) malloc((size_t) (target_length + 1) *
            sizeof(WCHAR));
    if (normalized == NULL) {
        free(source);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_ALLOC_FAILED);
        return 0;
    }
    target_length = 0;
    for (i = 0; source[i] != L'\0'; i++) {
        if (source[i] == L'\r' && source[i + 1] == L'\n') {
            normalized[target_length++] = L'\r';
            normalized[target_length++] = L'\n';
            i++;
        } else {
            if (source[i] == L'\n') {
                normalized[target_length++] = L'\r';
            }
            normalized[target_length++] = source[i];
        }
    }
    normalized[target_length] = L'\0';
    free(source);

    /* Windows CE's clipboard broker expects the Unicode handle to be
     * allocated after the clipboard has been opened and emptied. Keep this
     * ordering for CF_UNICODETEXT seeding; the generic byte helper above is
     * used only to inject a raw non-Unicode format in the negative probe. */
    open = OpenClipboard(owner) ? 1 : 0;
    if (!open) {
        free(normalized);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OPEN_FAILED);
        return 0;
    }
    if (!EmptyClipboard()) {
        CloseClipboard();
        free(normalized);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_EMPTY_FAILED);
        return 0;
    }
    data_handle = (HANDLE) LocalAlloc(LMEM_MOVEABLE | LMEM_ZEROINIT,
            (UINT) ((target_length + 1) * sizeof(WCHAR)));
    if (data_handle == NULL) {
        CloseClipboard();
        free(normalized);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_ALLOC_FAILED);
        return 0;
    }
    locked = (WCHAR *) GlobalLock((HGLOBAL) data_handle);
    if (locked == NULL) {
        GlobalFree((HGLOBAL) data_handle);
        CloseClipboard();
        free(normalized);
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_LOCK_FAILED);
        return 0;
    }
    memcpy(locked, normalized, (size_t) (target_length + 1) *
            sizeof(WCHAR));
    GlobalUnlock((HGLOBAL) data_handle);
    free(normalized);
    if (SetClipboardData(CF_UNICODETEXT, data_handle) == NULL) {
        GlobalFree((HGLOBAL) data_handle);
        CloseClipboard();
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_SET_FAILED);
        return 0;
    }
    CloseClipboard();
    pcore_native_edit_clipboard_status_set(
            PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OK);
    return 1;
}

static int pcore_native_edit_clipboard_empty(HWND owner)
{
    int opened;
    int result;

    if (owner == NULL) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_INVALID_ARGUMENT);
        return 0;
    }
    opened = OpenClipboard(owner) ? 1 : 0;
    if (!opened) {
        pcore_native_edit_clipboard_status_set(
                PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OPEN_FAILED);
        return 0;
    }
    result = EmptyClipboard() ? 1 : 0;
    CloseClipboard();
    pcore_native_edit_clipboard_status_set(result ?
            PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_OK :
            PCORE_NATIVE_EDIT_CLIPBOARD_STATUS_EMPTY_FAILED);
    return result;
}

static void pcore_native_edit_selection_mouse_direction(
        pcore_native_edit *native_edit)
{
    int native_start;
    int native_end;
    int direction;

    if (native_edit == NULL || !native_edit->native_selection_mouse_active ||
            !native_edit->native_selection_mouse_anchor_valid ||
            !pcore_native_edit_selection_native_range(native_edit,
            &native_start, &native_end)) {
        if (native_edit != NULL) {
            native_edit->native_selection_direction_valid = 0;
        }
        return;
    }
    if (native_end <= native_start) {
        direction = PBROWSER_SCRIPT_CONTENT_SELECTION_NONE;
    } else if (native_edit->native_selection_mouse_anchor <= native_start) {
        direction = PBROWSER_SCRIPT_CONTENT_SELECTION_FORWARD;
    } else if (native_edit->native_selection_mouse_anchor >= native_end) {
        direction = PBROWSER_SCRIPT_CONTENT_SELECTION_BACKWARD;
    } else {
        native_edit->native_selection_direction_valid = 0;
        return;
    }
    native_edit->native_selection_direction = direction;
    native_edit->native_selection_direction_valid = 1;
}

static void pcore_native_edit_selection_changed(
        pcore_native_edit *native_edit, int trusted)
{
    pcore_browser_script_bridge *bridge;
    int start;
    int end;
    int direction;
    int changed;

    if (native_edit == NULL || !native_edit->content_editable ||
            native_edit->content_editable_id == NULL || g_render_doc == NULL ||
            g_browser_script_session.document != g_render_doc ||
            g_browser_script_session.bridge == NULL ||
            g_browser_script_session.bridge->session == NULL) {
        return;
    }
    if (!pcore_native_edit_selection_snapshot(native_edit, &start, &end,
            &direction)) {
        return;
    }
    bridge = g_browser_script_session.bridge;
    changed = 0;
    (void) PBrowser_ScriptSessionNotifyContentEditableSelection(
            bridge->session, native_edit->content_editable_id, start, end,
            direction, trusted ? 1 : 0, &changed);
}

static void pcore_native_edit_selection_mouse_begin(
        pcore_native_edit *native_edit, WPARAM wp)
{
    int native_start;
    int native_end;

    if (native_edit == NULL) {
        return;
    }
    native_edit->native_selection_mouse_active = 1;
    native_edit->native_selection_mouse_anchor_valid = 0;
    native_edit->native_selection_direction_valid = 0;
    if ((wp & MK_SHIFT) != 0 || native_edit->native_selection_shift_down ||
            GetKeyState(VK_SHIFT) < 0 ||
            !pcore_native_edit_selection_native_range(native_edit,
            &native_start, &native_end)) {
        return;
    }
    /* Without Shift, the EDIT default procedure has already placed the caret
     * at the pointer. A non-collapsed result (for example a word click) uses
     * its leading endpoint as the bounded drag anchor. */
    native_edit->native_selection_mouse_anchor = native_start;
    native_edit->native_selection_mouse_anchor_valid = 1;
}

static void pcore_native_edit_selection_mouse_update(
        pcore_native_edit *native_edit, int final_update)
{
    if (native_edit == NULL || !native_edit->native_selection_mouse_active) {
        return;
    }
    pcore_native_edit_selection_mouse_direction(native_edit);
    pcore_native_edit_selection_changed(native_edit, 1);
    if (final_update) {
        native_edit->native_selection_mouse_active = 0;
        native_edit->native_selection_mouse_anchor_valid = 0;
    }
}

static int pcore_native_edit_selection_navigation_key(UINT msg, WPARAM wp)
{
    if (msg != WM_KEYDOWN) {
        return 0;
    }
    return wp == VK_LEFT || wp == VK_RIGHT || wp == VK_UP ||
            wp == VK_DOWN || wp == VK_HOME || wp == VK_END;
}

static void pcore_native_edit_selection_keyboard_begin(
        pcore_native_edit *native_edit)
{
    int native_start;
    int native_end;
    int anchor;
    int shift;
    int previous_direction;
    int previous_direction_valid;

    if (native_edit == NULL || native_edit->native_selection_keyboard_active) {
        return;
    }
    previous_direction = native_edit->native_selection_direction;
    previous_direction_valid = native_edit->native_selection_direction_valid;
    native_edit->native_selection_keyboard_active = 1;
    native_edit->native_selection_keyboard_anchor_valid = 0;
    native_edit->native_selection_direction_valid = 0;
    if (!pcore_native_edit_selection_native_range(native_edit,
            &native_start, &native_end)) {
        return;
    }
    shift = native_edit->native_selection_shift_down ||
            GetKeyState(VK_SHIFT) < 0;
    anchor = native_end;
    if (native_start == native_end) {
        anchor = native_start;
    } else if (shift && previous_direction_valid) {
        if (previous_direction ==
                PBROWSER_SCRIPT_CONTENT_SELECTION_FORWARD) {
            anchor = native_start;
        } else if (previous_direction ==
                PBROWSER_SCRIPT_CONTENT_SELECTION_BACKWARD) {
            anchor = native_end;
        }
    } else if (!shift && previous_direction_valid &&
            previous_direction ==
            PBROWSER_SCRIPT_CONTENT_SELECTION_BACKWARD) {
        anchor = native_start;
    }
    native_edit->native_selection_keyboard_anchor = anchor;
    native_edit->native_selection_keyboard_anchor_valid = 1;
}

static void pcore_native_edit_selection_keyboard_direction(
        pcore_native_edit *native_edit)
{
    int native_start;
    int native_end;
    int direction;

    if (native_edit == NULL ||
            !native_edit->native_selection_keyboard_active ||
            !native_edit->native_selection_keyboard_anchor_valid ||
            !pcore_native_edit_selection_native_range(native_edit,
            &native_start, &native_end)) {
        if (native_edit != NULL) {
            native_edit->native_selection_direction_valid = 0;
        }
        return;
    }
    if (native_end <= native_start) {
        direction = PBROWSER_SCRIPT_CONTENT_SELECTION_NONE;
    } else if (native_edit->native_selection_keyboard_anchor <= native_start) {
        direction = PBROWSER_SCRIPT_CONTENT_SELECTION_FORWARD;
    } else if (native_edit->native_selection_keyboard_anchor >= native_end) {
        direction = PBROWSER_SCRIPT_CONTENT_SELECTION_BACKWARD;
    } else {
        native_edit->native_selection_direction_valid = 0;
        return;
    }
    native_edit->native_selection_direction = direction;
    native_edit->native_selection_direction_valid = 1;
}

static void pcore_native_edit_selection_keyboard_update(
        pcore_native_edit *native_edit, int final_update)
{
    if (native_edit == NULL ||
            !native_edit->native_selection_keyboard_active) {
        return;
    }
    pcore_native_edit_selection_keyboard_direction(native_edit);
    pcore_native_edit_selection_changed(native_edit, 1);
    if (final_update) {
        native_edit->native_selection_keyboard_active = 0;
        native_edit->native_selection_keyboard_anchor_valid = 0;
    }
}

