static const char *pcore_browser_script_get_active_element(void *pw)
{
    pcore_browser_script_bridge *bridge;
    int bytes;
    int rc;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || bridge->document == NULL) {
        return "";
    }
    bridge->active_element_id[0] = '\0';
    bytes = 0;
    rc = PCore_InteractionFocusElementId(bridge->document,
            bridge->active_element_id, sizeof(bridge->active_element_id),
            &bytes);
    if (rc != 0 || bytes <= 0) {
        bridge->active_element_id[0] = '\0';
        return "";
    }
    return bridge->active_element_id;
}

static const char *pcore_browser_script_get_interaction_element(void *pw,
        const char *state)
{
    pcore_browser_script_bridge *bridge;
    unsigned int state_flags;
    int bytes;
    int rc;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || bridge->document == NULL || state == NULL) {
        return "";
    }
    if (strcmp(state, PBROWSER_SCRIPT_INTERACTION_ACTIVE) == 0) {
        state_flags = PCORE_INTERACTION_ACTIVE;
    } else if (strcmp(state, PBROWSER_SCRIPT_INTERACTION_HOVER) == 0) {
        state_flags = PCORE_INTERACTION_HOVER;
    } else {
        return "";
    }
    bridge->interaction_element_id[0] = '\0';
    bytes = 0;
    rc = PCore_InteractionStateElementId(bridge->document, state_flags,
            bridge->interaction_element_id,
            sizeof(bridge->interaction_element_id), &bytes);
    if (rc != 0 || bytes <= 0) {
        bridge->interaction_element_id[0] = '\0';
        return "";
    }
    return bridge->interaction_element_id;
}

/* Focus requests originate in the Browser DLL; the reference host only
 * connects an eligible Core target to a native child window when one exists.
 * Suppress the native subclass notifications while doing so because this
 * transaction emits one explicit focus-family pair below. */
static int pcore_browser_script_focus_native_target(
        const PCoreFocusTargetInfo *target)
{
    int old_edit_syncing;
    int old_select_syncing;
    int result;
    int x;
    int y;
    int width;
    int height;
    unsigned int i;

    if (target == NULL) {
        return 0;
    }
    old_edit_syncing = g_native_edit_syncing;
    old_select_syncing = g_native_select_syncing;
    g_native_edit_syncing = 1;
    g_native_select_syncing = 1;
    result = pcore_focus_native_form_control(target->kind,
            target->x + target->width / 2,
            target->y + target->height / 2);
    if (result == 0 && target->kind == PCORE_FOCUS_TARGET_CONTENTEDITABLE) {
        for (i = 0; i < g_native_edit_count; i++) {
            if (g_native_edits[i].hwnd == NULL ||
                    !pcore_native_edit_geometry_info(&g_native_edits[i],
                    &x, &y, &width, &height, NULL, NULL) ||
                    target->x != x || target->y != y ||
                    target->width != width || target->height != height) {
                continue;
            }
            if (IsWindowEnabled(g_native_edits[i].hwnd)) {
                SetFocus(g_native_edits[i].hwnd);
                result = 1;
            }
            break;
        }
    }
    g_native_edit_syncing = old_edit_syncing;
    g_native_select_syncing = old_select_syncing;
    return result;
}

static void pcore_browser_script_focus_move_platform(
        pcore_browser_script_bridge *bridge,
        const PCoreFocusTargetInfo *target, int focus_target)
{
    int old_edit_syncing;
    int old_select_syncing;

    if (bridge == NULL || target == NULL || bridge->document != g_render_doc) {
        return;
    }
    if (focus_target &&
            pcore_browser_script_focus_native_target(target) != 0) {
        return;
    }
    if (bridge->hwnd == NULL || !IsWindow(bridge->hwnd)) {
        return;
    }
    old_edit_syncing = g_native_edit_syncing;
    old_select_syncing = g_native_select_syncing;
    g_native_edit_syncing = 1;
    g_native_select_syncing = 1;
    SetFocus(bridge->hwnd);
    g_native_edit_syncing = old_edit_syncing;
    g_native_select_syncing = old_select_syncing;
}

static void pcore_browser_script_focus_pair(
        const PCoreFocusTargetInfo *target, const char *first,
        const char *second)
{
    int x;
    int y;

    if (target == NULL || first == NULL || second == NULL) {
        return;
    }
    x = target->x + target->width / 2;
    y = target->y + target->height / 2;
    pcore_browser_script_dispatch_focus_at(x, y, first,
            strcmp(first, "focusin") == 0 ||
            strcmp(first, "focusout") == 0);
    pcore_browser_script_dispatch_focus_at(x, y, second,
            strcmp(second, "focusin") == 0 ||
            strcmp(second, "focusout") == 0);
}

/* Reveal an id-addressable target in the page viewport before the focus
 * family is dispatched. This is deliberately a host adapter concern: Core
 * supplies document geometry, while the host owns physical scrolling and
 * native child repositioning. The Browser callback receives the applied CSS
 * coordinates and updates its script viewport only after the native call
 * returns, so this path never re-enters Duktape from inside a callback. */
static void pcore_browser_script_focus_reveal(
        pcore_browser_script_bridge *bridge,
        const PCoreFocusTargetInfo *target, int prevent_scroll,
        PBrowserScriptFocusRequestResult *out_result)
{
    RECT rc;
    int viewport_w;
    int viewport_h;
    int desired_x;
    int desired_y;
    int old_x;
    int old_y;
    int dpi;

    if (out_result != NULL) {
        out_result->scroll_changed = 0;
        out_result->scroll_x = 0;
        out_result->scroll_y = 0;
    }
    if (bridge == NULL || target == NULL || prevent_scroll ||
            bridge != g_browser_script_session.bridge ||
            bridge->document == NULL || bridge->document != g_render_doc ||
            target->width <= 0 || target->height <= 0) {
        return;
    }
    viewport_w = g_view_w;
    viewport_h = g_view_h;
    if (bridge->hwnd != NULL && IsWindow(bridge->hwnd)) {
        GetClientRect(bridge->hwnd, &rc);
        viewport_w = rc.right - rc.left;
        viewport_h = rc.bottom - rc.top;
    }
    if (viewport_w <= 0 || viewport_h <= 0) {
        return;
    }
    old_x = g_scroll_x;
    old_y = g_scroll_y;
    desired_x = old_x;
    desired_y = old_y;
    if (target->width >= viewport_w) {
        desired_x = target->x;
    } else if (target->x < old_x) {
        desired_x = target->x;
    } else if ((long) target->x + target->width >
            (long) old_x + viewport_w) {
        desired_x = target->x + target->width - viewport_w;
    }
    if (target->height >= viewport_h) {
        desired_y = target->y;
    } else if (target->y < old_y) {
        desired_y = target->y;
    } else if ((long) target->y + target->height >
            (long) old_y + viewport_h) {
        desired_y = target->y + target->height - viewport_h;
    }
    if (desired_x != old_x || desired_y != old_y) {
        g_browser_script_scroll_dispatch++;
        (void) pcore_scroll_to_xy(bridge->hwnd, desired_x, desired_y);
        g_browser_script_scroll_dispatch--;
    }
    if (out_result == NULL) {
        return;
    }
    dpi = g_page_scroll_dpi;
    if (dpi <= 0) {
        dpi = 96;
    }
    out_result->scroll_changed = (old_x != g_scroll_x || old_y != g_scroll_y);
    out_result->scroll_x = MulDiv((g_scroll_x >= 0) ? g_scroll_x : 0,
            96, dpi);
    out_result->scroll_y = MulDiv((g_scroll_y >= 0) ? g_scroll_y : 0,
            96, dpi);
}

static int pcore_browser_script_focus_request(void *pw,
        const PBrowserScriptFocusRequestInfoEx *info,
        PBrowserScriptFocusRequestResult *out_result)
{
    pcore_browser_script_bridge *bridge;
    PCoreFocusTargetInfo target;
    PCoreFocusTargetInfo old_target;
    char old_id[PBROWSER_SCRIPT_ACTIVE_ELEMENT_ID_MAX];
    int old_bytes;
    int old_valid;
    int old_target_valid;
    int changed;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || bridge->document == NULL || info == NULL ||
            info->size < sizeof(PBrowserScriptFocusRequestInfoEx) ||
            info->element_id == NULL || info->element_id[0] == '\0' ||
            (info->focused != 0 && info->focused != 1) ||
            (info->prevent_scroll != 0 && info->prevent_scroll != 1)) {
        return -1;
    }
    memset(&target, 0, sizeof(target));
    if (PCore_FocusTargetInfoById(bridge->document, info->element_id,
            &target) != 0) {
        return 0;
    }
    if (info->focused) {
        pcore_browser_script_focus_reveal(bridge, &target,
                info->prevent_scroll, out_result);
    } else if (out_result != NULL) {
        out_result->scroll_changed = 0;
        out_result->scroll_x = 0;
        out_result->scroll_y = 0;
    }
    memset(old_id, 0, sizeof(old_id));
    old_bytes = 0;
    old_valid = PCore_InteractionFocusElementId(bridge->document, old_id,
            sizeof(old_id), &old_bytes) == 0 && old_bytes > 0;
    if (!info->focused) {
        if (!old_valid || strcmp(old_id, info->element_id) != 0) {
            return 0;
        }
        pcore_browser_script_focus_move_platform(bridge, &target, 0);
        pcore_browser_script_focus_pair(&target, "blur", "focusout");
        changed = PCore_InteractionClear(bridge->document,
                PCORE_INTERACTION_FOCUS);
        if (changed < 0) {
            return -1;
        }
        pcore_toggle_focus_clear();
        pcore_button_focus_clear();
        pcore_disclosure_focus_clear();
        pcore_sequential_focus_clear();
        pcore_request_interaction_restyle(bridge->hwnd);
        return 0;
    }
    if (old_valid && strcmp(old_id, info->element_id) == 0) {
        return 0;
    }
    old_target_valid = old_valid &&
            PCore_FocusTargetInfoById(bridge->document, old_id,
            &old_target) == 0;
    if (old_target_valid) {
        pcore_browser_script_focus_pair(&old_target, "blur", "focusout");
    }
    pcore_browser_script_focus_move_platform(bridge, &target, 1);
    changed = PCore_InteractionFocusById(bridge->document,
            info->element_id);
    if (changed < 0) {
        return -1;
    }
    if (changed == 0 && old_valid) {
        return 0;
    }
    pcore_toggle_focus_clear();
    pcore_button_focus_clear();
    pcore_disclosure_focus_clear();
    pcore_sequential_focus_clear();
    pcore_browser_script_focus_pair(&target, "focus", "focusin");
    pcore_request_interaction_restyle(bridge->hwnd);
    return 0;
}

