static int pcore_browser_script_single_window_target_allowed(
        unsigned int target_kind);
static int pcore_browser_script_single_window_target_allowed_context(
        unsigned int target_kind, const char *target,
        const char *context_name);
static int pcore_browser_script_single_window_open_target_allowed(
        unsigned int target_kind, const char *target,
        const char *context_name);

/* Apply Browser-originated window.scrollTo/scrollBy requests to the active
 * host viewport. Candidate documents are intentionally side-effect free:
 * before commit they receive their normalized request back without touching
 * the old page. */
static int pcore_browser_script_scroll(void *pw,
        const PBrowserScriptScrollInfo *info, int *out_x, int *out_y)
{
    pcore_browser_script_bridge *bridge;
    int dpi;
    int device_x;
    int device_y;
    int rc;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || info == NULL ||
            info->size < sizeof(PBrowserScriptScrollInfo) ||
            out_x == NULL || out_y == NULL || info->scroll_x < 0 ||
            info->scroll_y < 0) {
        return -1;
    }
    if (bridge != g_browser_script_session.bridge ||
            bridge->document == NULL || bridge->document != g_render_doc) {
        *out_x = info->scroll_x;
        *out_y = info->scroll_y;
        return 0;
    }
    if (info->element_id != NULL && info->element_id[0] != '\0') {
        rc = PCore_NodeOverflowScrollToById(bridge->document,
                info->element_id, info->scroll_x, info->scroll_y,
                out_x, out_y);
        if (rc == 2) {
            *out_x = 0;
            *out_y = 0;
            return 0;
        }
        if (rc != 0) {
            return -1;
        }
        if (bridge->hwnd != NULL && IsWindow(bridge->hwnd)) {
            pcore_invalidate_overflow(bridge->hwnd);
        }
        return 0;
    }
    dpi = g_page_scroll_dpi;
    if (dpi <= 0) {
        dpi = 96;
    }
    device_x = MulDiv(info->scroll_x, dpi, 96);
    device_y = MulDiv(info->scroll_y, dpi, 96);
    g_browser_script_scroll_dispatch++;
    rc = pcore_scroll_to_xy(bridge->hwnd, device_x, device_y);
    g_browser_script_scroll_dispatch--;
    if (!rc) {
        return -1;
    }
    *out_x = MulDiv((g_scroll_x >= 0) ? g_scroll_x : 0, 96, dpi);
    *out_y = MulDiv((g_scroll_y >= 0) ? g_scroll_y : 0, 96, dpi);
    return 0;
}

static int pcore_browser_script_navigation(void *pw,
        const PBrowserScriptNavigationInfo *info, int *out_value)
{
    pcore_browser_script_bridge *bridge;
    const char *url;
    char normalized_fragment_url[PCORE_SCRIPT_NAVIGATION_URL_MAX];
    char *url_copy;
    char *target_url_copy;
    char *state_copy;
    const char *context_name;
    char captured_context_name[PBROWSER_SCRIPT_WINDOW_NAME_MAX];
    int i;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || info == NULL ||
            info->size < sizeof(PBrowserScriptNavigationInfo) ||
            out_value == NULL) {
        return -1;
    }
    *out_value = 0;
    /* A later script navigation supersedes a queued form POST. Keep the
     * bridge's single pending-navigation slot coherent before recording the
     * new request. */
    free(bridge->navigation_body);
    bridge->navigation_body = NULL;
    bridge->navigation_method = 0;
    if (bridge->navigation_kind == PCORE_SCRIPT_NAVIGATION_FORM) {
        bridge->navigation_kind = PCORE_SCRIPT_NAVIGATION_NONE;
    }
    bridge->navigation_target[0] = '\0';
    bridge->navigation_rel[0] = '\0';
    bridge->navigation_context_name[0] = '\0';
    bridge->navigation_target_kind =
            PBROWSER_SCRIPT_NAVIGATION_TARGET_DEFAULT;
    url = info->url;
    url_copy = NULL;
    target_url_copy = NULL;
    state_copy = NULL;
    context_name = info->context_name;
    captured_context_name[0] = '\0';
    if (info->kind == PBROWSER_SCRIPT_NAVIGATION_REPLACE_STATE) {
        if (bridge->history_url == NULL || url == NULL ||
                info->state_json == NULL || url[0] == '\0' ||
                info->state_json[0] == '\0' ||
                strlen(url) >= PCORE_BROWSE_HISTORY_URL_MAX ||
                strlen(info->state_json) >= PCORE_BROWSE_HISTORY_STATE_MAX ||
                !pcore_browse_history_same_origin_url(
                bridge->history_url, url)) {
            return 0;
        }
        state_copy = pcore_browser_script_copy_string(info->state_json);
        url_copy = pcore_browser_script_copy_string(url);
        if (bridge->hwnd == NULL) {
            target_url_copy = pcore_browser_script_copy_string(url);
        }
        if (state_copy == NULL || url_copy == NULL ||
                (bridge->hwnd == NULL && target_url_copy == NULL) ||
                (bridge->hwnd != NULL &&
                pcore_browse_history_replace_state_url(url,
                info->state_json) != 0)) {
            free(state_copy);
            free(url_copy);
            free(target_url_copy);
            return 0;
        }
        if (bridge->hwnd == NULL && bridge->history_push_count > 0) {
            i = bridge->history_push_count - 1;
            free(bridge->history_push_urls[i]);
            bridge->history_push_urls[i] = target_url_copy;
            free(bridge->history_push_states[i]);
            bridge->history_push_states[i] = state_copy;
        } else {
            if (bridge->hwnd == NULL) {
                free(bridge->history_entry_url);
                bridge->history_entry_url = target_url_copy;
            }
            free(bridge->history_state_json);
            bridge->history_state_json = state_copy;
            bridge->history_state_changed = 1;
        }
        free(bridge->history_url);
        bridge->history_url = url_copy;
        return 1;
    }
    if (info->kind == PBROWSER_SCRIPT_NAVIGATION_PUSH_STATE) {
        if (!bridge->history_can_commit || bridge->history_url == NULL ||
                url == NULL || info->state_json == NULL ||
                url[0] == '\0' || info->state_json[0] == '\0' ||
                strlen(url) >= PCORE_BROWSE_HISTORY_URL_MAX ||
                strlen(info->state_json) >= PCORE_BROWSE_HISTORY_STATE_MAX ||
                !pcore_browse_history_same_origin_url(
                url, bridge->history_url)) {
            return 0;
        }
        state_copy = pcore_browser_script_copy_string(info->state_json);
        url_copy = pcore_browser_script_copy_string(url);
        if (bridge->hwnd == NULL) {
            target_url_copy = pcore_browser_script_copy_string(url);
        }
        if (state_copy == NULL || url_copy == NULL ||
                (bridge->hwnd == NULL && target_url_copy == NULL)) {
            free(state_copy);
            free(url_copy);
            free(target_url_copy);
            return 0;
        }
        if (bridge->hwnd != NULL) {
            if (pcore_browse_history_push_state(url, info->state_json) != 0) {
                free(state_copy);
                free(url_copy);
                free(target_url_copy);
                return 0;
            }
            bridge->history_length = g_browse_history.count;
            bridge->history_index = g_browse_history.index;
            free(bridge->history_state_json);
            bridge->history_state_json = state_copy;
            bridge->history_state_changed = 1;
        } else {
            if (bridge->history_push_count >= PCORE_BROWSE_HISTORY_MAX) {
                free(bridge->history_push_urls[0]);
                free(bridge->history_push_states[0]);
                for (i = 1; i < bridge->history_push_count; i++) {
                    bridge->history_push_urls[i - 1] =
                            bridge->history_push_urls[i];
                    bridge->history_push_states[i - 1] =
                            bridge->history_push_states[i];
                }
                bridge->history_push_count--;
            }
            bridge->history_push_urls[bridge->history_push_count] =
                    target_url_copy;
            bridge->history_push_states[bridge->history_push_count] =
                    state_copy;
            bridge->history_push_count++;
            if (bridge->history_index + 1 < bridge->history_length) {
                bridge->history_length = bridge->history_index + 1;
            }
            if (bridge->history_length >= PCORE_BROWSE_HISTORY_MAX) {
                bridge->history_length--;
                bridge->history_index--;
            }
            bridge->history_length++;
            bridge->history_index = bridge->history_length - 1;
        }
        free(bridge->history_url);
        bridge->history_url = url_copy;
        *out_value = bridge->history_length;
        return 1;
    }
    if (info->kind == PBROWSER_SCRIPT_NAVIGATION_BACK ||
            info->kind == PBROWSER_SCRIPT_NAVIGATION_FORWARD ||
            info->kind == PBROWSER_SCRIPT_NAVIGATION_GO) {
        free(bridge->navigation_url);
        bridge->navigation_url = NULL;
        bridge->navigation_kind = (info->kind ==
                PBROWSER_SCRIPT_NAVIGATION_BACK) ?
                PCORE_SCRIPT_NAVIGATION_BACK :
                (info->kind == PBROWSER_SCRIPT_NAVIGATION_FORWARD) ?
                PCORE_SCRIPT_NAVIGATION_FORWARD :
                PCORE_SCRIPT_NAVIGATION_GO;
        bridge->navigation_delta = info->delta;
        if (bridge->hwnd != NULL) {
            (void) PostMessage(bridge->hwnd, WM_PCORE_SCRIPT_NAVIGATE,
                    0, 0);
        }
        return 1;
    }
    if (info->kind != PBROWSER_SCRIPT_NAVIGATION_ASSIGN &&
            info->kind != PBROWSER_SCRIPT_NAVIGATION_RELOAD &&
            info->kind != PBROWSER_SCRIPT_NAVIGATION_REPLACE &&
            info->kind != PBROWSER_SCRIPT_NAVIGATION_FRAGMENT &&
            info->kind != PBROWSER_SCRIPT_NAVIGATION_FRAGMENT_REPLACE &&
            info->kind != PBROWSER_SCRIPT_NAVIGATION_OPEN) {
        return -1;
    }
    if (url == NULL || url[0] == '\0' ||
            strlen(url) >= PCORE_SCRIPT_NAVIGATION_URL_MAX) {
        return 0;
    }
    if ((info->target != NULL &&
            strlen(info->target) >= PBROWSER_SCRIPT_ANCHOR_TARGET_MAX) ||
            (info->rel != NULL &&
            strlen(info->rel) >= PBROWSER_SCRIPT_ANCHOR_REL_MAX) ||
            (info->context_name != NULL &&
            strlen(info->context_name) >= PBROWSER_SCRIPT_WINDOW_NAME_MAX)) {
        return 0;
    }
    if (info->kind != PBROWSER_SCRIPT_NAVIGATION_OPEN &&
            info->target_kind == PBROWSER_SCRIPT_NAVIGATION_TARGET_NAMED &&
            context_name == NULL) {
        if (pcore_browser_script_capture_window_name(
                captured_context_name, sizeof(captured_context_name))) {
            context_name = captured_context_name;
        } else if (g_browser_script_context_window_name[0] != '\0') {
            context_name = g_browser_script_context_window_name;
        }
    }
    if (info->kind == PBROWSER_SCRIPT_NAVIGATION_OPEN &&
            !pcore_browser_script_single_window_open_target_allowed(
            info->target_kind, info->target, info->context_name)) {
        return 0;
    }
    if (info->kind != PBROWSER_SCRIPT_NAVIGATION_OPEN && bridge->hwnd != NULL &&
            !pcore_browser_script_single_window_target_allowed_context(
            info->target_kind, info->target, context_name)) {
        return 0;
    }
    normalized_fragment_url[0] = '\0';
    if (info->kind == PBROWSER_SCRIPT_NAVIGATION_FRAGMENT ||
            info->kind == PBROWSER_SCRIPT_NAVIGATION_FRAGMENT_REPLACE) {
        if (!pcore_browser_script_normalize_fragment_url(bridge, url,
                normalized_fragment_url,
                sizeof(normalized_fragment_url))) {
            return 0;
        }
        url = normalized_fragment_url;
    }
    if ((info->kind == PBROWSER_SCRIPT_NAVIGATION_FRAGMENT ||
            info->kind == PBROWSER_SCRIPT_NAVIGATION_FRAGMENT_REPLACE) &&
            (!bridge->history_can_commit || bridge->history_url == NULL ||
            !pcore_browse_history_same_base_url(
            bridge->history_url, url))) {
        return 0;
    }
    url_copy = pcore_browser_script_copy_string(url);
    if (url_copy == NULL) {
        return 0;
    }
    free(bridge->navigation_url);
    bridge->navigation_url = url_copy;
    if (info->kind == PBROWSER_SCRIPT_NAVIGATION_OPEN) {
        bridge->navigation_kind = PCORE_SCRIPT_NAVIGATION_OPEN;
    } else if (info->kind == PBROWSER_SCRIPT_NAVIGATION_ASSIGN) {
        bridge->navigation_kind = PCORE_SCRIPT_NAVIGATION_ASSIGN;
    } else if (info->kind == PBROWSER_SCRIPT_NAVIGATION_RELOAD) {
        bridge->navigation_kind = PCORE_SCRIPT_NAVIGATION_RELOAD;
    } else if (info->kind == PBROWSER_SCRIPT_NAVIGATION_REPLACE) {
        bridge->navigation_kind = PCORE_SCRIPT_NAVIGATION_REPLACE;
    } else if (info->kind == PBROWSER_SCRIPT_NAVIGATION_FRAGMENT) {
        bridge->navigation_kind = PCORE_SCRIPT_NAVIGATION_FRAGMENT;
    } else {
        bridge->navigation_kind = PCORE_SCRIPT_NAVIGATION_FRAGMENT_REPLACE;
    }
    bridge->navigation_delta = 0;
    if (info->target != NULL) {
        memcpy(bridge->navigation_target, info->target,
                strlen(info->target) + 1);
    }
    if (info->rel != NULL) {
        memcpy(bridge->navigation_rel, info->rel,
                strlen(info->rel) + 1);
    }
    bridge->navigation_target_kind = info->target_kind;
    if (context_name != NULL) {
        memcpy(bridge->navigation_context_name, context_name,
                strlen(context_name) + 1);
    }
    if (bridge->hwnd != NULL) {
        (void) PostMessage(bridge->hwnd, WM_PCORE_SCRIPT_NAVIGATE,
                0, 0);
    }
    return 1;
}

/* This host currently owns exactly one browsing context. Current-context
 * target keywords can therefore be honored directly; a named target is also
 * safe only when it exactly matches the active context name. _blank and
 * unknown names require a future window manager and must not silently replace
 * the active document. The browser DLL already performed the bounded keyword
 * classification, so this consumer does not duplicate string parsing. */
static int pcore_browser_script_single_window_target_allowed(
        unsigned int target_kind)
{
    return pcore_browser_script_single_window_target_allowed_context(
            target_kind, NULL, NULL);
}

static int pcore_browser_script_single_window_target_allowed_context(
        unsigned int target_kind, const char *target,
        const char *context_name)
{
    if (target_kind == PBROWSER_SCRIPT_NAVIGATION_TARGET_DEFAULT ||
            target_kind == PBROWSER_SCRIPT_NAVIGATION_TARGET_SELF ||
            target_kind == PBROWSER_SCRIPT_NAVIGATION_TARGET_PARENT ||
            target_kind == PBROWSER_SCRIPT_NAVIGATION_TARGET_TOP) {
        return 1;
    }
    return target_kind == PBROWSER_SCRIPT_NAVIGATION_TARGET_NAMED &&
            target != NULL && target[0] != '\0' &&
            context_name != NULL && context_name[0] != '\0' &&
            strcmp(target, context_name) == 0;
}

/* window.open() without a window manager may only reuse the active context.
 * DEFAULT means a new unnamed context in the Web API, so it is deliberately
 * rejected here even though an anchor with no target may use the current
 * single window. A non-keyword name is safe only when it names this exact
 * current context; another name still requires a future window manager. */
static int pcore_browser_script_single_window_open_target_allowed(
        unsigned int target_kind, const char *target,
        const char *context_name)
{
    return target_kind != PBROWSER_SCRIPT_NAVIGATION_TARGET_DEFAULT &&
            pcore_browser_script_single_window_target_allowed_context(
            target_kind, target, context_name);
}

static unsigned int pcore_browser_script_event_callback(void *pw,
        const PCoreEventInfo *event_info)
{
    pcore_browser_script_event_binding *binding;
    PBrowserScriptEventInfo browser_event;
    unsigned int action;

    binding = (pcore_browser_script_event_binding *) pw;
    if (binding == NULL || binding->bridge == NULL ||
            binding->bridge->session == NULL || event_info == NULL ||
            !pcore_browser_script_event_type_safe(binding->event_type)) {
        return PCORE_EVENT_ACTION_NONE;
    }
    memset(&browser_event, 0, sizeof(browser_event));
    browser_event.size = sizeof(browser_event);
    browser_event.phase = event_info->phase;
    browser_event.bubbles = event_info->bubbles;
    browser_event.cancelable = event_info->cancelable;
    browser_event.trusted = event_info->trusted;
    browser_event.default_prevented = event_info->default_prevented;
    browser_event.key = event_info->key;
    browser_event.key_code = event_info->key_code;
    browser_event.char_code = event_info->char_code;
    browser_event.repeat = event_info->repeat;
    browser_event.shift = event_info->shift;
    browser_event.ctrl = event_info->ctrl;
    browser_event.alt = event_info->alt;
    browser_event.input_type = event_info->input_type;
    browser_event.data = event_info->data;
    browser_event.is_composing = event_info->is_composing;
    browser_event.target_id = event_info->target_id;
    browser_event.current_target_id = event_info->current_target_id;
    action = PBrowser_ScriptSessionDispatchEvent(binding->bridge->session,
            binding->id, binding->event_type, &browser_event);
    if ((action & PBROWSER_SCRIPT_EVENT_ACTION_PREVENT_DEFAULT) != 0) {
        return PCORE_EVENT_ACTION_PREVENT_DEFAULT;
    }
    return PCORE_EVENT_ACTION_NONE;
}

static unsigned int pcore_browser_script_add_event_listener(void *pw,
        const char *element_id, const char *event_type, int capture)
{
    pcore_browser_script_bridge *bridge;
    pcore_browser_script_event_binding *binding;
    HANDLE listener;
    unsigned int id;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || bridge->document == NULL || element_id == NULL ||
            element_id[0] == '\0' ||
            !pcore_browser_script_event_type_safe(event_type)) {
        return 0;
    }
    binding = (pcore_browser_script_event_binding *) calloc(1,
            sizeof(*binding));
    if (binding == NULL) {
        return 0;
    }
    binding->bridge = bridge;
    binding->element_id = pcore_browser_script_copy_string(element_id);
    binding->event_type = pcore_browser_script_copy_string(event_type);
    if (binding->element_id == NULL || binding->event_type == NULL) {
        free(binding->element_id);
        free(binding->event_type);
        free(binding);
        return 0;
    }
    id = bridge->next_event_id;
    if (id == 0) {
        id = 1;
    }
    bridge->next_event_id = id + 1;
    binding->id = id;
    listener = PCore_EventListenerAdd(bridge->document,
            binding->element_id, binding->event_type, capture,
            pcore_browser_script_event_callback, binding);
    if (listener == NULL) {
        free(binding->element_id);
        free(binding->event_type);
        free(binding);
        return 0;
    }
    binding->listener = listener;
    binding->next = bridge->events;
    bridge->events = binding;
    return id;
}

static int pcore_browser_script_remove_event_listener(void *pw,
        unsigned int listener_id)
{
    pcore_browser_script_bridge *bridge;
    pcore_browser_script_event_binding *binding;
    pcore_browser_script_event_binding *previous;
    int removed;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || bridge->document == NULL || listener_id == 0) {
        return 0;
    }
    previous = NULL;
    binding = bridge->events;
    while (binding != NULL && binding->id != listener_id) {
        previous = binding;
        binding = binding->next;
    }
    if (binding == NULL) {
        return 0;
    }
    if (previous != NULL) {
        previous->next = binding->next;
    } else {
        bridge->events = binding->next;
    }
    removed = PCore_EventListenerRemove(bridge->document,
            binding->listener);
    free(binding->element_id);
    free(binding->event_type);
    free(binding);
    return removed > 0 ? 1 : 0;
}

static void pcore_browser_script_bridge_destroy(
        pcore_browser_script_bridge *bridge)
{
    pcore_browser_script_event_binding *binding;
    pcore_browser_script_event_binding *next;
    int i;

    if (bridge == NULL) {
        return;
    }
    binding = bridge->events;
    while (binding != NULL) {
        next = binding->next;
        if (bridge->document != NULL && binding->listener != NULL) {
            PCore_EventListenerRemove(bridge->document,
                    binding->listener);
        }
        free(binding->element_id);
        free(binding->event_type);
        free(binding);
        binding = next;
    }
    bridge->events = NULL;
    free(bridge->navigation_url);
    bridge->navigation_url = NULL;
    free(bridge->navigation_body);
    bridge->navigation_body = NULL;
    bridge->navigation_method = 0;
    bridge->navigation_target[0] = '\0';
    bridge->navigation_rel[0] = '\0';
    bridge->navigation_context_name[0] = '\0';
    bridge->navigation_target_kind =
            PBROWSER_SCRIPT_NAVIGATION_TARGET_DEFAULT;
    free(bridge->history_url);
    bridge->history_url = NULL;
    free(bridge->history_entry_url);
    bridge->history_entry_url = NULL;
    free(bridge->history_state_json);
    bridge->history_state_json = NULL;
    free(bridge->programmatic_click_element_id);
    bridge->programmatic_click_element_id = NULL;
    bridge->history_state_changed = 0;
    for (i = 0; i < bridge->history_push_count; i++) {
        free(bridge->history_push_urls[i]);
        bridge->history_push_urls[i] = NULL;
        free(bridge->history_push_states[i]);
        bridge->history_push_states[i] = NULL;
    }
    bridge->history_push_count = 0;
    if (bridge->session != NULL) {
        PBrowser_ScriptSessionDestroy(bridge->session);
        bridge->session = NULL;
    }
    bridge->runtime = NULL;
}

static int pcore_browser_script_type_equal(const char *type, int length,
        const char *expected)
{
    int i;
    char a;
    char b;

    if ((int) strlen(expected) != length) {
        return 0;
    }
    for (i = 0; i < length; i++) {
        a = type[i];
        b = expected[i];
        if (a >= 'A' && a <= 'Z') {
            a = (char) (a + ('a' - 'A'));
        }
        if (a != b) {
            return 0;
        }
    }
    return 1;
}

static int pcore_browser_script_type_supported(const char *type)
{
    const char *start;
    const char *end;
    int length;

    if (type == NULL) {
        return 1;
    }
    start = type;
    while (*start == ' ' || *start == '\t' || *start == '\r' ||
            *start == '\n') {
        start++;
    }
    end = start + strlen(start);
    while (end > start && (end[-1] == ' ' || end[-1] == '\t' ||
            end[-1] == '\r' || end[-1] == '\n')) {
        end--;
    }
    length = (int) (end - start);
    return length == 0 ||
            pcore_browser_script_type_equal(start, length,
                    "text/javascript") ||
            pcore_browser_script_type_equal(start, length,
                    "application/javascript") ||
            pcore_browser_script_type_equal(start, length,
                    "text/ecmascript") ||
            pcore_browser_script_type_equal(start, length,
                    "application/ecmascript");
}

static void pcore_browser_script_error(char *error, int error_capacity,
        const char *stage, const char *detail)
{
    if (error == NULL || error_capacity <= 0) {
        return;
    }
    _snprintf(error, error_capacity - 1, "%s: %s", stage,
            (detail != NULL && detail[0] != '\0') ? detail : "failed");
    error[error_capacity - 1] = '\0';
}

static int pcore_browser_script_session_evaluate(const char *source,
        int source_len, char *error, int error_capacity)
{
    if (g_browser_script_session.document == NULL ||
            g_browser_script_session.bridge == NULL ||
            g_browser_script_session.bridge->session == NULL ||
            g_browser_script_session.bridge->document !=
                    g_browser_script_session.document) {
        pcore_browser_script_error(error, error_capacity,
                "persistent script context", "not available");
        return 1;
    }
    if (PBrowser_ScriptSessionEvaluate(
            g_browser_script_session.bridge->session, source,
            source_len) != PSCRIPT_OK) {
        pcore_browser_script_error(error, error_capacity,
                "persistent script evaluation",
                PBrowser_ScriptSessionGetError(
                g_browser_script_session.bridge->session));
        return 1;
    }
    return 0;
}

static int pcore_browser_script_session_traverse_history(int target_index)
{
    pcore_browser_script_bridge *bridge;
    const char *state_json;
    const char *target_url;
    char *state_copy;
    char *final_copy;
    char *target_copy;
    char *old_url;
    int old_index;

    bridge = g_browser_script_session.bridge;
    if (!pcore_browse_history_same_document_target(target_index) ||
            bridge == NULL || bridge->session == NULL) {
        return 1;
    }
    state_json = pcore_browse_history_state_at(target_index);
    target_url = g_browse_history.entries[target_index];
    state_copy = pcore_browser_script_copy_string(state_json);
    target_copy = pcore_browser_script_copy_string(target_url);
    if (state_copy == NULL || target_copy == NULL) {
        free(state_copy);
        free(target_copy);
        return 1;
    }
    pcore_browse_history_save_scroll();
    old_index = g_browse_history.index;
    if (pcore_browse_history_commit_target(target_index) != 0) {
        free(state_copy);
        free(target_copy);
        return 1;
    }
    old_url = bridge->history_url;
    bridge->history_url = target_copy;
    if (PBrowser_ScriptSessionDispatchHistoryTraversal(bridge->session,
            state_json, target_url) != PSCRIPT_OK) {
        (void) pcore_browse_history_commit_target(old_index);
        free(bridge->history_url);
        bridge->history_url = old_url;
        free(state_copy);
        return 1;
    }
    /* Same-document fragment entries keep the current document alive, so
     * traversal must restore the target viewport just like a fresh fragment
     * navigation. Non-fragment pushState entries restore their host-owned
     * saved position; unknown fragments deliberately leave the existing
     * position unchanged. */
    if (strchr(target_url, '#') != NULL) {
        (void) pcore_browser_script_scroll_to_fragment(bridge->hwnd,
                target_url);
    } else {
        (void) pcore_browse_history_restore_scroll(bridge->hwnd,
                target_index);
    }
    free(old_url);
    final_copy = pcore_browser_script_copy_string(
            pcore_browse_history_current_state());
    if (final_copy != NULL) {
        free(state_copy);
        state_copy = final_copy;
    }
    free(bridge->history_state_json);
    bridge->history_state_json = state_copy;
    bridge->history_state_changed = 1;
    bridge->history_length = g_browse_history.count;
    bridge->history_index = g_browse_history.index;
    return 0;
}

static int pcore_browser_script_session_navigate_fragment(const char *url,
        int replace_current)
{
    pcore_browser_script_bridge *bridge;
    char *url_copy;
    char *state_copy;
    int new_length;

    bridge = g_browser_script_session.bridge;
    if (bridge == NULL || bridge->session == NULL ||
            url == NULL || url[0] == '\0' ||
            strlen(url) >= PCORE_BROWSE_HISTORY_URL_MAX ||
            pcore_browse_history_current() == NULL ||
            !pcore_browse_history_same_base_url(
            pcore_browse_history_current(), url)) {
        return 1;
    }
    if (strcmp(pcore_browse_history_current(), url) == 0) {
        return 0;
    }
    url_copy = pcore_browser_script_copy_string(url);
    state_copy = pcore_browser_script_copy_string("null");
    if (url_copy == NULL || state_copy == NULL) {
        free(url_copy);
        free(state_copy);
        return 1;
    }
    new_length = g_browse_history.count;
    if (!replace_current) {
        if (g_browse_history.index + 1 < new_length) {
            new_length = g_browse_history.index + 1;
        }
        if (new_length >= PCORE_BROWSE_HISTORY_MAX) {
            new_length--;
        }
        new_length++;
    }
    if ((replace_current ?
            pcore_browse_history_replace_state_url(url, "null") :
            pcore_browse_history_push_state(url, "null")) != 0) {
        free(url_copy);
        free(state_copy);
        return 1;
    }
    free(bridge->history_url);
    bridge->history_url = url_copy;
    free(bridge->history_state_json);
    bridge->history_state_json = state_copy;
    bridge->history_state_changed = 1;
    bridge->history_length = g_browse_history.count;
    bridge->history_index = g_browse_history.index;
    if (PBrowser_ScriptSessionDispatchHashNavigation(bridge->session,
            url, bridge->history_length) != PSCRIPT_OK) {
        return 1;
    }
    (void) pcore_browser_script_scroll_to_fragment(bridge->hwnd, url);
    return 0;
}

static int pcore_browser_execute_scripts_with_history(HANDLE document,
        int enabled, int allow_external, const char *document_url,
        int history_length, int history_index, int history_can_commit,
        const char *history_state_json,
        PCoreResolveUrlFn resolve, void *resolve_pw, int *out_executed,
        int *out_ignored, char *error, int error_capacity,
        HANDLE *out_runtime, pcore_browser_script_bridge **out_bridge)
{
    pcore_browser_script_bridge bridge_storage;
    pcore_browser_script_bridge *bridge;
    PCoreScriptInfo info;
    HANDLE session;
    HANDLE runtime;
    PBrowserScriptDomReadCallbacks dom_read_callbacks;
    PBrowserScriptActiveElementCallbacks active_element_callbacks;
    PBrowserScriptInteractionCallbacksEx interaction_callbacks;
    PBrowserScriptFocusRequestCallbacksEx focus_request_callbacks;
    PBrowserScriptDomRelationCallbacks dom_relation_callbacks;
    PBrowserScriptDomWriteCallbacks dom_write_callbacks;
    PBrowserScriptContentEditableCallbacks content_editable_callbacks;
    PBrowserScriptContentEditableSelectionCallbacks
            content_editable_selection_callbacks;
    PBrowserScriptDomValueCallbacks dom_value_callbacks;
    PBrowserScriptDomCheckedCallbacks dom_checked_callbacks;
    PBrowserScriptFormCallbacks form_callbacks;
    PBrowserScriptOptionCallbacks option_callbacks;
    PBrowserScriptFormDataCallbacksEx form_data_callbacks;
    PBrowserScriptFormResetCallbacks form_reset_callbacks;
    PBrowserScriptFormSubmitCallbacks form_submit_callbacks;
    PBrowserScriptFormSubmitDirectCallbacks form_submit_direct_callbacks;
    PBrowserScriptValidationCallbacks validation_callbacks;
    PBrowserScriptReportValidityCallbacks report_validity_callbacks;
    PBrowserScriptCustomValidityCallbacks custom_validity_callbacks;
    PBrowserScriptInputCallbacks input_callbacks;
    PBrowserScriptKeyCallbacks key_callbacks;
    PBrowserScriptFocusCallbacks focus_callbacks;
    PBrowserScriptEditCallbacks edit_callbacks;
    PBrowserScriptNativeEditCallbacksEx native_edit_callbacks_ex;
    PBrowserScriptSelectCallbacks select_callbacks;
    PBrowserScriptNativeSelectCallbacksEx native_select_callbacks_ex;
    PBrowserScriptClickCallbacks click_callbacks;
    PBrowserScriptProgrammaticClickCallbacksEx
            programmatic_click_callbacks_ex;
    PBrowserScriptProgrammaticAnchorCallbacks
            programmatic_anchor_callbacks;
    PBrowserScriptFormEventCallbacks form_event_callbacks;
    PBrowserScriptFormEventCallbacksEx form_event_callbacks_ex;
    PBrowserScriptInvalidCallbacks invalid_callbacks;
    PBrowserScriptNavigationCallbacks navigation_callbacks;
    PBrowserScriptScrollCallbacks scroll_callbacks;
    PBrowserScriptDomAttributeCallbacks dom_attribute_callbacks;
    PBrowserScriptEventCallbacks event_callbacks;
    char *source;
    char *type;
    const char *data;
    const char *runtime_error;
    int count;
    int executed;
    int ignored;
    int rc;
    int i;
    int host_dpi;
    int initial_window_name_rc;
    double viewport_width;
    double viewport_height;
    double device_pixel_ratio;

    if (out_executed != NULL) {
        *out_executed = 0;
    }
    if (out_ignored != NULL) {
        *out_ignored = 0;
    }
    if (error != NULL && error_capacity > 0) {
        error[0] = '\0';
    }
    if (out_runtime != NULL) {
        *out_runtime = NULL;
    }
    if (out_bridge != NULL) {
        *out_bridge = NULL;
    }
    if (!enabled) {
        return 0;
    }
    count = PCore_GetScriptCount(document);
    if (count < 0) {
        pcore_browser_script_error(error, error_capacity,
                "inline script enumeration", NULL);
        return 1;
    }
    if (count == 0) {
        return 0;
    }
    /* Browser bootstrap is a large, product-owned selector/DOM program on
     * the slow WM6 CPU. Keep the page budget bounded while allowing the
     * reference host enough headroom for its one-time parse. */
    session = PBrowser_ScriptSessionCreate(PSCRIPT_DEFAULT_BUDGET_MS * 4UL);
    runtime = PBrowser_ScriptSessionRuntime(session);
    if (session == NULL || runtime == NULL) {
        PBrowser_ScriptSessionDestroy(session);
        pcore_browser_script_error(error, error_capacity,
                "runtime creation", NULL);
        return 1;
    }
    if (out_runtime != NULL) {
        bridge = (pcore_browser_script_bridge *) malloc(sizeof(*bridge));
        if (bridge == NULL) {
            PBrowser_ScriptSessionDestroy(session);
            pcore_browser_script_error(error, error_capacity,
                    "script bridge allocation", NULL);
            return 1;
        }
    } else {
        bridge = &bridge_storage;
    }
    bridge->document = document;
    bridge->session = session;
    bridge->runtime = runtime;
    bridge->hwnd = NULL;
    bridge->navigation_kind = PCORE_SCRIPT_NAVIGATION_NONE;
    bridge->navigation_delta = 0;
    bridge->navigation_method = 0;
    bridge->navigation_url = NULL;
    bridge->navigation_body = NULL;
    bridge->navigation_target[0] = '\0';
    bridge->navigation_rel[0] = '\0';
    bridge->navigation_target_kind =
            PBROWSER_SCRIPT_NAVIGATION_TARGET_DEFAULT;
    bridge->history_url = pcore_browser_script_copy_string(
            (document_url != NULL) ? document_url : "");
    bridge->history_entry_url = pcore_browser_script_copy_string(
            (document_url != NULL) ? document_url : "");
    bridge->history_state_json = NULL;
    bridge->history_state_changed = 0;
    bridge->history_push_count = 0;
    for (i = 0; i < PCORE_BROWSE_HISTORY_MAX; i++) {
        bridge->history_push_urls[i] = NULL;
        bridge->history_push_states[i] = NULL;
    }
    bridge->next_event_id = 1;
    bridge->events = NULL;
    bridge->programmatic_click_element_id = NULL;
    bridge->active_element_id[0] = '\0';
    bridge->interaction_element_id[0] = '\0';
    bridge->visited_url_count = 0;
    memset(bridge->visited_urls, 0, sizeof(bridge->visited_urls));
    dom_read_callbacks.size = sizeof(dom_read_callbacks);
    dom_read_callbacks.pw = bridge;
    dom_read_callbacks.has_element = pcore_browser_script_dom_has_element;
    dom_read_callbacks.get_text = pcore_browser_script_dom_get_text;
    active_element_callbacks.size = sizeof(active_element_callbacks);
    active_element_callbacks.pw = bridge;
    active_element_callbacks.get_active_element =
            pcore_browser_script_get_active_element;
    interaction_callbacks.size = sizeof(interaction_callbacks);
    interaction_callbacks.pw = bridge;
    interaction_callbacks.get_interaction_element =
            pcore_browser_script_get_interaction_element;
    interaction_callbacks.get_link_visited =
            pcore_browser_script_get_link_visited;
    focus_request_callbacks.size = sizeof(focus_request_callbacks);
    focus_request_callbacks.pw = bridge;
    focus_request_callbacks.request_focus =
            pcore_browser_script_focus_request;
    dom_relation_callbacks.size = sizeof(dom_relation_callbacks);
    dom_relation_callbacks.pw = bridge;
    dom_relation_callbacks.get_relation =
            pcore_browser_script_dom_get_relation;
    dom_write_callbacks.size = sizeof(dom_write_callbacks);
    dom_write_callbacks.pw = bridge;
    dom_write_callbacks.set_text = pcore_browser_script_dom_set_text;
    content_editable_callbacks.size = sizeof(content_editable_callbacks);
    content_editable_callbacks.pw = bridge;
    content_editable_callbacks.get_editable =
            pcore_browser_script_content_editable_get;
    content_editable_callbacks.set_text =
            pcore_browser_script_content_editable_set;
    content_editable_selection_callbacks.size =
            sizeof(content_editable_selection_callbacks);
    content_editable_selection_callbacks.pw = bridge;
    content_editable_selection_callbacks.get_selection =
            pcore_browser_script_content_editable_selection_get;
    content_editable_selection_callbacks.set_selection =
            pcore_browser_script_content_editable_selection_set;
    dom_value_callbacks.size = sizeof(dom_value_callbacks);
    dom_value_callbacks.pw = bridge;
    dom_value_callbacks.get_value = pcore_browser_script_dom_get_value;
    dom_value_callbacks.set_value = pcore_browser_script_dom_set_value;
    dom_checked_callbacks.size = sizeof(dom_checked_callbacks);
    dom_checked_callbacks.pw = bridge;
    dom_checked_callbacks.get_checked = pcore_browser_script_dom_get_checked;
    dom_checked_callbacks.set_checked = pcore_browser_script_dom_set_checked;
    form_callbacks.size = sizeof(form_callbacks);
    form_callbacks.pw = bridge;
    form_callbacks.get_default_value =
            pcore_browser_script_dom_get_default_value;
    form_callbacks.set_default_value =
            pcore_browser_script_dom_set_default_value;
    form_callbacks.get_default_checked =
            pcore_browser_script_dom_get_default_checked;
    form_callbacks.set_default_checked =
            pcore_browser_script_dom_set_default_checked;
    form_callbacks.get_selected_index =
            pcore_browser_script_dom_get_selected_index;
    form_callbacks.set_selected_index =
            pcore_browser_script_dom_set_selected_index;
    option_callbacks.size = sizeof(option_callbacks);
    option_callbacks.pw = bridge;
    option_callbacks.get_selected =
            pcore_browser_script_dom_get_option_selected;
    option_callbacks.set_selected =
            pcore_browser_script_dom_set_option_selected;
    option_callbacks.get_default_selected =
            pcore_browser_script_dom_get_option_default_selected;
    option_callbacks.set_default_selected =
            pcore_browser_script_dom_set_option_default_selected;
    form_data_callbacks.size = sizeof(form_data_callbacks);
    form_data_callbacks.pw = bridge;
    form_data_callbacks.get_count = pcore_browser_script_form_data_count_ex;
    form_data_callbacks.get_entry = pcore_browser_script_form_data_entry_ex;
    form_reset_callbacks.size = sizeof(form_reset_callbacks);
    form_reset_callbacks.pw = bridge;
    form_reset_callbacks.reset_form = pcore_browser_script_dom_reset_form;
    form_submit_callbacks.size = sizeof(form_submit_callbacks);
    form_submit_callbacks.pw = bridge;
    form_submit_callbacks.validate_submit =
            pcore_browser_script_form_submit_validate;
    form_submit_callbacks.submit_form =
            pcore_browser_script_form_submit_default;
    form_submit_direct_callbacks.size = sizeof(form_submit_direct_callbacks);
    form_submit_direct_callbacks.pw = bridge;
    form_submit_direct_callbacks.submit_form =
            pcore_browser_script_form_submit_direct;
    validation_callbacks.size = sizeof(validation_callbacks);
    validation_callbacks.pw = bridge;
    validation_callbacks.get_validation =
            pcore_browser_script_dom_get_validation;
    report_validity_callbacks.size = sizeof(report_validity_callbacks);
    report_validity_callbacks.pw = bridge;
    report_validity_callbacks.report_validity =
            pcore_browser_script_dom_report_validity;
    custom_validity_callbacks.size = sizeof(custom_validity_callbacks);
    custom_validity_callbacks.pw = bridge;
    custom_validity_callbacks.get_message =
            pcore_browser_script_dom_get_custom_validity;
    custom_validity_callbacks.set_message =
            pcore_browser_script_dom_set_custom_validity;
    input_callbacks.size = sizeof(input_callbacks);
    input_callbacks.pw = bridge;
    input_callbacks.dispatch_input = pcore_browser_script_input_dispatch;
    key_callbacks.size = sizeof(key_callbacks);
    key_callbacks.pw = bridge;
    key_callbacks.dispatch_key = pcore_browser_script_key_dispatch;
    focus_callbacks.size = sizeof(focus_callbacks);
    focus_callbacks.pw = bridge;
    focus_callbacks.dispatch_focus = pcore_browser_script_focus_dispatch;
    edit_callbacks.size = sizeof(edit_callbacks);
    edit_callbacks.pw = bridge;
    edit_callbacks.dispatch_edit = pcore_browser_script_edit_dispatch;
    native_edit_callbacks_ex.size = sizeof(native_edit_callbacks_ex);
    native_edit_callbacks_ex.pw = bridge;
    native_edit_callbacks_ex.dispatch_input =
            pcore_browser_script_input_dispatch;
    native_edit_callbacks_ex.dispatch_change =
            pcore_browser_script_edit_dispatch;
    select_callbacks.size = sizeof(select_callbacks);
    select_callbacks.pw = bridge;
    select_callbacks.dispatch_select = pcore_browser_script_select_dispatch;
    native_select_callbacks_ex.size = sizeof(native_select_callbacks_ex);
    native_select_callbacks_ex.pw = bridge;
    native_select_callbacks_ex.dispatch_select =
            pcore_browser_script_native_select_dispatch;
    click_callbacks.size = sizeof(click_callbacks);
    click_callbacks.pw = bridge;
    click_callbacks.dispatch_click = pcore_browser_script_click_dispatch;
    programmatic_click_callbacks_ex.size =
            sizeof(programmatic_click_callbacks_ex);
    programmatic_click_callbacks_ex.pw = bridge;
    programmatic_click_callbacks_ex.get_target =
            pcore_browser_script_programmatic_click_target;
    programmatic_click_callbacks_ex.validate_submit =
            pcore_browser_script_programmatic_click_validate;
    programmatic_click_callbacks_ex.perform_default =
            pcore_browser_script_programmatic_click_default;
    programmatic_click_callbacks_ex.dispatch_generic =
            pcore_browser_script_programmatic_click_dispatch;
    programmatic_anchor_callbacks.size =
            sizeof(programmatic_anchor_callbacks);
    programmatic_anchor_callbacks.pw = bridge;
    programmatic_anchor_callbacks.get_target =
            pcore_browser_script_programmatic_anchor_target;
    form_event_callbacks.size = sizeof(form_event_callbacks);
    form_event_callbacks.pw = bridge;
    form_event_callbacks.dispatch_form_event =
            pcore_browser_script_form_event_dispatch;
    form_event_callbacks_ex.size = sizeof(form_event_callbacks_ex);
    form_event_callbacks_ex.pw = bridge;
    form_event_callbacks_ex.dispatch_form_event =
            pcore_browser_script_form_event_dispatch_by_id;
    invalid_callbacks.size = sizeof(invalid_callbacks);
    invalid_callbacks.pw = bridge;
    invalid_callbacks.dispatch_invalid = pcore_browser_script_invalid_dispatch;
    navigation_callbacks.size = sizeof(navigation_callbacks);
    navigation_callbacks.pw = bridge;
    navigation_callbacks.navigate = pcore_browser_script_navigation;
    scroll_callbacks.size = sizeof(scroll_callbacks);
    scroll_callbacks.pw = bridge;
    scroll_callbacks.scroll = pcore_browser_script_scroll;
    dom_attribute_callbacks.size = sizeof(dom_attribute_callbacks);
    dom_attribute_callbacks.pw = bridge;
    dom_attribute_callbacks.get_attribute =
            pcore_browser_script_dom_get_attribute;
    dom_attribute_callbacks.set_attribute =
            pcore_browser_script_dom_set_attribute;
    dom_attribute_callbacks.remove_attribute =
            pcore_browser_script_dom_remove_attribute;
    event_callbacks.size = sizeof(event_callbacks);
    event_callbacks.pw = bridge;
    event_callbacks.add_listener = pcore_browser_script_add_event_listener;
    event_callbacks.remove_listener =
            pcore_browser_script_remove_event_listener;
    if (history_length < 1 || history_length > PCORE_BROWSE_HISTORY_MAX) {
        history_length = 1;
    }
    if (history_index < 0 || history_index >= history_length) {
        history_index = history_length - 1;
    }
    bridge->history_length = history_length;
    bridge->history_index = history_index;
    bridge->history_can_commit = history_can_commit;
    if (history_state_json == NULL) {
        history_state_json = "null";
    }
    host_dpi = test_host_device_dpi();
    if (host_dpi <= 0) {
        host_dpi = 96;
    }
    viewport_width = (double) GetSystemMetrics(SM_CXSCREEN) * 96.0 /
            (double) host_dpi;
    viewport_height = (double) GetSystemMetrics(SM_CYSCREEN) * 96.0 /
            (double) host_dpi;
    device_pixel_ratio = (double) host_dpi / 96.0;
    initial_window_name_rc = PBrowser_ScriptSessionSetGlobalString(session,
            "__pcoreWindowName", g_browser_script_initial_window_name);
    g_browser_script_initial_window_name[0] = '\0';
    if (bridge->history_url == NULL || bridge->history_entry_url == NULL ||
            initial_window_name_rc != PSCRIPT_OK ||
            PBrowser_ScriptSessionSetGlobalString(session,
            "__pcoreDocumentUrl",
            (document_url != NULL) ? document_url : "") != PSCRIPT_OK ||
            PBrowser_ScriptSessionSetGlobalNumber(session,
            "__pcoreHistoryLength", (double) history_length) != PSCRIPT_OK ||
            PBrowser_ScriptSessionSetGlobalJson(session,
            "__pcoreHistoryState", history_state_json) != PSCRIPT_OK ||
            PBrowser_ScriptSessionSetGlobalNumber(session,
            "__pcoreViewportWidth", viewport_width) != PSCRIPT_OK ||
            PBrowser_ScriptSessionSetGlobalNumber(session,
            "__pcoreViewportHeight", viewport_height) != PSCRIPT_OK ||
            PBrowser_ScriptSessionSetGlobalNumber(session,
            "__pcoreDevicePixelRatio", device_pixel_ratio) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterDomReadCallbacks(session,
            &dom_read_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterDomRelationCallbacks(session,
            &dom_relation_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterDomWriteCallbacks(session,
            &dom_write_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterContentEditableCallbacks(session,
            &content_editable_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterContentEditableSelectionCallbacks(
            session, &content_editable_selection_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterDomValueCallbacks(session,
            &dom_value_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterDomCheckedCallbacks(session,
            &dom_checked_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterFormCallbacks(session,
            &form_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterOptionCallbacks(session,
            &option_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterFormDataCallbacksEx(session,
            &form_data_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterFormResetCallbacks(session,
            &form_reset_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterFormSubmitCallbacks(session,
            &form_submit_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterFormSubmitDirectCallbacks(session,
            &form_submit_direct_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterValidationCallbacks(session,
            &validation_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterReportValidityCallbacks(session,
            &report_validity_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterCustomValidityCallbacks(session,
            &custom_validity_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterInputCallbacks(session,
            &input_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterKeyCallbacks(session,
            &key_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterFocusCallbacks(session,
            &focus_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterEditCallbacks(session,
            &edit_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterNativeEditCallbacksEx(session,
            &native_edit_callbacks_ex) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterSelectCallbacks(session,
            &select_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterNativeSelectCallbacksEx(session,
            &native_select_callbacks_ex) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterClickCallbacks(session,
            &click_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterProgrammaticClickCallbacksEx(session,
            &programmatic_click_callbacks_ex) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterProgrammaticAnchorCallbacks(session,
            &programmatic_anchor_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterFormEventCallbacks(session,
            &form_event_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterFormEventCallbacksEx(session,
            &form_event_callbacks_ex) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterInvalidCallbacks(session,
            &invalid_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterDomAttributeCallbacks(session,
            &dom_attribute_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterEventCallbacks(session,
            &event_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterNavigationCallbacks(session,
            &navigation_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionRegisterScrollCallbacks(session,
            &scroll_callbacks) != PSCRIPT_OK ||
            PBrowser_ScriptSessionEvaluateBootstrap(session) != PSCRIPT_OK) {
        pcore_browser_script_error(error, error_capacity, "DOM bootstrap",
                PBrowser_ScriptSessionGetError(session));
        pcore_browser_script_bridge_destroy(bridge);
        if (out_runtime != NULL) {
            free(bridge);
        }
        return 1;
    }
    if (PBrowser_ScriptSessionRegisterActiveElementCallbacks(session,
            &active_element_callbacks) != PSCRIPT_OK) {
        pcore_browser_script_error(error, error_capacity,
                "activeElement bridge", PBrowser_ScriptSessionGetError(session));
        pcore_browser_script_bridge_destroy(bridge);
        if (out_runtime != NULL) {
            free(bridge);
        }
        return 1;
    }
    if (PBrowser_ScriptSessionRegisterInteractionElementCallbacksEx(session,
            &interaction_callbacks) != PSCRIPT_OK) {
        pcore_browser_script_error(error, error_capacity,
                "interaction selector bridge", PBrowser_ScriptSessionGetError(
                session));
        pcore_browser_script_bridge_destroy(bridge);
        if (out_runtime != NULL) {
            free(bridge);
        }
        return 1;
    }
    if (PBrowser_ScriptSessionRegisterFocusRequestCallbacksEx(session,
            &focus_request_callbacks) != PSCRIPT_OK) {
        pcore_browser_script_error(error, error_capacity,
                "focus request bridge", PBrowser_ScriptSessionGetError(
                session));
        pcore_browser_script_bridge_destroy(bridge);
        if (out_runtime != NULL) {
            free(bridge);
        }
        return 1;
    }
    executed = 0;
    ignored = 0;
    rc = 0;
    source = NULL;
    type = NULL;
    for (i = 0; i < count; i++) {
        memset(&info, 0, sizeof(info));
        data = NULL;
        if (PCore_GetScript(document, (unsigned int) i, document_url,
                resolve, resolve_pw, &info, NULL, 0, NULL, 0, NULL, 0,
                &data) != 0 || info.source_bytes < 0 ||
                info.type_bytes < 0 || info.url_bytes < 0 ||
                info.data_bytes < 0) {
            pcore_browser_script_error(error, error_capacity,
                    "script metadata", NULL);
            rc = 1;
            break;
        }
        if (info.kind == 2 && !allow_external) {
            ignored++;
            continue;
        }
        if (info.kind == 2 && !info.available) {
            ignored++;
            continue;
        }
        source = (info.kind == 1) ?
                (char *) malloc((size_t) info.source_bytes + 1) : NULL;
        type = (char *) malloc((size_t) info.type_bytes + 1);
        if ((info.kind == 1 && source == NULL) || type == NULL ||
                PCore_GetScript(document, (unsigned int) i, document_url,
                        resolve, resolve_pw, &info, source,
                        info.source_bytes + 1, NULL, 0, type,
                        info.type_bytes + 1, &data) != 0) {
            free(source);
            free(type);
            source = NULL;
            type = NULL;
            pcore_browser_script_error(error, error_capacity, "script copy",
                    NULL);
            rc = 1;
            break;
        }
        if (pcore_browser_script_type_supported(type) &&
                ((info.kind == 1 && source != NULL) ||
                (info.kind == 2 && data != NULL))) {
            if (PBrowser_ScriptSessionEvaluate(session,
                    (info.kind == 1) ? source : data,
                    (info.kind == 1) ? info.source_bytes : info.data_bytes) !=
                    PSCRIPT_OK) {
                runtime_error = PBrowser_ScriptSessionGetError(session);
                pcore_browser_script_error(error, error_capacity,
                        "script evaluation", runtime_error);
                rc = 1;
            } else {
                executed++;
            }
        } else {
            ignored++;
        }
        free(source);
        free(type);
        source = NULL;
        type = NULL;
    }
    if (rc == 0 && PBrowser_ScriptSessionDispatchPageLifecycle(
            session, "complete") != PSCRIPT_OK) {
        pcore_browser_script_error(error, error_capacity,
                "page lifecycle", PBrowser_ScriptSessionGetError(session));
        rc = 1;
    }
    if (out_runtime != NULL) {
        *out_runtime = runtime;
        if (out_bridge != NULL) {
            *out_bridge = bridge;
        }
    } else {
        pcore_browser_script_bridge_destroy(bridge);
    }
    if (out_executed != NULL) {
        *out_executed = executed;
    }
    if (out_ignored != NULL) {
        *out_ignored = ignored;
    }
    return rc;
}

static int pcore_browser_execute_scripts(HANDLE document, int enabled,
        int allow_external, const char *document_url,
        PCoreResolveUrlFn resolve, void *resolve_pw, int *out_executed,
        int *out_ignored, char *error, int error_capacity,
        HANDLE *out_runtime, pcore_browser_script_bridge **out_bridge)
{
    return pcore_browser_execute_scripts_with_history(document, enabled,
            allow_external, document_url,
            pcore_browse_history_exposed_length(),
            g_browse_history.index, 1,
            pcore_browse_history_current_state(), resolve, resolve_pw,
            out_executed, out_ignored, error, error_capacity, out_runtime,
            out_bridge);
}

static int pcore_browser_execute_inline_scripts(HANDLE document, int enabled,
        int *out_executed, int *out_ignored, char *error,
        int error_capacity)
{
    return pcore_browser_execute_scripts(document, enabled, 0, NULL, NULL,
            NULL, out_executed, out_ignored, error, error_capacity,
            NULL, NULL);
}

/* Run one UI-owned commit phase, then yield to the WM message queue. A missing
 * callback body queues the URL and returns MORE for another worker stage. */
static int pcore_navigation_commit_step(HWND hwnd,
        pcore_navigation_request *request, int report_errors)
{
    PHttpResponse *resp;
    RECT           rc;
    int            cw, chh;
    char           emsg[320];
    char           document_url[1536];
    char           captured_window_name[PBROWSER_SCRIPT_WINDOW_NAME_MAX];
    WCHAR          script_debug[384];
    DWORD          started;
    DWORD          elapsed;
    int            script_executed;
    int            script_ignored;
    int            style_result;
    PBrowserNavigationCommitInfo commit_info;
    int            history_commit_rc;

    if (request->commit_stage == PCORE_NAV_COMMIT_PARSE) {
        resp = request->response;
        if (pcore_navigation_response_error(request, emsg,
                sizeof(emsg))) {
            if (report_errors) {
                show_error(L"Navigation failed", emsg);
            }
            return PCORE_NAV_RESULT_FAILED;
        }
        started = GetTickCount();
        request->document = PCore_ParseHTML(resp->body, resp->body_len);
        elapsed = GetTickCount() - started;
        request->stats.parse_ms += elapsed;
        if (elapsed > request->stats.max_ui_slice_ms) {
            request->stats.max_ui_slice_ms = elapsed;
        }
        PHttp_FreeResponse(resp);
        request->response = NULL;
        if (request->document == NULL) {
            if (report_errors) {
                show_error(L"Navigation failed",
                        "PCore_ParseHTML returned NULL");
            }
            return PCORE_NAV_RESULT_FAILED;
        }
        request->commit_stage = PCORE_NAV_COMMIT_SCRIPT;
        return PCORE_NAV_RESULT_CONTINUE;
    }

    if (request->commit_stage == PCORE_NAV_COMMIT_SCRIPT) {
        script_executed = 0;
        script_ignored = 0;
        document_url[0] = '\0';
        if (g_browser_javascript_enabled) {
            if (g_browser_script_session.session != NULL) {
                if (pcore_browser_script_capture_window_name(
                        captured_window_name, sizeof(captured_window_name))) {
                    cstr_copy(g_browser_script_context_window_name,
                            sizeof(g_browser_script_context_window_name),
                            captured_window_name);
                } else {
                    /* Do not let an unreadable/overlong name from the old
                     * document leak into a later named-target admission. */
                    g_browser_script_context_window_name[0] = '\0';
                }
            }
            cstr_copy(g_browser_script_initial_window_name,
                    sizeof(g_browser_script_initial_window_name),
                    g_browser_script_context_window_name);
        }
        request->resource_policy = PCORE_NAV_RESOURCE_OPTIONAL;
        request->resource_role_mask = PCORE_NAV_RESOURCE_ROLE_SCRIPT;
        if (g_browser_javascript_enabled &&
                pcore_document_url(request->host, request->path,
                request->port, document_url, sizeof(document_url)) == 0 &&
                PCore_FetchScriptResourcesEx(request->document, document_url,
                wm_combine_url, pcore_navigation_resource_cb,
                page_resource_free_cb, request, NULL, NULL) != 0) {
            pcore_browser_script_error(emsg, sizeof(emsg),
                    "script resource discovery", NULL);
        }
        request->resource_policy = PCORE_NAV_RESOURCE_OPTIONAL;
        request->resource_role_mask = PCORE_NAV_RESOURCE_ROLE_NONE;
        if (g_browser_javascript_enabled &&
                pcore_navigation_pending_count(request) > 0) {
            request->worker_stage = PCORE_NAV_STAGE_RESOURCES;
            request->worker_resume_stage = PCORE_NAV_COMMIT_SCRIPT;
            return PCORE_NAV_RESULT_MORE;
        }
        if (pcore_browser_execute_scripts_with_history(request->document,
                g_browser_javascript_enabled, 1,
                document_url[0] != '\0' ? document_url : NULL,
                pcore_browse_history_navigation_length(
                document_url[0] != '\0' ? document_url : NULL,
                request->method, request->history_target_index),
                pcore_browse_history_navigation_index(
                document_url[0] != '\0' ? document_url : NULL,
                request->method, request->history_target_index),
                request->method == 1,
                pcore_browse_history_navigation_state(
                document_url[0] != '\0' ? document_url : NULL,
                request->method, request->history_target_index),
                wm_combine_url, request, &script_executed, &script_ignored,
                emsg, sizeof(emsg), &request->script_runtime,
                &request->script_bridge) != 0) {
            utf8_to_wide(emsg, -1, script_debug,
                    sizeof(script_debug) / sizeof(script_debug[0]));
            OutputDebugStringW(L"Positron inline script error: ");
            OutputDebugStringW(script_debug);
            OutputDebugStringW(L"\r\n");
        }
        if (request->script_bridge != NULL) {
            request->script_bridge->hwnd = hwnd;
        }
        request->commit_stage = PCORE_NAV_COMMIT_STYLE;
        return PCORE_NAV_RESULT_CONTINUE;
    }

    if (request->commit_stage == PCORE_NAV_COMMIT_STYLE) {
        rc.left = 0;
        rc.top = 0;
        rc.right = 224;
        rc.bottom = 320;
        if (hwnd != NULL) {
            GetClientRect(hwnd, &rc);
        }
        cw = rc.right - rc.left;
        chh = rc.bottom - rc.top;
        if (cw <= 0) { cw = 224; }
        if (chh <= 0) { chh = 320; }
        test_host_set_device_viewport(cw, chh);
        started = GetTickCount();
        style_result = pcore_document_url(request->host, request->path,
                request->port, document_url, sizeof(document_url));
        if (style_result == 0) {
            request->resource_policy = PCORE_NAV_RESOURCE_REQUIRED;
            request->resource_role_mask =
                    PCORE_NAV_RESOURCE_ROLE_STYLESHEET;
            style_result = PCore_StyleDocumentEx2(request->document, NULL,
                    document_url, wm_combine_url,
                    pcore_navigation_resource_cb, page_resource_free_cb,
                    request);
            request->resource_policy = PCORE_NAV_RESOURCE_OPTIONAL;
            request->resource_role_mask = PCORE_NAV_RESOURCE_ROLE_NONE;
        }
        if (style_result != 0) {
            /* A terminal required-resource failure can make Core's style
             * pass return nonzero before the later image-stage gate. Refresh
             * the Browser-owned gate here so old-page preservation remains
             * observable and the host does not lose the failure reason. */
            (void) pcore_navigation_resource_commit_gate(request);
            elapsed = GetTickCount() - started;
            request->stats.style_ms += elapsed;
            if (elapsed > request->stats.max_ui_slice_ms) {
                request->stats.max_ui_slice_ms = elapsed;
            }
            if (report_errors) {
                show_error(L"Navigation failed",
                        "PCore_StyleDocument failed");
            }
            return PCORE_NAV_RESULT_FAILED;
        }
        request->resource_policy = PCORE_NAV_RESOURCE_OPTIONAL;
        elapsed = GetTickCount() - started;
        request->stats.style_ms += elapsed;
        if (elapsed > request->stats.max_ui_slice_ms) {
            request->stats.max_ui_slice_ms = elapsed;
        }
        if (pcore_navigation_pending_count(request) > 0) {
            request->worker_stage = PCORE_NAV_STAGE_RESOURCES;
            request->worker_resume_stage = PCORE_NAV_COMMIT_STYLE;
            return PCORE_NAV_RESULT_MORE;
        }
        request->commit_stage = PCORE_NAV_COMMIT_IMAGES;
        return PCORE_NAV_RESULT_CONTINUE;
    }

    if (request->commit_stage == PCORE_NAV_COMMIT_IMAGES) {
        started = GetTickCount();
        request->resource_policy = PCORE_NAV_RESOURCE_OPTIONAL;
        request->resource_role_mask = PCORE_NAV_RESOURCE_ROLE_IMAGE;
        (void) PCore_FetchImageResources(request->document,
                pcore_navigation_resource_cb, page_resource_free_cb,
                request, NULL, NULL);
        request->resource_policy = PCORE_NAV_RESOURCE_OPTIONAL;
        request->resource_role_mask = PCORE_NAV_RESOURCE_ROLE_NONE;
        elapsed = GetTickCount() - started;
        request->stats.images_ms += elapsed;
        if (elapsed > request->stats.max_ui_slice_ms) {
            request->stats.max_ui_slice_ms = elapsed;
        }
        if (pcore_navigation_pending_count(request) > 0) {
            request->worker_stage = PCORE_NAV_STAGE_RESOURCES;
            request->worker_resume_stage = PCORE_NAV_COMMIT_STYLE;
            request->commit_stage = PCORE_NAV_COMMIT_STYLE;
            return PCORE_NAV_RESULT_MORE;
        }
        memset(&commit_info, 0, sizeof(commit_info));
        if (pcore_navigation_commit_info(request, &commit_info) != 0) {
            if (report_errors) {
                show_error(L"Navigation failed",
                        "Could not inspect the navigation commit gate");
            }
            return PCORE_NAV_RESULT_FAILED;
        }
        (void) pcore_navigation_resource_stats_sync(request);
        if (commit_info.decision != PBROWSER_NAVIGATION_COMMIT_READY) {
            if (report_errors) {
                if (commit_info.decision ==
                        PBROWSER_NAVIGATION_COMMIT_REQUIRED_FAILED) {
                    show_error(L"Navigation failed",
                            "Required navigation resource failed");
                } else if (commit_info.decision ==
                        PBROWSER_NAVIGATION_COMMIT_RESOURCE_CANCELLED) {
                    show_error(L"Navigation cancelled",
                            "Navigation resource work was cancelled");
                } else if (commit_info.decision ==
                        PBROWSER_NAVIGATION_COMMIT_CANDIDATE_STALE) {
                    show_error(L"Navigation superseded",
                            "The navigation candidate is no longer current");
                } else if (commit_info.decision ==
                        PBROWSER_NAVIGATION_COMMIT_CANDIDATE_CANCELLED ||
                        commit_info.decision ==
                        PBROWSER_NAVIGATION_COMMIT_CANDIDATE_CANCEL_REQUESTED) {
                    show_error(L"Navigation cancelled",
                            "The navigation candidate was cancelled");
                } else {
                    show_error(L"Navigation failed",
                            "Navigation commit prerequisites are incomplete");
                }
            }
            return PCORE_NAV_RESULT_FAILED;
        }
        request->commit_stage = PCORE_NAV_COMMIT_LAYOUT;
        return PCORE_NAV_RESULT_CONTINUE;
    }

    if (request->commit_stage != PCORE_NAV_COMMIT_LAYOUT) {
        if (report_errors) {
            show_error(L"Navigation failed", "Invalid UI commit stage");
        }
        return PCORE_NAV_RESULT_FAILED;
    }
    memset(&commit_info, 0, sizeof(commit_info));
    if (pcore_navigation_commit_info(request, &commit_info) != 0 ||
            commit_info.decision != PBROWSER_NAVIGATION_COMMIT_READY) {
        if (report_errors) {
            show_error(L"Navigation superseded",
                    "Navigation commit prerequisites changed before layout");
        }
        return PCORE_NAV_RESULT_FAILED;
    }
    (void) pcore_navigation_resource_stats_sync(request);
    rc.left = 0;
    rc.top = 0;
    rc.right = 224;
    rc.bottom = 320;
    if (hwnd != NULL) {
        GetClientRect(hwnd, &rc);
    }
    cw = rc.right - rc.left;
    chh = rc.bottom - rc.top;
    if (cw <= 0) { cw = 224; }
    if (chh <= 0) { chh = 320; }
    started = GetTickCount();
    if (PCore_LayoutDocument(request->document, cw, chh) != 0) {
        elapsed = GetTickCount() - started;
        request->stats.layout_ms += elapsed;
        if (elapsed > request->stats.max_ui_slice_ms) {
            request->stats.max_ui_slice_ms = elapsed;
        }
        if (report_errors) {
            show_error(L"Navigation failed", "PCore_LayoutDocument failed");
        }
        return PCORE_NAV_RESULT_FAILED;
    }
    elapsed = GetTickCount() - started;
    request->stats.layout_ms += elapsed;
    if (elapsed > request->stats.max_ui_slice_ms) {
        request->stats.max_ui_slice_ms = elapsed;
    }
    request->stats.core_layout_valid =
            PCore_GetLayoutStats(request->document,
                    &request->stats.core_layout) == 0;
    request->stats.core_box_valid =
            PCore_GetBoxStats(request->document,
                    &request->stats.core_box) == 0;
    request->stats.core_image_valid =
            PCore_GetImageDecodeStats(request->document,
                    &request->stats.core_image) == 0;
    pcore_navigation_observe_fallbacks(request);

    /* A successful cross-document commit is the last moment when the old
     * script session and document are both alive. Give the old page one
     * cancelable beforeunload boundary first; a rejection leaves the old page,
     * its session and its pending work untouched and fails this candidate. */
    if (!pcore_browser_script_beforeunload_allows_close(report_errors)) {
        return PCORE_NAV_RESULT_FAILED;
    }
    /* The beforeunload check passed. Let the product Browser dispatch its
     * one-shot visibility/pagehide/unload boundary and clear page-owned
     * queues before native children and the old DOM are released. A failed
     * candidate never reaches this point, so the visible page keeps its
     * session and pending work. */
    if (g_browser_script_session.session != NULL) {
        (void) PBrowser_ScriptSessionDispatchPageTeardown(
                g_browser_script_session.session);
    }

    /* Swap in the new document; native children must release their old DOM
     * indices before the document they describe is freed. */
    pcore_native_edits_destroy();
    pcore_native_selects_destroy();
    pcore_browser_script_session_destroy();
    if (g_render_doc != NULL) {
        PCore_FreeDocument(g_render_doc);
    }
    g_render_doc = request->document;
    request->document = NULL;
    g_browser_script_session.document = g_render_doc;
    g_browser_script_session.session = (request->script_bridge != NULL) ?
            request->script_bridge->session : NULL;
    g_browser_script_session.runtime = request->script_runtime;
    g_browser_script_session.bridge = request->script_bridge;
    request->script_runtime = NULL;
    request->script_bridge = NULL;
    g_render_sheet = NULL;
    g_doc_w = PCore_DocumentWidth(g_render_doc);
    g_doc_h = PCore_DocumentHeight(g_render_doc);
    pcore_browse_history_save_scroll();
    g_scroll_x = 0;
    g_scroll_y = 0;
    cstr_copy(g_cur_host, sizeof(g_cur_host), request->host);
    cstr_copy(g_cur_path, sizeof(g_cur_path), request->path);
    g_cur_port = request->port;
    if (request->method == 1 &&
            pcore_document_url(request->host, request->path,
                    request->port, document_url,
                    sizeof(document_url)) == 0) {
        history_commit_rc = pcore_browse_history_commit_navigation_with_bridge(
                document_url, request->method,
                request->history_target_index,
                g_browser_script_session.bridge);
        if (history_commit_rc == 0 &&
                request->history_target_index >= 0) {
            (void) pcore_browse_history_restore_scroll(hwnd,
                    request->history_target_index);
        }
    }

    pcore_set_scrollbar(hwnd);
    pcore_native_edits_rebuild(hwnd, 0);
    pcore_native_selects_rebuild(hwnd, 0);
    started = GetTickCount();
    InvalidateRect(hwnd, NULL, TRUE);
    UpdateWindow(hwnd);
    elapsed = GetTickCount() - started;
    request->stats.first_paint_ms += elapsed;
    if (elapsed > request->stats.max_ui_slice_ms) {
        request->stats.max_ui_slice_ms = elapsed;
    }
    request->stats.completed = 1;
    return PCORE_NAV_RESULT_DONE;
}

static void pcore_navigation_finish(HWND hwnd,
        pcore_navigation_request *request)
{
    (void) pcore_navigation_resource_commit_gate(request);
    request->stats.total_ms = GetTickCount() - request->stats.started_tick;
    (void) pcore_navigation_resource_stats_sync(request);
    if (!request->stats.completed &&
            request->resource_transaction != NULL) {
        /* A failed or superseded request owns no visible page. Settle any
         * remaining pending entries before observing the release boundary so
         * destroying the transaction cannot abandon worker-owned state. */
        (void) PBrowser_NavigationResourceCancelAll(
                request->resource_transaction);
        (void) pcore_navigation_resource_commit_gate(request);
        (void) pcore_navigation_resource_stats_sync(request);
    }
    request->stats.resources_pending =
            pcore_navigation_resource_pending_total(request);
    /* Browser owns the candidate terminal state. The host records timing
     * and performs platform cleanup, but it cannot turn a failed or stale
     * request into a committed page. */
    if (request->candidate != NULL) {
        if (request->stats.completed) {
            (void) PBrowser_NavigationCandidateMarkCommitted(
                    request->candidate, (unsigned long) g_nav_generation);
        } else {
            (void) PBrowser_NavigationCandidateMarkFailed(
                    request->candidate);
        }
    }
    (void) pcore_navigation_cleanup_capture(request);
    g_nav_last_stats = request->stats;
    g_nav_last_stats_valid = 1;
    testbench_log_navigation(request);
    if (g_testbench_auto && g_testbench_browse_active) {
        if (request->stats.completed) {
            g_testbench_browse_completed++;
        } else {
            g_testbench_browse_failed = 1;
        }
    }
    if (hwnd != NULL) {
        pcore_navigation_set_loading(hwnd, 0);
    } else {
        g_nav_loading = 0;
        g_nav_determinate = 0;
    }
    if (hwnd != NULL && g_browser_script_session.bridge != NULL &&
            g_browser_script_session.bridge->navigation_kind !=
                    PCORE_SCRIPT_NAVIGATION_NONE) {
        (void) PostMessage(hwnd, WM_PCORE_SCRIPT_NAVIGATE, 0, 0);
    }
    if (request == g_nav_request) {
        g_nav_request = NULL;
    }
    pcore_navigation_request_free(request);
    if (hwnd != NULL && g_testbench_auto && g_testbench_browse_active) {
        PostMessage(hwnd, g_testbench_browse_failed ?
                WM_CLOSE : WM_TESTBENCH_NAVIGATE, 0, 0);
    }
}

static int pcore_navigation_post_continue(HWND hwnd,
        pcore_navigation_request *request)
{
    g_nav_determinate = 0;
    g_nav_phase = 0;
    if (g_nav_bar != NULL) {
        SendMessage(g_nav_bar, PBM_SETPOS, 0, 0);
    }
    (void) request;
    return SetTimer(hwnd, PCORE_NAV_COMMIT_TIMER, 1, NULL) != 0 ? 0 : 1;
}

static pcore_navigation_request *pcore_navigation_request_create_ex(
        HWND hwnd, const char *href, int method, const void *body,
        int body_len, const char *content_type)
{
    pcore_navigation_request *request;
    size_t href_len;
    size_t content_type_len;

    if (href == NULL) {
        return NULL;
    }
    href_len = strlen(href);
    if (href_len >= sizeof(request->path)) {
        return NULL;
    }
    request = (pcore_navigation_request *) malloc(sizeof(*request));
    if (request == NULL) {
        return NULL;
    }
    memset(request, 0, sizeof(*request));
    if (pcore_navigation_resource_ensure(request) != 0) {
        free(request);
        return NULL;
    }
    request->port = 443;
    request->history_target_index = PCORE_BROWSE_HISTORY_TARGET_NEW;
    if (!resolve_url(href, request->host, sizeof(request->host),
            request->path, sizeof(request->path), &request->port)) {
        pcore_navigation_request_free(request);
        return NULL;
    }
    request->method = (method == 2 || method == 3) ? method : 1;
    if (request->method == 2 || request->method == 3) {
        if (body_len < 0 || (body_len > 0 && body == NULL)) {
            pcore_navigation_request_free(request);
            return NULL;
        }
        request->request_body = (char *) malloc((size_t) body_len + 1);
        if (request->request_body == NULL) {
            pcore_navigation_request_free(request);
            return NULL;
        }
        if (body_len > 0) {
            memcpy(request->request_body, body, (size_t) body_len);
        }
        request->request_body[body_len] = '\0';
        request->request_body_len = body_len;
        if (content_type != NULL) {
            content_type_len = strlen(content_type);
            request->request_content_type = (char *) malloc(
                    content_type_len + 1);
            if (request->request_content_type == NULL) {
                pcore_navigation_request_free(request);
                return NULL;
            }
            memcpy(request->request_content_type, content_type,
                    content_type_len + 1);
        }
    }
    request->hwnd = hwnd;
    request->worker_stage = PCORE_NAV_STAGE_DOCUMENT;
    request->commit_stage = PCORE_NAV_COMMIT_NONE;
    request->stats.started_tick = GetTickCount();
    request->stats.cleanup_decision = -1;
    request->stats.cleanup_candidate_result = -1;
    request->stats.cleanup_resource_gate = -1;
    request->stats.cleanup_resource_pending = -1;
    return request;
}

static pcore_navigation_request *pcore_navigation_request_create(
        HWND hwnd, const char *href, int method, const char *body)
{
    int body_len;

    body_len = (body != NULL) ? (int) strlen(body) : 0;
    return pcore_navigation_request_create_ex(hwnd, href, method,
            body, body_len, NULL);
}

/* Start the main-document stage. Later stages reuse this request for external
 * CSS/image GETs while the old visible document remains interactive. */
static int navigate_to_request_ex(HWND hwnd, const char *href,
        int method, const void *body, int body_len,
        const char *content_type, int history_target_index)
{
    pcore_navigation_request *request;
    int superseded;

    superseded = 0;
    if (g_nav_loading) {
        if (pcore_navigation_retired_count() >= PCORE_NAV_RETIRED_MAX) {
            show_error(L"Navigation busy",
                    "Too many superseded navigations are still shutting down");
            return 1;
        }
        /* A newer navigation supersedes the current candidate. Keep the
         * visible document untouched; the old request is retired until its
         * worker completion message closes the worker and frees its owned
         * response/resources. */
        pcore_navigation_cancel_active();
        superseded = 1;
    }
    request = pcore_navigation_request_create_ex(hwnd, href, method,
            body, body_len, content_type);
    if (request == NULL) {
        if (superseded) {
            pcore_navigation_set_loading(hwnd, 0);
        }
        show_error(L"Navigation failed",
                "Invalid URL, oversized form target, or out of memory");
        return 1;
    }
    request->history_target_index = history_target_index;
    if (pcore_navigation_request_assign_generation(request, NULL) != 0) {
        if (superseded) {
            pcore_navigation_set_loading(hwnd, 0);
        }
        show_error(L"Navigation failed", "Candidate allocation failed");
        pcore_navigation_request_free(request);
        return 1;
    }
    g_nav_request = request;
    pcore_navigation_set_loading(hwnd, 1);
    if (pcore_navigation_start_worker(request) != 0) {
        pcore_navigation_set_loading(hwnd, 0);
        g_nav_request = NULL;
        pcore_navigation_request_free(request);
        show_error(L"Navigation failed", "CreateThread failed");
        return 1;
    }
    return 0;
}

static void navigate_to_request(HWND hwnd, const char *href,
        int method, const char *body)
{
    int body_len;

    body_len = (body != NULL) ? (int) strlen(body) : 0;
    (void) navigate_to_request_ex(hwnd, href, method, body, body_len,
            NULL, PCORE_BROWSE_HISTORY_TARGET_NEW);
}

static void navigate_to(HWND hwnd, const char *href)
{
    navigate_to_request(hwnd, href, 1, NULL);
}

static void navigate_replace(HWND hwnd, const char *href)
{
    (void) navigate_to_request_ex(hwnd, href, 1, NULL, 0, NULL,
            PCORE_BROWSE_HISTORY_TARGET_REPLACE_CURRENT);
}

static int pcore_browse_navigate_back(HWND hwnd)
{
    const char *target;
    int target_index;

    if (g_nav_loading) {
        return 0;
    }
    target = pcore_browse_history_back_target(&target_index);
    if (target == NULL) {
        return 0;
    }
    if (pcore_browse_history_same_document_target(target_index)) {
        return pcore_browser_script_session_traverse_history(
                target_index) == 0;
    }
    return navigate_to_request_ex(hwnd, target, 1, NULL, 0, NULL,
            target_index) == 0;
}

static int pcore_browse_navigate_forward(HWND hwnd)
{
    const char *target;
    int target_index;

    if (g_nav_loading) {
        return 0;
    }
    target = pcore_browse_history_forward_target(&target_index);
    if (target == NULL) {
        return 0;
    }
    if (pcore_browse_history_same_document_target(target_index)) {
        return pcore_browser_script_session_traverse_history(
                target_index) == 0;
    }
    return navigate_to_request_ex(hwnd, target, 1, NULL, 0, NULL,
            target_index) == 0;
}

static int pcore_browse_navigate_go(HWND hwnd, int delta)
{
    const char *target;
    int target_index;

    if (g_nav_loading) {
        return 0;
    }
    target = pcore_browse_history_go_target(delta, &target_index);
    if (target == NULL) {
        return 0;
    }
    if (pcore_browse_history_same_document_target(target_index)) {
        return pcore_browser_script_session_traverse_history(
                target_index) == 0;
    }
    return navigate_to_request_ex(hwnd, target, 1, NULL, 0, NULL,
            target_index) == 0;
}

typedef struct pcore_multipart_buffer {
    unsigned char *data;
    size_t length;
    size_t capacity;
} pcore_multipart_buffer;

static int pcore_multipart_buffer_reserve(pcore_multipart_buffer *buffer,
        size_t additional)
{
    unsigned char *grown;
    size_t needed;
    size_t capacity;

    if (buffer == NULL || additional > (size_t) INT_MAX - buffer->length) {
        return 0;
    }
    needed = buffer->length + additional + 1;
    if (needed <= buffer->capacity) {
        return 1;
    }
    capacity = (buffer->capacity > 0) ? buffer->capacity : 512;
    while (capacity < needed) {
        if (capacity > ((size_t) INT_MAX + 1) / 2) {
            capacity = (size_t) INT_MAX + 1;
            break;
        }
        capacity *= 2;
    }
    grown = (unsigned char *) realloc(buffer->data, capacity);
    if (grown == NULL) {
        return 0;
    }
    buffer->data = grown;
    buffer->capacity = capacity;
    return 1;
}

static int pcore_multipart_buffer_append(pcore_multipart_buffer *buffer,
        const void *data, size_t length)
{
    if ((length > 0 && data == NULL) ||
            !pcore_multipart_buffer_reserve(buffer, length)) {
        return 0;
    }
    if (length > 0) {
        memcpy(buffer->data + buffer->length, data, length);
    }
    buffer->length += length;
    buffer->data[buffer->length] = '\0';
    return 1;
}

static int pcore_multipart_buffer_text(pcore_multipart_buffer *buffer,
        const char *text)
{
    return pcore_multipart_buffer_append(buffer, text, strlen(text));
}

static int pcore_multipart_buffer_quoted(pcore_multipart_buffer *buffer,
        const char *text)
{
    const unsigned char *cursor;
    unsigned char value;
    char escape[2];

    cursor = (const unsigned char *) ((text != NULL) ? text : "");
    while (*cursor != 0) {
        value = *cursor++;
        if (value == '\r' || value == '\n') {
            value = ' ';
        }
        if (value == '"' || value == '\\') {
            escape[0] = '\\';
            escape[1] = (char) value;
            if (!pcore_multipart_buffer_append(buffer, escape, 2)) {
                return 0;
            }
        } else if (!pcore_multipart_buffer_append(buffer, &value, 1)) {
            return 0;
        }
    }
    return 1;
}

static int pcore_multipart_buffer_file(pcore_multipart_buffer *buffer,
        const char *path)
{
    WCHAR *wide_path;
    HANDLE file;
    DWORD high;
    DWORD low;
    DWORD read_count;
    size_t offset;

    if (path == NULL || path[0] == '\0') {
        return 1;
    }
    wide_path = utf8_to_wide_alloc(path);
    if (wide_path == NULL) {
        return 0;
    }
    file = CreateFileW(wide_path, GENERIC_READ, FILE_SHARE_READ,
            NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
    free(wide_path);
    if (file == INVALID_HANDLE_VALUE) {
        return 0;
    }
    high = 0;
    low = GetFileSize(file, &high);
    if ((low == INVALID_FILE_SIZE && GetLastError() != NO_ERROR) ||
            high != 0 || low > (DWORD) INT_MAX ||
            !pcore_multipart_buffer_reserve(buffer, (size_t) low)) {
        CloseHandle(file);
        return 0;
    }
    offset = 0;
    while (offset < (size_t) low) {
        read_count = 0;
        if (!ReadFile(file, buffer->data + buffer->length + offset,
                low - (DWORD) offset, &read_count, NULL) ||
                read_count == 0) {
            CloseHandle(file);
            return 0;
        }
        offset += read_count;
    }
    CloseHandle(file);
    buffer->length += (size_t) low;
    buffer->data[buffer->length] = '\0';
    return 1;
}

static int pcore_multipart_build(HANDLE submission,
        char **out_body, int *out_body_len, char **out_content_type)
{
    static unsigned int boundary_sequence = 0;
    PCoreMultipartSubmissionInfo submission_info;
    PCoreMultipartPartInfo part_info;
    pcore_multipart_buffer buffer;
    char boundary[64];
    char *content_type;
    char *name;
    char *value;
    char *path;
    unsigned int index;
    int content_type_length;
    int result;

    if (submission == NULL || out_body == NULL ||
            out_body_len == NULL || out_content_type == NULL ||
            PCore_MultipartSubmissionInfo(submission, &submission_info,
                    NULL, 0) != 1) {
        return 0;
    }
    *out_body = NULL;
    *out_body_len = 0;
    *out_content_type = NULL;
    memset(&buffer, 0, sizeof(buffer));
    boundary_sequence++;
    _snprintf(boundary, sizeof(boundary) - 1,
            "----PositronWM6%08lX%04X",
            GetTickCount(), boundary_sequence & 0xffff);
    boundary[sizeof(boundary) - 1] = '\0';
    for (index = 0; index < submission_info.part_count; index++) {
        memset(&part_info, 0, sizeof(part_info));
        if (PCore_MultipartPartInfo(submission, index, &part_info,
                NULL, 0, NULL, 0, NULL, 0) != 1 ||
                part_info.name_bytes < 0 ||
                part_info.value_bytes < 0 ||
                part_info.path_bytes < 0) {
            free(buffer.data);
            return 0;
        }
        name = (char *) malloc((size_t) part_info.name_bytes + 1);
        value = (char *) malloc((size_t) part_info.value_bytes + 1);
        path = (char *) malloc((size_t) part_info.path_bytes + 1);
        if (name == NULL || value == NULL || path == NULL) {
            free(name);
            free(value);
            free(path);
            free(buffer.data);
            return 0;
        }
        result = PCore_MultipartPartInfo(submission, index, &part_info,
                name, part_info.name_bytes + 1,
                value, part_info.value_bytes + 1,
                path, part_info.path_bytes + 1);
        if (result != 1 ||
                !pcore_multipart_buffer_text(&buffer, "--") ||
                !pcore_multipart_buffer_text(&buffer, boundary) ||
                !pcore_multipart_buffer_text(&buffer,
                    "\r\nContent-Disposition: form-data; name=\"") ||
                !pcore_multipart_buffer_quoted(&buffer, name) ||
                !pcore_multipart_buffer_text(&buffer, "\"")) {
            free(name);
            free(value);
            free(path);
            free(buffer.data);
            return 0;
        }
        if (part_info.kind == 2) {
            result = pcore_multipart_buffer_text(&buffer, "; filename=\"") &&
                    pcore_multipart_buffer_quoted(&buffer, value) &&
                    pcore_multipart_buffer_text(&buffer,
                        "\"\r\nContent-Type: application/octet-stream"
                        "\r\n\r\n") &&
                    pcore_multipart_buffer_file(&buffer, path);
        } else {
            result = pcore_multipart_buffer_text(&buffer, "\r\n\r\n") &&
                    pcore_multipart_buffer_append(&buffer, value,
                            (size_t) part_info.value_bytes);
        }
        free(name);
        free(value);
        free(path);
        if (!result || !pcore_multipart_buffer_text(&buffer, "\r\n")) {
            free(buffer.data);
            return 0;
        }
    }
    if (!pcore_multipart_buffer_text(&buffer, "--") ||
            !pcore_multipart_buffer_text(&buffer, boundary) ||
            !pcore_multipart_buffer_text(&buffer, "--\r\n")) {
        free(buffer.data);
        return 0;
    }
    content_type_length = (int) strlen(boundary) + 48;
    content_type = (char *) malloc((size_t) content_type_length);
    if (content_type == NULL) {
        free(buffer.data);
        return 0;
    }
    _snprintf(content_type, content_type_length - 1,
            "Content-Type: multipart/form-data; boundary=%s", boundary);
    content_type[content_type_length - 1] = '\0';
    *out_body = (char *) buffer.data;
    *out_body_len = (int) buffer.length;
    *out_content_type = content_type;
    return 1;
}

static char *pcore_form_target_url(const char *action, const char *body,
        int method)
{
    char current[1536];
    const char *source;
    size_t source_length;
    size_t base_length;
    size_t body_length;
    size_t needed;
    char *target;

    source = action;
    if (source == NULL || source[0] == '\0') {
        if (pcore_document_url(g_cur_host, g_cur_path, g_cur_port,
                current, sizeof(current)) != 0) {
            return NULL;
        }
        source = current;
    }
    source_length = strlen(source);
    base_length = 0;
    while (base_length < source_length &&
            source[base_length] != '?' && source[base_length] != '#') {
        base_length++;
    }
    body_length = (body != NULL) ? strlen(body) : 0;
    needed = (method == 1) ?
            base_length + ((body_length > 0) ? body_length + 1 : 0) :
            source_length;
    if (needed >= 65535) {
        return NULL;
    }
    target = (char *) malloc(needed + 1);
    if (target == NULL) {
        return NULL;
    }
    if (method == 1) {
        if (base_length > 0) {
            memcpy(target, source, base_length);
        }
        if (body_length > 0) {
            target[base_length] = '?';
            memcpy(target + base_length + 1, body, body_length);
        }
    } else if (source_length > 0) {
        memcpy(target, source, source_length);
    }
    target[needed] = '\0';
    return target;
}

static int navigate_multipart_submission(HWND hwnd, HANDLE submission)
{
    PCoreMultipartSubmissionInfo info;
    char *action;
    char *body;
    char *content_type;
    char *target;
    int body_len;
    int result;

    memset(&info, 0, sizeof(info));
    action = NULL;
    body = NULL;
    content_type = NULL;
    target = NULL;
    result = 0;
    if (submission == NULL ||
            PCore_MultipartSubmissionInfo(submission, &info,
                    NULL, 0) != 1 ||
            info.action_bytes < 0) {
        goto done;
    }
    action = (char *) malloc((size_t) info.action_bytes + 1);
    if (action == NULL ||
            PCore_MultipartSubmissionInfo(submission, &info,
                    action, info.action_bytes + 1) != 1 ||
            !pcore_multipart_build(submission, &body, &body_len,
                    &content_type)) {
        goto done;
    }
    target = pcore_form_target_url(action, NULL, 3);
    if (target == NULL) {
        goto done;
    }
    (void) navigate_to_request_ex(hwnd, target, 3, body, body_len,
            content_type, PCORE_BROWSE_HISTORY_TARGET_NEW);
    result = 1;

done:
    free(target);
    free(content_type);
    free(body);
    free(action);
    PCore_FreeMultipartSubmission(submission);
    if (!result) {
        show_error(L"Form submission failed",
                "Could not build the multipart/form-data request");
    }
    return result;
}

static void navigate_form_submission(HWND hwnd, int method,
        const char *action, const char *body)
{
    char *target;

    target = pcore_form_target_url(action, body, method);
    if (target == NULL) {
        show_error(L"Form submission failed",
                "The form target is invalid or too large");
        return;
    }
    navigate_to_request(hwnd, target, method,
            (method == 2) ? body : NULL);
    free(target);
}

/* Script requestSubmit() reaches this host only after Browser has completed
 * validation and the cancelable submit event. Keep the remaining work as a
 * thin adapter: Core builds the successful-control set, while this host
 * starts the existing navigation/dialog machinery or records a deterministic
 * raw-fixture observation. */
static void pcore_browser_script_form_submit_probe_record(
        const PBrowserScriptFormSubmitInfo *info, int method,
        const char *action, const char *body)
{
    if (!g_script_form_submit_probe || info == NULL) {
        return;
    }
    g_script_form_submit_default_calls++;
    if (method >= 0 && method < (int) (sizeof(g_script_form_submit_method_counts) /
            sizeof(g_script_form_submit_method_counts[0]))) {
        g_script_form_submit_method_counts[method]++;
    }
    g_script_form_submit_last_method = method;
    cstr_copy(g_script_form_submit_last_form,
            sizeof(g_script_form_submit_last_form), info->form_id);
    cstr_copy(g_script_form_submit_last_submitter,
            sizeof(g_script_form_submit_last_submitter), info->submitter_id);
    cstr_copy(g_script_form_submit_last_action,
            sizeof(g_script_form_submit_last_action),
            (action != NULL) ? action : "");
    cstr_copy(g_script_form_submit_last_body,
            sizeof(g_script_form_submit_last_body),
            (body != NULL) ? body : "");
    if (method == PCORE_FORM_METHOD_POST) {
        cstr_copy(g_script_form_submit_post_body,
                sizeof(g_script_form_submit_post_body),
                (body != NULL) ? body : "");
    }
}

static char *pcore_browser_script_form_target(
        pcore_browser_script_bridge *bridge, const char *action,
        const char *body, int method)
{
    const char *effective_action;

    effective_action = action;
    if ((effective_action == NULL || effective_action[0] == '\0') &&
            bridge != NULL && bridge->history_url != NULL &&
            bridge->history_url[0] != '\0') {
        /* During initial inline-script execution the global visible URL is
         * still the old page. The candidate bridge's history URL is the
         * correct base for an omitted form action. */
        effective_action = bridge->history_url;
    }
    return pcore_form_target_url(effective_action, body, method);
}

static int pcore_browser_script_queue_form_navigation(
        pcore_browser_script_bridge *bridge, int method,
        const char *action, const char *body)
{
    char *target;
    char *body_copy;
    int body_len;
    int result;

    if (bridge == NULL || (method != PCORE_FORM_METHOD_GET &&
            method != PCORE_FORM_METHOD_POST) ||
            (body == NULL && method == PCORE_FORM_METHOD_POST)) {
        return 0;
    }
    if (g_script_form_submit_probe) {
        return 1;
    }
    target = pcore_browser_script_form_target(bridge, action, body, method);
    if (target == NULL) {
        return 0;
    }
    if (bridge->hwnd != NULL && bridge->document == g_render_doc) {
        result = navigate_to_request_ex(bridge->hwnd, target, method,
                (method == PCORE_FORM_METHOD_POST) ? body : NULL,
                (method == PCORE_FORM_METHOD_POST && body != NULL) ?
                (int) strlen(body) : 0, NULL,
                PCORE_BROWSE_HISTORY_TARGET_NEW);
        free(target);
        return result == 0 ? 1 : 0;
    }
    body_copy = NULL;
    body_len = (body != NULL) ? (int) strlen(body) : 0;
    if (method == PCORE_FORM_METHOD_POST) {
        body_copy = (char *) malloc((size_t) body_len + 1);
        if (body_copy == NULL) {
            free(target);
            return 0;
        }
        if (body_len > 0) {
            memcpy(body_copy, body, (size_t) body_len);
        }
        body_copy[body_len] = '\0';
    }
    free(bridge->navigation_url);
    bridge->navigation_url = target;
    free(bridge->navigation_body);
    bridge->navigation_body = body_copy;
    bridge->navigation_method = method;
    bridge->navigation_kind = PCORE_SCRIPT_NAVIGATION_FORM;
    bridge->navigation_delta = 0;
    bridge->navigation_target[0] = '\0';
    bridge->navigation_rel[0] = '\0';
    bridge->navigation_context_name[0] = '\0';
    bridge->navigation_target_kind =
            PBROWSER_SCRIPT_NAVIGATION_TARGET_DEFAULT;
    return 1;
}

static int pcore_browser_script_form_submit_validate(void *pw,
        const PBrowserScriptFormSubmitInfo *info, int *out_valid)
{
    pcore_browser_script_bridge *bridge;
    PCoreFormValidationInfo validation;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || bridge->document == NULL || info == NULL ||
            info->size < sizeof(PBrowserScriptFormSubmitInfo) ||
            info->form_id == NULL || info->form_id[0] == '\0' ||
            info->submitter_id == NULL || out_valid == NULL) {
        return -1;
    }
    if (g_script_form_submit_probe) {
        g_script_form_submit_validate_calls++;
    }
    *out_valid = -1;
    if (PCore_FormValidationSubmitById(bridge->document, info->form_id,
            info->submitter_id, &validation) != 0) {
        return 0;
    }
    *out_valid = validation.valid ? 1 : 0;
    return 0;
}

static int pcore_browser_script_form_submit_dialog_default(
        pcore_browser_script_bridge *bridge,
        const PBrowserScriptFormSubmitInfo *info, int validate)
{
    PCoreDialogFormSubmissionInfo dialog_info;
    char dialog_probe[1];
    char value_probe[1];
    char *dialog_id;
    char *return_value;
    int closed;
    int result;

    memset(&dialog_info, 0, sizeof(dialog_info));
    dialog_info.size = sizeof(dialog_info);
    dialog_probe[0] = '\0';
    value_probe[0] = '\0';
    if (validate) {
        result = PCore_FormDialogSubmissionById(bridge->document,
                info->form_id, info->submitter_id, &dialog_info,
                dialog_probe, sizeof(dialog_probe), value_probe,
                sizeof(value_probe));
    } else {
        result = PCore_FormDialogSubmissionNoValidationById(
                bridge->document, info->form_id, &dialog_info,
                dialog_probe, sizeof(dialog_probe), value_probe,
                sizeof(value_probe));
    }
    if (result == 0 || result == 2 || result == 5) {
        return result == 2 ? 1 : 0;
    }
    if (result != 4 || dialog_info.dialog_id_bytes <= 0 ||
            dialog_info.return_value_bytes < 0 ||
            dialog_info.dialog_id_bytes >= PBROWSER_SCRIPT_DIALOG_ID_MAX ||
            dialog_info.return_value_bytes >=
            PBROWSER_SCRIPT_DIALOG_VALUE_MAX) {
        return 0;
    }
    dialog_id = (char *) malloc((size_t) dialog_info.dialog_id_bytes + 1);
    return_value = (char *) malloc(
            (size_t) dialog_info.return_value_bytes + 1);
    if (dialog_id == NULL || return_value == NULL) {
        free(dialog_id);
        free(return_value);
        return 0;
    }
    if (validate) {
        result = PCore_FormDialogSubmissionById(bridge->document,
                info->form_id, info->submitter_id, &dialog_info, dialog_id,
                dialog_info.dialog_id_bytes + 1, return_value,
                dialog_info.return_value_bytes + 1);
    } else {
        result = PCore_FormDialogSubmissionNoValidationById(
                bridge->document, info->form_id, &dialog_info, dialog_id,
                dialog_info.dialog_id_bytes + 1, return_value,
                dialog_info.return_value_bytes + 1);
    }
    if (result != 1) {
        free(dialog_id);
        free(return_value);
        return 0;
    }
    pcore_browser_script_form_submit_probe_record(info,
            PCORE_FORM_METHOD_DIALOG, dialog_id, return_value);
    if (g_script_form_submit_probe) {
        free(dialog_id);
        free(return_value);
        return 1;
    }
    closed = 0;
    if (bridge->session == NULL ||
            PBrowser_ScriptSessionCloseDialogById(bridge->session,
            dialog_id, return_value, &closed) != PSCRIPT_OK) {
        free(dialog_id);
        free(return_value);
        return 0;
    }
    if (closed) {
        pcore_toggle_focus_clear();
        pcore_button_focus_clear();
        pcore_disclosure_focus_clear();
        pcore_sequential_focus_clear();
        if (bridge->hwnd != NULL) {
            pcore_request_interaction_restyle(bridge->hwnd);
        }
    }
    free(dialog_id);
    free(return_value);
    return closed ? 1 : 0;
}

static int pcore_browser_script_form_submit_default_common(void *pw,
        const PBrowserScriptFormSubmitInfo *info, int validate)
{
    pcore_browser_script_bridge *bridge;
    PCoreFormSubmissionInfo submission;
    char action_probe[1];
    char body_probe[1];
    char *action;
    char *body;
    HANDLE multipart;
    PCoreMultipartSubmissionInfo multipart_info;
    int result;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || bridge->document == NULL || info == NULL ||
            info->size < sizeof(PBrowserScriptFormSubmitInfo) ||
            info->form_id == NULL || info->form_id[0] == '\0' ||
            info->submitter_id == NULL) {
        return -1;
    }
    memset(&submission, 0, sizeof(submission));
    action_probe[0] = '\0';
    body_probe[0] = '\0';
    if (validate) {
        result = PCore_FormSubmissionById(bridge->document, info->form_id,
                info->submitter_id, &submission, action_probe,
                sizeof(action_probe), body_probe, sizeof(body_probe));
    } else {
        result = PCore_FormSubmissionNoValidationById(bridge->document,
                info->form_id, &submission, action_probe,
                sizeof(action_probe), body_probe, sizeof(body_probe));
    }
    if (result == 0 || result == 2 || result == 5) {
        return 0;
    }
    if (result == 6) {
        return pcore_browser_script_form_submit_dialog_default(bridge, info,
                validate);
    }
    if (result == 3) {
        if (validate) {
            multipart = PCore_MultipartSubmissionById(bridge->document,
                    info->form_id, info->submitter_id);
        } else {
            multipart = PCore_MultipartSubmissionNoValidationById(
                    bridge->document, info->form_id);
        }
        if (multipart == NULL) {
            return 0;
        }
        memset(&multipart_info, 0, sizeof(multipart_info));
        if (PCore_MultipartSubmissionInfo(multipart, &multipart_info,
                NULL, 0) != 1 || multipart_info.action_bytes < 0 ||
                multipart_info.action_bytes >=
                (int) sizeof(g_script_form_submit_last_action)) {
            PCore_FreeMultipartSubmission(multipart);
            return 0;
        }
        action = (char *) malloc((size_t) multipart_info.action_bytes + 1);
        if (action == NULL ||
                PCore_MultipartSubmissionInfo(multipart, &multipart_info,
                action, multipart_info.action_bytes + 1) != 1) {
            free(action);
            PCore_FreeMultipartSubmission(multipart);
            return 0;
        }
        pcore_browser_script_form_submit_probe_record(info,
                PCORE_FORM_METHOD_MULTIPART, action, "");
        free(action);
        if (g_script_form_submit_probe) {
            PCore_FreeMultipartSubmission(multipart);
            return 1;
        }
        if (bridge->hwnd == NULL || bridge->document != g_render_doc) {
            PCore_FreeMultipartSubmission(multipart);
            return 0;
        }
        return navigate_multipart_submission(bridge->hwnd, multipart);
    }
    action = NULL;
    body = NULL;
    if (result == 1) {
        action = action_probe;
        body = body_probe;
    } else if (result == 4 && submission.method != 0 &&
            submission.action_bytes >= 0 && submission.body_bytes >= 0 &&
            submission.action_bytes < 65535 &&
            submission.body_bytes < 65535) {
        action = (char *) malloc((size_t) submission.action_bytes + 1);
        body = (char *) malloc((size_t) submission.body_bytes + 1);
        if (action == NULL || body == NULL) {
            free(action);
            free(body);
            return 0;
        }
        if (validate) {
            result = PCore_FormSubmissionById(bridge->document,
                    info->form_id, info->submitter_id, &submission, action,
                    submission.action_bytes + 1, body,
                    submission.body_bytes + 1);
        } else {
            result = PCore_FormSubmissionNoValidationById(
                    bridge->document, info->form_id, &submission, action,
                    submission.action_bytes + 1, body,
                    submission.body_bytes + 1);
        }
        if (result != 1) {
            free(action);
            free(body);
            return 0;
        }
    } else {
        return 0;
    }
    pcore_browser_script_form_submit_probe_record(info, submission.method,
            action, body);
    if (g_script_form_submit_probe) {
        if (action != action_probe) { free(action); }
        if (body != body_probe) { free(body); }
        return 1;
    }
    result = pcore_browser_script_queue_form_navigation(bridge,
            submission.method, action, body);
    if (action != action_probe) { free(action); }
    if (body != body_probe) { free(body); }
    return result;
}

static int pcore_browser_script_form_submit_default(void *pw,
        const PBrowserScriptFormSubmitInfo *info)
{
    return pcore_browser_script_form_submit_default_common(pw, info, 1);
}

static int pcore_browser_script_form_submit_direct(void *pw,
        const PBrowserScriptFormSubmitInfo *info)
{
    if (info == NULL || info->submitter_id == NULL ||
            info->submitter_id[0] != '\0') {
        return -1;
    }
    if (g_script_form_submit_probe) {
        g_script_form_submit_direct_calls++;
    }
    return pcore_browser_script_form_submit_default_common(pw, info, 0);
}

static int pcore_browser_script_form_data_count_ex(void *pw,
        const char *form_id, const char *submitter_id, int *out_count)
{
    pcore_browser_script_bridge *bridge;
    HANDLE form_data;
    PCoreFormDataInfo info;
    int result;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || bridge->document == NULL || form_id == NULL ||
            form_id[0] == '\0' || out_count == NULL) {
        return -1;
    }
    form_data = PCore_FormDataByIdEx(bridge->document, form_id,
            submitter_id);
    if (form_data == NULL) {
        return 1;
    }
    memset(&info, 0, sizeof(info));
    result = PCore_FormDataInfo(form_data, &info);
    if (result != 1 || info.entry_count >
            PBROWSER_SCRIPT_FORM_DATA_MAX_ENTRIES) {
        PCore_FreeFormData(form_data);
        return 1;
    }
    *out_count = (int) info.entry_count;
    PCore_FreeFormData(form_data);
    return 0;
}

static int pcore_browser_script_form_data_entry_ex(void *pw,
        const char *form_id, const char *submitter_id,
        unsigned int entry_index, PBrowserScriptFormDataEntryInfo *out_info)
{
    pcore_browser_script_bridge *bridge;
    HANDLE form_data;
    PCoreFormDataEntryInfo core_info;
    char core_name[PBROWSER_SCRIPT_FORM_DATA_NAME_MAX_BYTES + 1];
    char core_value[PBROWSER_SCRIPT_FORM_DATA_VALUE_MAX_BYTES + 1];
    int result;

    bridge = (pcore_browser_script_bridge *) pw;
    if (bridge == NULL || bridge->document == NULL || form_id == NULL ||
            form_id[0] == '\0' || out_info == NULL ||
            out_info->size < sizeof(PBrowserScriptFormDataEntryInfo) ||
            out_info->name == NULL || out_info->name_capacity <= 0 ||
            out_info->value == NULL || out_info->value_capacity <= 0 ||
            out_info->filename == NULL || out_info->filename_capacity <= 0 ||
            out_info->type == NULL || out_info->type_capacity <= 0) {
        return -1;
    }
    if (out_info->name_capacity >
            PBROWSER_SCRIPT_FORM_DATA_NAME_MAX_BYTES + 1 ||
            out_info->value_capacity >
            PBROWSER_SCRIPT_FORM_DATA_VALUE_MAX_BYTES + 1 ||
            out_info->filename_capacity >
            PBROWSER_SCRIPT_FORM_DATA_FILENAME_MAX_BYTES + 1 ||
            out_info->type_capacity >
            PBROWSER_SCRIPT_FORM_DATA_TYPE_MAX_BYTES + 1) {
        return -1;
    }
    form_data = PCore_FormDataByIdEx(bridge->document, form_id,
            submitter_id);
    if (form_data == NULL) {
        return 1;
    }
    memset(&core_info, 0, sizeof(core_info));
    memset(core_name, 0, sizeof(core_name));
    memset(core_value, 0, sizeof(core_value));
    result = PCore_FormDataEntryInfo(form_data, entry_index, &core_info,
            core_name, sizeof(core_name), core_value, sizeof(core_value));
    PCore_FreeFormData(form_data);
    if (result != 1 ||
            (core_info.kind != PBROWSER_SCRIPT_FORM_DATA_STRING &&
            core_info.kind != PBROWSER_SCRIPT_FORM_DATA_FILE) ||
            core_info.name_bytes < 0 || core_info.name_bytes >=
            (int) sizeof(core_name) || core_info.value_bytes < 0 ||
            core_info.value_bytes >= (int) sizeof(core_value)) {
        return 1;
    }
    if (core_info.name_bytes >= out_info->name_capacity ||
            (core_info.kind == PBROWSER_SCRIPT_FORM_DATA_STRING &&
            core_info.value_bytes >= out_info->value_capacity) ||
            (core_info.kind == PBROWSER_SCRIPT_FORM_DATA_FILE &&
            core_info.value_bytes >= out_info->filename_capacity)) {
        return -1;
    }
    memcpy(out_info->name, core_name, (size_t) core_info.name_bytes + 1);
    out_info->name_bytes = core_info.name_bytes;
    out_info->value[0] = '\0';
    out_info->value_bytes = 0;
    out_info->filename[0] = '\0';
    out_info->filename_bytes = 0;
    out_info->type[0] = '\0';
    out_info->type_bytes = 0;
    if (core_info.kind == PBROWSER_SCRIPT_FORM_DATA_FILE) {
        memcpy(out_info->filename, core_value,
                (size_t) core_info.value_bytes + 1);
        out_info->filename_bytes = core_info.value_bytes;
    } else {
        memcpy(out_info->value, core_value,
                (size_t) core_info.value_bytes + 1);
        out_info->value_bytes = core_info.value_bytes;
    }
    out_info->kind = core_info.kind;
    return 0;
}

/* Every WM re-style must reassert the physical-pixel/DPI contract before
 * both selection and layout. Otherwise PCore_LayoutDocument consumes the
 * previous device viewport, falls back to the legacy CSS-pixel path, and a
 * following :active/:hover reselect can treat a high-DPI physical width as
 * the CSS viewport width. */
static int pcore_style_layout_device_document(HANDLE document, HANDLE sheet,
        const char *document_base, int width, int height, int dpi)
{
    if (document == NULL || width <= 0 || height <= 0 || dpi <= 0) {
        return 1;
    }
    g_page_scroll_dpi = dpi;
    PCore_SetDeviceViewport(width, height, dpi);
    if (PCore_StyleDocumentEx2(document, sheet, document_base,
            wm_combine_url, page_resource_cache_only_cb, NULL, NULL) != 0 ||
            PCore_LayoutDocument(document, width, height) != 0) {
        return 1;
    }
    return 0;
}

static int pcore_restyle_form_state(HWND hwnd, int preserve_focus)
{
    RECT client;
    char document_url[1536];
    const char *document_base;
    int width;
    int height;
    int max_scroll_x;
    int max_scroll;

    if (hwnd == NULL || g_render_doc == NULL) {
        return 1;
    }
    GetClientRect(hwnd, &client);
    width = client.right - client.left;
    height = client.bottom - client.top;
    document_base = NULL;
    if (pcore_document_url(g_cur_host, g_cur_path, g_cur_port,
            document_url, sizeof(document_url)) == 0) {
        document_base = document_url;
    }
    if (pcore_style_layout_device_document(g_render_doc, g_render_sheet,
            document_base, width, height, test_host_device_dpi()) != 0) {
        return 1;
    }
    g_doc_w = PCore_DocumentWidth(g_render_doc);
    g_doc_h = PCore_DocumentHeight(g_render_doc);
    max_scroll_x = (g_doc_w > width) ? g_doc_w - width : 0;
    max_scroll = (g_doc_h > height) ? g_doc_h - height : 0;
    if (g_scroll_x > max_scroll_x) {
        g_scroll_x = max_scroll_x;
    }
    if (g_scroll_y > max_scroll) {
        g_scroll_y = max_scroll;
    }
    pcore_set_scrollbar(hwnd);
    pcore_native_edits_rebuild(hwnd, preserve_focus);
    pcore_native_selects_rebuild(hwnd, preserve_focus);
    InvalidateRect(hwnd, NULL, TRUE);
    return 0;
}

static void pcore_handle_invalid_form(HWND hwnd,
        const PCoreFormValidationInfo *validation);

static int pcore_form_button_control_at(int x, int y,
        unsigned int *out_index, int *out_kind, int *out_disabled)
{
    unsigned int index;
    int left;
    int top;
    int width;
    int height;
    int kind;
    int disabled;

    if (out_index != NULL) {
        *out_index = 0;
    }
    if (out_kind != NULL) {
        *out_kind = 0;
    }
    if (out_disabled != NULL) {
        *out_disabled = 0;
    }
    if (g_render_doc == NULL) {
        return 0;
    }
    index = 0;
    while (PCore_FormControlInfo(g_render_doc, index, &left, &top,
            &width, &height, &kind, NULL, &disabled) == 0) {
        if ((kind >= 7 && kind <= 9) && width > 0 && height > 0 &&
                x >= left && x < left + width &&
                y >= top && y < top + height) {
            if (out_index != NULL) {
                *out_index = index;
            }
            if (out_kind != NULL) {
                *out_kind = kind;
            }
            if (out_disabled != NULL) {
                *out_disabled = disabled ? 1 : 0;
            }
            return 1;
        }
        if (index == UINT_MAX) {
            break;
        }
        index++;
    }
    return 0;
}

static int pcore_form_button_kind_at(int x, int y, int *out_kind)
{
    int disabled;

    if (out_kind != NULL) {
        *out_kind = 0;
    }
    disabled = 0;
    return pcore_form_button_control_at(x, y, NULL, out_kind,
            &disabled) && !disabled;
}

static int pcore_browser_script_dispatch_form_event_at(int x, int y,
        const char *event_type)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptFormEventInfo event_info;
    int default_allowed;
    int rc;

    if (g_render_doc == NULL || event_type == NULL) {
        return 1;
    }
    bridge = g_browser_script_session.bridge;
    if (g_browser_script_session.document == g_render_doc &&
            g_browser_script_session.runtime != NULL &&
            bridge != NULL && bridge->session != NULL) {
        memset(&event_info, 0, sizeof(event_info));
        event_info.size = sizeof(event_info);
        event_info.x = x;
        event_info.y = y;
        event_info.event_type = event_type;
        event_info.bubbles = 1;
        event_info.cancelable = 1;
        default_allowed = 1;
        rc = PBrowser_ScriptSessionDispatchFormEvent(bridge->session,
                &event_info, &default_allowed);
        if (rc != PSCRIPT_OK) {
            return 0;
        }
        return default_allowed ? 1 : 0;
    }
    default_allowed = 1;
    PCore_EventDispatchAt(g_render_doc, x, y, event_type, 1, 1,
            &default_allowed);
    return default_allowed ? 1 : 0;
}

/* Programmatic form activation can run while a navigation request is still
 * preparing its new document, before the global render session is installed.
 * Dispatch through the callback's bridge directly so the event cannot land on
 * the previous page. Returns 1 when the default is allowed, 0 when canceled,
 * and -1 for an adapter/core failure. */
static int pcore_browser_script_dispatch_form_event_bridge(
        pcore_browser_script_bridge *bridge, int x, int y,
        const char *event_type)
{
    PBrowserScriptFormEventInfo event_info;
    int default_allowed;
    int result;
    int rc;

    if (bridge == NULL || bridge->document == NULL ||
            event_type == NULL ||
            (strcmp(event_type, "submit") != 0 &&
            strcmp(event_type, "reset") != 0)) {
        return -1;
    }
    memset(&event_info, 0, sizeof(event_info));
    event_info.size = sizeof(event_info);
    event_info.x = x;
    event_info.y = y;
    event_info.event_type = event_type;
    event_info.bubbles = 1;
    event_info.cancelable = 1;
    default_allowed = 1;
    if (bridge->session != NULL) {
        rc = PBrowser_ScriptSessionDispatchFormEvent(bridge->session,
                &event_info, &default_allowed);
        if (rc != PSCRIPT_OK) {
            return -1;
        }
    } else {
        result = PCore_EventDispatchAt(bridge->document, x, y,
                event_type, 1, 1, &default_allowed);
        if (result < 0) {
            return -1;
        }
    }
    return default_allowed ? 1 : 0;
}

static int pcore_browser_script_dispatch_form_event_for_text_input(
        unsigned int text_index, const char *event_type)
{
    PCoreTextInputInfo text_info;

    if (g_render_doc == NULL || PCore_TextInputInfo(g_render_doc,
            text_index, &text_info, NULL, 0) != 0 ||
            text_info.width <= 0 || text_info.height <= 0) {
        return 1;
    }
    return pcore_browser_script_dispatch_form_event_at(
            text_info.x + text_info.width / 2,
            text_info.y + text_info.height / 2, event_type);
}

static int pcore_browser_script_dispatch_invalid_event_at(int x, int y)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptInvalidEventInfo event_info;
    int default_allowed;
    int rc;

    if (g_render_doc == NULL) {
        return 1;
    }
    bridge = g_browser_script_session.bridge;
    if (g_browser_script_session.document == g_render_doc &&
            g_browser_script_session.runtime != NULL &&
            bridge != NULL && bridge->session != NULL) {
        memset(&event_info, 0, sizeof(event_info));
        event_info.size = sizeof(event_info);
        event_info.x = x;
        event_info.y = y;
        event_info.event_type = "invalid";
        event_info.bubbles = 0;
        event_info.cancelable = 1;
        default_allowed = 1;
        rc = PBrowser_ScriptSessionDispatchInvalidEvent(bridge->session,
                &event_info, &default_allowed);
        if (rc != PSCRIPT_OK) {
            return 0;
        }
        return default_allowed ? 1 : 0;
    }
    default_allowed = 1;
    PCore_EventDispatchAt(g_render_doc, x, y, "invalid", 0, 1,
            &default_allowed);
    return default_allowed ? 1 : 0;
}

/* Native SELECT, checkbox/radio and file controls use the existing typed
 * select-style change contract. The event is non-cancelable and is emitted
 * only after the core value/state has been committed. */
static int pcore_browser_script_dispatch_select_change_at(int x, int y)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptSelectEventInfo select_info;
    int rc;

    if (g_render_doc == NULL) {
        return -1;
    }
    bridge = g_browser_script_session.bridge;
    memset(&select_info, 0, sizeof(select_info));
    select_info.size = sizeof(select_info);
    select_info.x = x;
    select_info.y = y;
    select_info.event_type = "change";
    select_info.bubbles = 1;
    select_info.cancelable = 0;
    if (g_browser_script_session.document == g_render_doc &&
            g_browser_script_session.runtime != NULL &&
            bridge != NULL && bridge->session != NULL) {
        rc = PBrowser_ScriptSessionDispatchSelectEvent(
                bridge->session, &select_info);
        return rc == PSCRIPT_OK ? 1 : -1;
    }
    rc = PCore_EventDispatchAt(g_render_doc, x, y, "change", 1, 0, NULL);
    return rc < 0 ? -1 : 1;
}

/* Native SELECT commits use the product-owned Ex adapter when browser
 * scripting is active. The host still supplies the post-mutation geometry
 * and selection snapshot; the fallback keeps the non-script path unchanged. */
static int pcore_browser_script_dispatch_native_select_commit(HWND control)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptNativeSelectCommitInfo commit_info;
    PCoreSelectInfo select_info;
    unsigned int i;
    int x;
    int y;
    int rc;

    if (control == NULL || g_render_doc == NULL) {
        return -1;
    }
    for (i = 0; i < g_native_select_count; i++) {
        if (g_native_selects[i].hwnd == control &&
                PCore_SelectInfo(g_render_doc,
                g_native_selects[i].select_index, &select_info) == 0) {
            x = select_info.x + select_info.width / 2;
            y = select_info.y + select_info.height / 2;
            bridge = g_browser_script_session.bridge;
            if (g_browser_script_session.document == g_render_doc &&
                    g_browser_script_session.runtime != NULL &&
                    bridge != NULL && bridge->session != NULL) {
                memset(&commit_info, 0, sizeof(commit_info));
                commit_info.size = sizeof(commit_info);
                commit_info.target_token =
                        g_native_selects[i].select_index + 1UL;
                commit_info.x = x;
                commit_info.y = y;
                commit_info.multiple = select_info.multiple ? 1 : 0;
                commit_info.selected_index = select_info.selected_index;
                commit_info.selected_count = select_info.selected_count;
                rc = PBrowser_ScriptSessionDispatchNativeSelectCommit(
                        bridge->session, &commit_info);
                return rc == PSCRIPT_OK ? 1 : -1;
            }
            rc = PCore_EventDispatchAt(g_render_doc, x, y, "input", 1, 0,
                    NULL);
            if (rc < 0) {
                return -1;
            }
            rc = PCore_EventDispatchAt(g_render_doc, x, y, "change", 1, 0,
                    NULL);
            return rc < 0 ? -1 : 1;
        }
    }
    return -1;
}

/* Native single-select dropdown notifications use a browser-owned bounded
 * transaction when scripting is active. The host supplies only the current
 * WM phase and selection snapshot; Core is mutated later, on END_OK, by the
 * existing commit helper. A zero return means the non-script path keeps its
 * legacy immediate behavior. */
static int pcore_browser_script_dispatch_native_select_interaction(
        HWND control, int phase, int *out_should_commit)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptNativeSelectInteractionInfo interaction_info;
    PCoreSelectInfo select_info;
    unsigned int i;
    LRESULT selected_index;
    int selected_count;
    int rc;

    if (out_should_commit != NULL) {
        *out_should_commit = 0;
    }
    if (control == NULL || g_render_doc == NULL ||
            out_should_commit == NULL) {
        return -1;
    }
    for (i = 0; i < g_native_select_count; i++) {
        if (g_native_selects[i].hwnd == control &&
                !g_native_selects[i].multiple &&
                PCore_SelectInfo(g_render_doc,
                g_native_selects[i].select_index, &select_info) == 0) {
            selected_index = (phase ==
                    PBROWSER_SCRIPT_NATIVE_SELECT_INTERACTION_BEGIN) ?
                    (LRESULT) select_info.selected_index :
                    SendMessage(control, CB_GETCURSEL, 0, 0);
            selected_count = (selected_index == CB_ERR) ? 0 : 1;
            memset(&interaction_info, 0, sizeof(interaction_info));
            interaction_info.size = sizeof(interaction_info);
            interaction_info.target_token =
                    g_native_selects[i].select_index + 1UL;
            interaction_info.x = select_info.x + select_info.width / 2;
            interaction_info.y = select_info.y + select_info.height / 2;
            interaction_info.multiple = 0;
            interaction_info.selected_index =
                    (selected_index == CB_ERR) ? -1 :
                    (int) selected_index;
            interaction_info.selected_count = selected_count;
            interaction_info.phase = phase;
            bridge = g_browser_script_session.bridge;
            if (g_browser_script_session.document == g_render_doc &&
                    g_browser_script_session.runtime != NULL &&
                    bridge != NULL && bridge->session != NULL) {
                rc = PBrowser_ScriptSessionDispatchNativeSelectInteraction(
                        bridge->session, &interaction_info,
                        out_should_commit);
                return rc == PSCRIPT_OK ? 1 : -1;
            }
            return 0;
        }
    }
    return -1;
}

/* Native SELECT focus transitions use the browser-owned pair/state adapter
 * when scripting is active. The host still supplies only the control's
 * current geometry and the WM focus transition; the non-script fallback
 * preserves the existing direct Core dispatch. */
static int pcore_browser_script_dispatch_native_select_focus(HWND control,
        int focused)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptNativeSelectFocusInfo focus_info;
    PCoreSelectInfo select_info;
    unsigned int i;
    int x;
    int y;
    int rc;

    if (control == NULL || g_render_doc == NULL ||
            (focused != 0 && focused != 1)) {
        return -1;
    }
    for (i = 0; i < g_native_select_count; i++) {
        if (g_native_selects[i].hwnd == control &&
                PCore_SelectInfo(g_render_doc,
                g_native_selects[i].select_index, &select_info) == 0) {
            x = select_info.x + select_info.width / 2;
            y = select_info.y + select_info.height / 2;
            bridge = g_browser_script_session.bridge;
            if (g_browser_script_session.document == g_render_doc &&
                    g_browser_script_session.runtime != NULL &&
                    bridge != NULL && bridge->session != NULL) {
                memset(&focus_info, 0, sizeof(focus_info));
                focus_info.size = sizeof(focus_info);
                focus_info.target_token =
                        g_native_selects[i].select_index + 1UL;
                focus_info.x = x;
                focus_info.y = y;
                focus_info.focused = focused;
                rc = PBrowser_ScriptSessionDispatchNativeSelectFocus(
                        bridge->session, &focus_info);
                return rc == PSCRIPT_OK ? 1 : -1;
            }
            if (focused) {
                rc = PCore_EventDispatchAt(g_render_doc, x, y,
                        "focus", 0, 0, NULL);
                if (rc >= 0) {
                    rc = PCore_EventDispatchAt(g_render_doc, x, y,
                            "focusin", 1, 0, NULL);
                }
            } else {
                rc = PCore_EventDispatchAt(g_render_doc, x, y,
                        "blur", 0, 0, NULL);
                if (rc >= 0) {
                    rc = PCore_EventDispatchAt(g_render_doc, x, y,
                            "focusout", 1, 0, NULL);
                }
            }
            return rc < 0 ? -1 : 1;
        }
    }
    return -1;
}

static void pcore_browser_script_reset_native_select_state(void)
{
    pcore_browser_script_bridge *bridge;

    bridge = g_browser_script_session.bridge;
    if (g_browser_script_session.document != NULL &&
            g_browser_script_session.runtime != NULL &&
            bridge != NULL && bridge->session != NULL) {
        (void) PBrowser_ScriptSessionResetNativeSelectState(
                bridge->session);
    }
}

/* Native checkbox/radio controls use the existing typed input contract. The
 * event is non-cancelable, carries no text-edit or file metadata, and is
 * emitted only after the core value/state has been committed. */
static int pcore_browser_script_dispatch_native_toggle_phase(
        unsigned int index, int kind, int x, int y, int phase,
        int disabled, int selected_before, int selected_after,
        int *out_default_allowed)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptNativeToggleInfo info;
    int default_allowed;
    int ignored_default_allowed;
    int rc;

    if (out_default_allowed == NULL) {
        out_default_allowed = &ignored_default_allowed;
    }
    *out_default_allowed = 1;
    if (g_render_doc == NULL || index >= PBROWSER_SCRIPT_NATIVE_TOGGLE_MAX_TARGETS ||
            (kind != PBROWSER_SCRIPT_NATIVE_TOGGLE_CHECKBOX &&
            kind != PBROWSER_SCRIPT_NATIVE_TOGGLE_RADIO) ||
            (phase != PBROWSER_SCRIPT_NATIVE_TOGGLE_CLICK &&
            phase != PBROWSER_SCRIPT_NATIVE_TOGGLE_COMMIT &&
            phase != PBROWSER_SCRIPT_NATIVE_TOGGLE_CANCEL)) {
        return -1;
    }
    bridge = g_browser_script_session.bridge;
    if (!pcore_native_script_active() || bridge == NULL ||
            bridge->session == NULL) {
        return 0;
    }
    memset(&info, 0, sizeof(info));
    info.size = sizeof(info);
    info.target_token = (unsigned long) index + 1UL;
    info.x = x;
    info.y = y;
    info.phase = phase;
    info.kind = kind;
    info.disabled = disabled ? 1 : 0;
    info.selected_before = selected_before ? 1 : 0;
    info.selected_after = selected_after ? 1 : 0;
    default_allowed = 1;
    rc = PBrowser_ScriptSessionDispatchNativeToggle(
            bridge->session, &info, &default_allowed);
    if (rc != PSCRIPT_OK) {
        *out_default_allowed = 0;
        return -1;
    }
    *out_default_allowed = default_allowed ? 1 : 0;
    return 1;
}

static int test1071_browser_toggle_host_route(
        test1071_toggle_state *state, HANDLE session)
{
    pcore_browser_script_bridge bridge_storage;
    int default_allowed;
    int rc;
    int ok;

    if (state == NULL || session == NULL) {
        return 0;
    }
    memset(&bridge_storage, 0, sizeof(bridge_storage));
    g_render_doc = (HANDLE) 1;
    bridge_storage.document = g_render_doc;
    bridge_storage.runtime = session;
    bridge_storage.session = session;
    g_browser_script_session.document = g_render_doc;
    g_browser_script_session.runtime = session;
    g_browser_script_session.session = session;
    g_browser_script_session.bridge = &bridge_storage;
    default_allowed = 0;
    rc = pcore_browser_script_dispatch_native_toggle_phase(
            4, PBROWSER_SCRIPT_NATIVE_TOGGLE_CHECKBOX, 44, 55,
            PBROWSER_SCRIPT_NATIVE_TOGGLE_CLICK, 0, 0, 0,
            &default_allowed);
    ok = rc == 1 && default_allowed == 1;
    if (ok) {
        rc = pcore_browser_script_dispatch_native_toggle_phase(
                4, PBROWSER_SCRIPT_NATIVE_TOGGLE_CHECKBOX, 44, 55,
                PBROWSER_SCRIPT_NATIVE_TOGGLE_COMMIT, 0, 0, 1,
                NULL);
        ok = rc == 1 &&
                strcmp(state->sequence, "CIS") == 0 &&
                state->click_calls == 1 && state->input_calls == 1 &&
                state->change_calls == 1;
    }
    g_browser_script_session.document = NULL;
    g_browser_script_session.runtime = NULL;
    g_browser_script_session.session = NULL;
    g_browser_script_session.bridge = NULL;
    g_render_doc = NULL;
    return ok;
}

static int pcore_browser_script_dispatch_native_button_phase(
        unsigned int index, int kind, int x, int y, int phase,
        int disabled, int validation_valid, int *out_default_allowed)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptNativeButtonInfo info;
    int native_kind;
    int default_allowed;
    int ignored_default_allowed;
    int rc;

    if (out_default_allowed == NULL) {
        out_default_allowed = &ignored_default_allowed;
    }
    *out_default_allowed = 1;
    if (g_render_doc == NULL || index == UINT_MAX ||
            (kind < 7 || kind > 9) ||
            (phase != PBROWSER_SCRIPT_NATIVE_BUTTON_CLICK &&
            phase != PBROWSER_SCRIPT_NATIVE_BUTTON_COMMIT &&
            phase != PBROWSER_SCRIPT_NATIVE_BUTTON_CANCEL) ||
            (disabled != 0 && disabled != 1) ||
            (validation_valid != 0 && validation_valid != 1)) {
        return -1;
    }
    bridge = g_browser_script_session.bridge;
    if (bridge == NULL || bridge->session == NULL ||
            (!pcore_native_script_active() &&
            phase != PBROWSER_SCRIPT_NATIVE_BUTTON_CANCEL)) {
        return 0;
    }
    native_kind = (kind == 7) ?
            PBROWSER_SCRIPT_NATIVE_BUTTON_SUBMIT :
            ((kind == 8) ? PBROWSER_SCRIPT_NATIVE_BUTTON_RESET :
            PBROWSER_SCRIPT_NATIVE_BUTTON_BUTTON);
    memset(&info, 0, sizeof(info));
    info.size = sizeof(info);
    info.target_token = (unsigned long) index + 1UL;
    info.x = x;
    info.y = y;
    info.phase = phase;
    info.kind = native_kind;
    info.disabled = disabled ? 1 : 0;
    info.validation_valid = validation_valid ? 1 : 0;
    default_allowed = 1;
    rc = PBrowser_ScriptSessionDispatchNativeButton(
            bridge->session, &info, &default_allowed);
    if (rc != PSCRIPT_OK) {
        *out_default_allowed = 0;
        return -1;
    }
    *out_default_allowed = default_allowed ? 1 : 0;
    return 1;
}

