static int pcore_browser_script_dispatch_toggle_input_at(int x, int y)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptInputEventInfo input_info;
    PCoreInputEventDataEx input_data;
    int default_allowed;
    int rc;

    if (g_render_doc == NULL) {
        return -1;
    }
    bridge = g_browser_script_session.bridge;
    memset(&input_info, 0, sizeof(input_info));
    input_info.size = sizeof(input_info);
    input_info.x = x;
    input_info.y = y;
    input_info.event_type = "input";
    input_info.bubbles = 1;
    input_info.cancelable = 0;
    input_info.input_type = "";
    input_info.data = "";
    input_info.is_composing = 0;
    default_allowed = 1;
    if (g_browser_script_session.document == g_render_doc &&
            g_browser_script_session.runtime != NULL &&
            bridge != NULL && bridge->session != NULL) {
        rc = PBrowser_ScriptSessionDispatchInputEvent(
                bridge->session, &input_info, &default_allowed);
        if (rc != PSCRIPT_OK) {
            return -1;
        }
        return default_allowed ? 1 : 0;
    }
    memset(&input_data, 0, sizeof(input_data));
    input_data.struct_size = sizeof(input_data);
    input_data.input_type = input_info.input_type;
    input_data.data = input_info.data;
    input_data.is_composing = 0;
    rc = PCore_EventDispatchInputExAt(g_render_doc, x, y, "input", 1, 0,
            &input_data, &default_allowed);
    if (rc < 0) {
        return -1;
    }
    return default_allowed ? 1 : 0;
}

/* Product file selection uses the existing typed input/select callbacks. The
 * picker and Core file value remain host-owned; this bridge only stages the
 * browser-owned begin/commit/cancel transaction. */
static int pcore_browser_script_dispatch_native_file_phase(
        unsigned int file_index, int x, int y, int phase)
{
    PBrowserScriptNativeFileSelectionInfo info;
    int rc;

    if (!pcore_native_script_active() ||
            g_browser_script_session.session == NULL) {
        return 0;
    }
    memset(&info, 0, sizeof(info));
    info.size = sizeof(info);
    info.target_token = (unsigned long) file_index + 1UL;
    info.x = x;
    info.y = y;
    info.phase = phase;
    rc = PBrowser_ScriptSessionDispatchNativeFileSelection(
            g_browser_script_session.session, &info);
    return rc == PSCRIPT_OK ? 1 : -1;
}

/* Product file-picker arbitration is separate from the picker/result
 * transaction above: the browser layer owns one pending/active request per
 * script session, while this host keeps the HWND/document needed to run the
 * modal WM6 dialog. */
static int pcore_browser_script_dispatch_native_file_picker_phase(
        pcore_browser_script_bridge *bridge, unsigned int file_index,
        int x, int y, int phase, int *out_accepted)
{
    PBrowserScriptNativeFilePickerInfo info;
    int accepted;
    int rc;

    if (out_accepted == NULL) {
        return -1;
    }
    *out_accepted = 1;
    if (bridge == NULL || bridge->session == NULL ||
            g_browser_script_session.bridge != bridge ||
            g_browser_script_session.session != bridge->session ||
            ((phase == PBROWSER_SCRIPT_NATIVE_FILE_PICKER_REQUEST ||
            phase == PBROWSER_SCRIPT_NATIVE_FILE_PICKER_OPEN) &&
            !pcore_native_script_active())) {
        return 0;
    }
    memset(&info, 0, sizeof(info));
    info.size = sizeof(info);
    info.target_token = (unsigned long) file_index + 1UL;
    info.x = x;
    info.y = y;
    info.phase = phase;
    accepted = 0;
    rc = PBrowser_ScriptSessionDispatchNativeFilePicker(
            bridge->session, &info, &accepted);
    if (rc != PSCRIPT_OK) {
        return -1;
    }
    *out_accepted = accepted ? 1 : 0;
    return 1;
}

/* Fallback for a host path without an active browser script session. */
static int pcore_browser_script_dispatch_file_event_at(int x, int y,
        const char *event_type)
{
    pcore_browser_script_bridge *bridge;
    PBrowserScriptInputEventInfo input_info;
    PCoreInputEventDataEx input_data;
    int default_allowed;
    int rc;

    if (g_render_doc == NULL || event_type == NULL) {
        return -1;
    }
    bridge = g_browser_script_session.bridge;
    if (strcmp(event_type, "input") == 0) {
        memset(&input_info, 0, sizeof(input_info));
        input_info.size = sizeof(input_info);
        input_info.x = x;
        input_info.y = y;
        input_info.event_type = "input";
        input_info.bubbles = 1;
        input_info.cancelable = 0;
        input_info.input_type = "insertFromFile";
        input_info.data = "";
        input_info.is_composing = 0;
        default_allowed = 1;
        if (g_browser_script_session.document == g_render_doc &&
                g_browser_script_session.runtime != NULL &&
                bridge != NULL && bridge->session != NULL) {
            rc = PBrowser_ScriptSessionDispatchInputEvent(
                    bridge->session, &input_info, &default_allowed);
            if (rc != PSCRIPT_OK) {
                return -1;
            }
            return default_allowed ? 1 : 0;
        }
        memset(&input_data, 0, sizeof(input_data));
        input_data.struct_size = sizeof(input_data);
        input_data.input_type = input_info.input_type;
        input_data.data = input_info.data;
        input_data.is_composing = 0;
        rc = PCore_EventDispatchInputExAt(g_render_doc, x, y, "input",
                1, 0, &input_data, &default_allowed);
        if (rc < 0) {
            return -1;
        }
        return default_allowed ? 1 : 0;
    }
    if (strcmp(event_type, "change") != 0) {
        return -1;
    }
    return pcore_browser_script_dispatch_select_change_at(x, y);
}

/* Core resolves form ownership, effective method, nearest dialog and the
 * submitter value. Browser owns the direct close/returnValue/close-event
 * lifecycle. This host function only joins those DLL boundaries to the WM
 * default-action path and never treats method=dialog as a navigation. */
static int pcore_handle_dialog_form_default(HWND hwnd, int x, int y,
        unsigned int text_index, int from_text_input)
{
    PCoreDialogFormSubmissionInfo info;
    char *dialog_id;
    char *return_value;
    int result;
    int closed;

    memset(&info, 0, sizeof(info));
    info.size = sizeof(info);
    if (from_text_input) {
        result = PCore_FormDialogSubmissionForTextInput(g_render_doc,
                text_index, &info, NULL, 0, NULL, 0);
    } else {
        result = PCore_FormDialogSubmissionAt(g_render_doc, x, y, &info,
                NULL, 0, NULL, 0);
    }
    if (result == 0) {
        return 0;
    }
    if (result == 2 || result == 5) {
        return 1;
    }
    if (result != 4 || info.dialog_id_bytes <= 0 ||
            info.return_value_bytes < 0 ||
            info.dialog_id_bytes >= PBROWSER_SCRIPT_DIALOG_ID_MAX ||
            info.return_value_bytes >= PBROWSER_SCRIPT_DIALOG_VALUE_MAX) {
        show_error(L"Dialog form failed",
                "Could not resolve the bounded dialog form result");
        return 1;
    }
    dialog_id = (char *) malloc((size_t) info.dialog_id_bytes + 1);
    return_value = (char *) malloc(
            (size_t) info.return_value_bytes + 1);
    if (dialog_id == NULL || return_value == NULL) {
        free(dialog_id);
        free(return_value);
        show_error(L"Dialog form failed", "Out of memory");
        return 1;
    }
    if (from_text_input) {
        result = PCore_FormDialogSubmissionForTextInput(g_render_doc,
                text_index, &info, dialog_id,
                info.dialog_id_bytes + 1, return_value,
                info.return_value_bytes + 1);
    } else {
        result = PCore_FormDialogSubmissionAt(g_render_doc, x, y, &info,
                dialog_id, info.dialog_id_bytes + 1, return_value,
                info.return_value_bytes + 1);
    }
    closed = 0;
    if (result == 1 && pcore_native_script_active() &&
            g_browser_script_session.bridge != NULL &&
            g_browser_script_session.bridge->session != NULL) {
        if (PBrowser_ScriptSessionCloseDialogById(
                g_browser_script_session.bridge->session, dialog_id,
                return_value, &closed) != PSCRIPT_OK) {
            result = 4;
        }
    }
    if (result == 1 && closed) {
        pcore_toggle_focus_clear();
        pcore_button_focus_clear();
        pcore_disclosure_focus_clear();
        pcore_sequential_focus_clear();
        if (hwnd != NULL) {
            pcore_request_interaction_restyle(hwnd);
        }
    } else if (result != 1) {
        show_error(L"Dialog form failed",
                "The form changed while its dialog result was committed");
    }
    free(dialog_id);
    free(return_value);
    return 1;
}

static int pcore_handle_form_button_default(HWND hwnd, int x, int y,
        int kind)
{
    PCoreFormSubmissionInfo info;
    PCoreFormValidationInfo validation;
    char action_probe[1];
    char body_probe[1];
    char *action;
    char *body;
    int result;

    /* An ordinary button has no Core form mutation, but it still consumes
     * the trusted click so the window procedure does not treat it as a
     * background tap and close the page. */
    if (kind == 9) {
        return 1;
    }
    if (kind != 7 && kind != 8) {
        return 0;
    }
    result = PCore_FormResetAt(g_render_doc, x, y);
    if (result != 0) {
        if (result == 1) {
            if (hwnd != NULL && pcore_restyle_form_state(hwnd, 0) != 0) {
                show_error(L"Form reset failed",
                        "The form reset but could not be re-laid out");
            }
        } else if (result == 3) {
            show_error(L"Form reset failed",
                    "Could not restore the form's initial state");
        }
        return 1;
    }
    memset(&info, 0, sizeof(info));
    action_probe[0] = '\0';
    body_probe[0] = '\0';
    result = PCore_FormSubmissionAt(g_render_doc, x, y, &info,
            action_probe, sizeof(action_probe),
            body_probe, sizeof(body_probe));
    if (result == 0) {
        return 0;
    }
    if (result == 2) {
        return 1;
    }
    if (result == 5) {
        if (PCore_FormValidationAt(g_render_doc, x, y, &validation)) {
            pcore_handle_invalid_form(hwnd, &validation);
        }
        return 1;
    }
    if (result == 6) {
        return pcore_handle_dialog_form_default(hwnd, x, y, 0, 0);
    }
    if (result == 3) {
        navigate_multipart_submission(hwnd,
                PCore_MultipartSubmissionAt(g_render_doc, x, y));
        return 1;
    }
    if (result == 1) {
        navigate_form_submission(hwnd, info.method,
                action_probe, body_probe);
        return 1;
    }
    if (info.method == 0 || info.action_bytes < 0 ||
            info.body_bytes < 0) {
        show_error(L"Form submission failed",
                "Could not enumerate successful form controls");
        return 1;
    }
    action = (char *) malloc((size_t) info.action_bytes + 1);
    body = (char *) malloc((size_t) info.body_bytes + 1);
    if (action == NULL || body == NULL) {
        free(action);
        free(body);
        show_error(L"Form submission failed", "Out of memory");
        return 1;
    }
    result = PCore_FormSubmissionAt(g_render_doc, x, y, &info,
            action, info.action_bytes + 1,
            body, info.body_bytes + 1);
    if (result == 1) {
        navigate_form_submission(hwnd, info.method, action, body);
    } else if (result == 5 &&
            PCore_FormValidationAt(g_render_doc, x, y, &validation)) {
        pcore_handle_invalid_form(hwnd, &validation);
    } else {
        show_error(L"Form submission failed",
                "The form changed while its data was being collected");
    }
    free(action);
    free(body);
    return 1;
}

static int pcore_handle_form_button(HWND hwnd, int x, int y)
{
    PCoreFormValidationInfo validation;
    int kind;

    kind = 0;
    if (pcore_form_button_kind_at(x, y, &kind)) {
        if (kind == 8) {
            if (!pcore_browser_script_dispatch_form_event_at(x, y,
                    "reset")) {
                return 1;
            }
        } else if (kind == 7 && PCore_FormValidationAt(g_render_doc,
                x, y, &validation) && validation.valid) {
            if (!pcore_browser_script_dispatch_form_event_at(x, y,
                    "submit")) {
                return 1;
            }
        }
    }
    return pcore_handle_form_button_default(hwnd, x, y, kind);
}

static void pcore_handle_form_enter(HWND hwnd, unsigned int text_index)
{
    PCoreFormSubmissionInfo info;
    PCoreFormValidationInfo validation;
    char action_probe[1];
    char body_probe[1];
    char *action;
    char *body;
    int result;

    memset(&info, 0, sizeof(info));
    action_probe[0] = '\0';
    body_probe[0] = '\0';
    result = PCore_FormSubmissionForTextInput(g_render_doc, text_index,
            &info, action_probe, sizeof(action_probe),
            body_probe, sizeof(body_probe));
    if (result == 0) {
        return;
    }
    if (result == 5) {
        if (PCore_FormValidationForTextInput(g_render_doc, text_index,
                &validation)) {
            pcore_handle_invalid_form(hwnd, &validation);
        }
        return;
    }
    if (result == 6) {
        if (pcore_browser_script_dispatch_form_event_for_text_input(
                text_index, "submit")) {
            (void) pcore_handle_dialog_form_default(hwnd, 0, 0,
                    text_index, 1);
        }
        return;
    }
    if (result == 3) {
        if (pcore_browser_script_dispatch_form_event_for_text_input(
                text_index, "submit")) {
            navigate_multipart_submission(hwnd,
                    PCore_MultipartSubmissionForTextInput(g_render_doc,
                            text_index));
        }
        return;
    }
    action = NULL;
    body = NULL;
    if (result == 4 && info.method != 0 &&
            info.action_bytes >= 0 && info.body_bytes >= 0) {
        action = (char *) malloc((size_t) info.action_bytes + 1);
        body = (char *) malloc((size_t) info.body_bytes + 1);
        if (action != NULL && body != NULL) {
            result = PCore_FormSubmissionForTextInput(g_render_doc,
                    text_index, &info,
                    action, info.action_bytes + 1,
                    body, info.body_bytes + 1);
        }
    } else if (result == 1) {
        action = action_probe;
        body = body_probe;
    }
    if (result == 1 && action != NULL && body != NULL) {
        if (pcore_browser_script_dispatch_form_event_for_text_input(
                text_index, "submit")) {
            if (g_native_form_enter_probe) {
                g_native_form_enter_probe_seen = 1;
                g_native_form_enter_probe_ok =
                        info.method == 1 &&
                        strcmp(action, "/implicit") == 0 &&
                        strcmp(body, g_native_form_enter_expected) == 0;
            } else {
                navigate_form_submission(hwnd, info.method, action, body);
            }
        }
    } else if (result == 5 &&
            PCore_FormValidationForTextInput(g_render_doc, text_index,
                    &validation)) {
        pcore_handle_invalid_form(hwnd, &validation);
    } else {
        show_error(L"Form submission failed",
                "Could not collect the form after Enter");
    }
    if (action != action_probe) {
        free(action);
    }
    if (body != body_probe) {
        free(body);
    }
}

static void pcore_invalidate_form_dirty(HWND hwnd,
        int x, int y, int width, int height)
{
    RECT dirty;

    if (width <= 0 || height <= 0) {
        return;
    }
    dirty.left = x - g_scroll_x;
    dirty.top = y - g_scroll_y;
    dirty.right = x - g_scroll_x + width;
    dirty.bottom = dirty.top + height;
    InvalidateRect(hwnd, &dirty, FALSE);
}

/* A summary is a document control rather than a native child window. Keep a
 * bounded geometry snapshot for keyboard activation and validate it against
 * the current laid-out box before consuming a key. Without a node handle or
 * an id in this host-side state, an unexpected reflow must fail closed rather
 * than activating a different summary that moved into the old point. */
static int pcore_disclosure_focus_track_at(int x, int y)
{
    int summary_x;
    int summary_y;
    int summary_w;
    int summary_h;

    summary_x = 0;
    summary_y = 0;
    summary_w = 0;
    summary_h = 0;
    if (g_render_doc == NULL ||
            PCore_DisclosureInfoAt(g_render_doc, x, y,
            &summary_x, &summary_y, &summary_w, &summary_h, NULL) != 1 ||
            summary_w <= 0 || summary_h <= 0) {
        pcore_disclosure_focus_clear();
        return 0;
    }
    pcore_toggle_focus_clear();
    pcore_button_focus_clear();
    g_disclosure_focus_document = g_render_doc;
    g_disclosure_focus_x = summary_x;
    g_disclosure_focus_y = summary_y;
    g_disclosure_focus_w = summary_w;
    g_disclosure_focus_h = summary_h;
    g_disclosure_focus_valid = 1;
    g_disclosure_space_pending = 0;
    return 1;
}

static int pcore_disclosure_focus_current(int *out_x, int *out_y)
{
    int summary_x;
    int summary_y;
    int summary_w;
    int summary_h;

    if (!g_disclosure_focus_valid ||
            g_disclosure_focus_document != g_render_doc ||
            g_render_doc == NULL || g_disclosure_focus_w <= 0 ||
            g_disclosure_focus_h <= 0) {
        return 0;
    }
    summary_x = 0;
    summary_y = 0;
    summary_w = 0;
    summary_h = 0;
    if (PCore_DisclosureInfoAt(g_render_doc,
            g_disclosure_focus_x + g_disclosure_focus_w / 2,
            g_disclosure_focus_y + g_disclosure_focus_h / 2,
            &summary_x, &summary_y, &summary_w, &summary_h, NULL) != 1 ||
            summary_x != g_disclosure_focus_x ||
            summary_y != g_disclosure_focus_y ||
            summary_w != g_disclosure_focus_w ||
            summary_h != g_disclosure_focus_h) {
        pcore_disclosure_focus_clear();
        return 0;
    }
    if (out_x != NULL) {
        *out_x = summary_x + summary_w / 2;
    }
    if (out_y != NULL) {
        *out_y = summary_y + summary_h / 2;
    }
    return 1;
}

/* Disclosure state lives in positron_core. The host only forwards a trusted
 * point and schedules the existing full style/layout transaction so that
 * opening or closing a details element reflows all following content. */
static int pcore_handle_disclosure(HWND hwnd, int x, int y)
{
    int result;

    result = PCore_DisclosureToggleAt(g_render_doc, x, y, NULL);
    if (result > 0) {
        pcore_request_interaction_restyle(hwnd);
        return 1;
    }
    return 0;
}

/* HTML summary keyboard activation follows the native button timing shape:
 * Enter commits on keydown, while Space commits on keyup. Keydown remains
 * cancelable; a held key dispatches repeat events but never repeats the
 * trusted click. The browser event bridge owns propagation/cancellation and
 * Core owns the open-state mutation; this host function only joins them at
 * the WM message boundary. */
static int pcore_handle_disclosure_keyboard(HWND hwnd, UINT msg,
        WPARAM wp, LPARAM lp, int system_key)
{
    int x;
    int y;
    int keydown;
    int keyup;

    if (wp != VK_SPACE && wp != VK_RETURN) {
        return 0;
    }
    if (!g_disclosure_focus_valid ||
            g_disclosure_focus_document != g_render_doc) {
        return 0;
    }
    if (!pcore_disclosure_focus_current(&x, &y)) {
        /* A previously focused summary moved or disappeared after a reflow.
         * Consume this activation key without falling through to the window
         * close fallback used by an otherwise unfocused render view. */
        return 1;
    }
    keydown = (msg == WM_KEYDOWN || msg == WM_SYSKEYDOWN);
    keyup = (msg == WM_KEYUP || msg == WM_SYSKEYUP);
    if (keydown) {
        if (!pcore_browser_script_dispatch_key_at(x, y, "keydown",
                wp, lp, system_key, 0)) {
            return 1;
        }
        if ((lp & 0x40000000L) != 0) {
            return 1;
        }
        if (wp == VK_SPACE) {
            g_disclosure_space_pending = 1;
            return 1;
        }
        if (pcore_browser_script_dispatch_click_at(x, y)) {
            (void) pcore_handle_disclosure(hwnd, x, y);
        }
        return 1;
    }
    if (keyup) {
        (void) pcore_browser_script_dispatch_key_at(x, y, "keyup",
                wp, lp, system_key, 0);
        if (wp == VK_SPACE && g_disclosure_space_pending) {
            g_disclosure_space_pending = 0;
            if (pcore_browser_script_dispatch_click_at(x, y)) {
                (void) pcore_handle_disclosure(hwnd, x, y);
            }
        }
        return 1;
    }
    return 0;
}

static int pcore_form_toggle_control_at(int x, int y,
        unsigned int *out_index, int *out_kind, int *out_selected,
        int *out_disabled)
{
    unsigned int index;
    int left;
    int top;
    int width;
    int height;
    int kind;
    int selected;
    int disabled;

    if (g_render_doc == NULL) {
        return 0;
    }
    index = 0;
    while (PCore_FormControlInfo(g_render_doc, index, &left, &top,
            &width, &height, &kind, &selected, &disabled) == 0) {
        if ((kind == 1 || kind == 2) && width > 0 && height > 0 &&
                x >= left && x < left + width &&
                y >= top && y < top + height) {
            if (out_index != NULL) {
                *out_index = index;
            }
            if (out_kind != NULL) {
                *out_kind = kind;
            }
            if (out_selected != NULL) {
                *out_selected = selected ? 1 : 0;
            }
            if (out_disabled != NULL) {
                *out_disabled = disabled ? 1 : 0;
            }
            return 1;
        }
        index++;
    }
    return 0;
}

static void pcore_toggle_focus_set(unsigned int index, int kind)
{
    if (g_render_doc == NULL || (kind != 1 && kind != 2)) {
        pcore_toggle_focus_clear();
        return;
    }
    pcore_disclosure_focus_clear();
    pcore_button_focus_clear();
    g_toggle_focus_document = g_render_doc;
    g_toggle_focus_index = index;
    g_toggle_focus_kind = kind;
    g_toggle_focus_valid = 1;
}

static int pcore_toggle_focus_track_at(int x, int y)
{
    unsigned int index;
    int kind;
    int disabled;

    index = 0;
    kind = 0;
    disabled = 0;
    if (!pcore_form_toggle_control_at(x, y, &index, &kind,
            NULL, &disabled) || disabled) {
        pcore_toggle_focus_clear();
        return 0;
    }
    pcore_toggle_focus_set(index, kind);
    return 1;
}

static int pcore_toggle_focus_current(int *out_x, int *out_y)
{
    int left;
    int top;
    int width;
    int height;
    int kind;
    int disabled;

    if (!g_toggle_focus_valid ||
            g_toggle_focus_document != g_render_doc ||
            g_render_doc == NULL) {
        return 0;
    }
    if (PCore_FormControlInfo(g_render_doc, g_toggle_focus_index,
            &left, &top, &width, &height, &kind, NULL, &disabled) != 0 ||
            kind != g_toggle_focus_kind || (kind != 1 && kind != 2) ||
            disabled || width <= 0 || height <= 0) {
        pcore_toggle_focus_clear();
        return 0;
    }
    if (out_x != NULL) {
        *out_x = left + width / 2;
    }
    if (out_y != NULL) {
        *out_y = top + height / 2;
    }
    return 1;
}

static void pcore_button_focus_set(unsigned int index, int kind)
{
    if (g_render_doc == NULL || kind < 7 || kind > 9) {
        pcore_button_focus_clear();
        return;
    }
    pcore_toggle_focus_clear();
    pcore_disclosure_focus_clear();
    g_button_focus_document = g_render_doc;
    g_button_focus_index = index;
    g_button_focus_kind = kind;
    g_button_focus_valid = 1;
    g_button_space_pending = 0;
}

static int pcore_button_focus_track_at(int x, int y)
{
    unsigned int index;
    int kind;
    int disabled;

    index = 0;
    kind = 0;
    disabled = 0;
    if (!pcore_form_button_control_at(x, y, &index, &kind,
            &disabled) || disabled) {
        pcore_button_focus_clear();
        return 0;
    }
    pcore_button_focus_set(index, kind);
    return 1;
}

static int pcore_button_focus_current(int *out_x, int *out_y,
        unsigned int *out_index, int *out_kind, int *out_disabled)
{
    int left;
    int top;
    int width;
    int height;
    int kind;
    int disabled;

    if (!g_button_focus_valid ||
            g_button_focus_document != g_render_doc ||
            g_render_doc == NULL) {
        return 0;
    }
    if (PCore_FormControlInfo(g_render_doc, g_button_focus_index,
            &left, &top, &width, &height, &kind, NULL, &disabled) != 0 ||
            kind != g_button_focus_kind || kind < 7 || kind > 9 ||
            disabled || width <= 0 || height <= 0) {
        pcore_button_focus_clear();
        return 0;
    }
    if (out_x != NULL) {
        *out_x = left + width / 2;
    }
    if (out_y != NULL) {
        *out_y = top + height / 2;
    }
    if (out_index != NULL) {
        *out_index = g_button_focus_index;
    }
    if (out_kind != NULL) {
        *out_kind = kind;
    }
    if (out_disabled != NULL) {
        *out_disabled = disabled ? 1 : 0;
    }
    return 1;
}

#define PCORE_SEQUENTIAL_FOCUS_MAX 128

static int pcore_sequential_focus_kind_native(int kind)
{
    return (kind >= 3 && kind <= 6) ||
            kind == PCORE_FOCUS_TARGET_CONTENTEDITABLE;
}

static int pcore_sequential_focus_info_at(const char *modal_id,
        unsigned int index, PCoreFocusTargetInfo *out_info)
{
    if (modal_id != NULL && modal_id[0] != '\0') {
        return PCore_FocusTargetInfoWithin(g_render_doc, modal_id, index,
                out_info);
    }
    return PCore_FocusTargetInfo(g_render_doc, index, out_info);
}

static void pcore_sequential_focus_store(unsigned int index,
        const PCoreFocusTargetInfo *info)
{
    char modal_id[PBROWSER_SCRIPT_DIALOG_ID_MAX];
    int scope;

    if (info == NULL) {
        pcore_sequential_focus_clear();
        return;
    }
    scope = pcore_sequential_focus_scope(modal_id, sizeof(modal_id));
    if (scope < 0) {
        pcore_sequential_focus_clear();
        return;
    }
    g_sequential_focus_document = g_render_doc;
    g_sequential_focus_index = index;
    g_sequential_focus_kind = info->kind;
    g_sequential_focus_x = info->x;
    g_sequential_focus_y = info->y;
    g_sequential_focus_w = info->width;
    g_sequential_focus_h = info->height;
    if (scope > 0) {
        memcpy(g_sequential_focus_modal_id, modal_id,
                sizeof(g_sequential_focus_modal_id));
    } else {
        g_sequential_focus_modal_id[0] = '\0';
    }
    g_sequential_focus_valid = 1;
}

static int pcore_sequential_focus_current(PCoreFocusTargetInfo *out_info)
{
    PCoreFocusTargetInfo info;
    char modal_id[PBROWSER_SCRIPT_DIALOG_ID_MAX];
    int scope;

    if (!g_sequential_focus_valid ||
            g_sequential_focus_document != g_render_doc ||
            g_render_doc == NULL) {
        return 0;
    }
    scope = pcore_sequential_focus_scope(modal_id, sizeof(modal_id));
    if (scope < 0 || (scope > 0 &&
            strcmp(modal_id, g_sequential_focus_modal_id) != 0) ||
            (scope == 0 && g_sequential_focus_modal_id[0] != '\0')) {
        pcore_sequential_focus_clear();
        return 0;
    }
    memset(&info, 0, sizeof(info));
    if (pcore_sequential_focus_info_at(scope > 0 ? modal_id : NULL,
            g_sequential_focus_index, &info) != 0 ||
            info.kind != g_sequential_focus_kind ||
            info.x != g_sequential_focus_x ||
            info.y != g_sequential_focus_y ||
            info.width != g_sequential_focus_w ||
            info.height != g_sequential_focus_h) {
        pcore_sequential_focus_clear();
        return 0;
    }
    if (out_info != NULL) {
        *out_info = info;
    }
    return 1;
}

/* Return the sequential-focus index for an already resolved target. The
 * autofocus path uses this only to seed the next Tab transaction; matching
 * the complete geometry/kind snapshot makes stale or ambiguous data fail
 * closed rather than moving the keyboard order unexpectedly. */
static int pcore_sequential_focus_index_for_target(
        const PCoreFocusTargetInfo *wanted, unsigned int *out_index)
{
    PCoreFocusTargetInfo info;
    char modal_id[PBROWSER_SCRIPT_DIALOG_ID_MAX];
    unsigned int index;
    int scope;

    if (wanted == NULL || g_render_doc == NULL) {
        return 0;
    }
    scope = pcore_sequential_focus_scope(modal_id, sizeof(modal_id));
    if (scope < 0) {
        return 0;
    }
    for (index = 0; index < PCORE_SEQUENTIAL_FOCUS_MAX; index++) {
        memset(&info, 0, sizeof(info));
        if (pcore_sequential_focus_info_at(scope > 0 ? modal_id : NULL,
                index, &info) != 0) {
            break;
        }
        if (info.kind == wanted->kind && info.x == wanted->x &&
                info.y == wanted->y && info.width == wanted->width &&
                info.height == wanted->height) {
            if (out_index != NULL) {
                *out_index = index;
            }
            return 1;
        }
    }
    return 0;
}

static int pcore_sequential_focus_target_at(int x, int y,
        unsigned int *out_index, PCoreFocusTargetInfo *out_info)
{
    PCoreFocusTargetInfo info;
    char modal_id[PBROWSER_SCRIPT_DIALOG_ID_MAX];
    unsigned int index;
    int scope;

    scope = pcore_sequential_focus_scope(modal_id, sizeof(modal_id));
    if (scope < 0) {
        return 0;
    }
    for (index = 0; index < PCORE_SEQUENTIAL_FOCUS_MAX; index++) {
        memset(&info, 0, sizeof(info));
        if (pcore_sequential_focus_info_at(scope > 0 ? modal_id : NULL,
                index, &info) != 0) {
            break;
        }
        if (info.width > 0 && info.height > 0 &&
                x >= info.x && x < info.x + info.width &&
                y >= info.y && y < info.y + info.height) {
            if (out_index != NULL) {
                *out_index = index;
            }
            if (out_info != NULL) {
                *out_info = info;
            }
            return 1;
        }
    }
    return 0;
}

static void pcore_sequential_focus_track_at(int x, int y)
{
    unsigned int index;
    PCoreFocusTargetInfo info;

    if (g_render_doc == NULL ||
            !pcore_sequential_focus_target_at(x, y, &index, &info)) {
        pcore_sequential_focus_clear();
        return;
    }
    pcore_sequential_focus_store(index, &info);
}

static HWND pcore_sequential_focus_native_window(
        const PCoreFocusTargetInfo *target)
{
    PCoreSelectInfo select_info;
    unsigned int i;
    int multiline;
    int kind;
    int x;
    int y;
    int width;
    int height;
    int password;

    if (target == NULL || g_render_doc == NULL) {
        return NULL;
    }
    if (target->kind >= 3 && target->kind <= 5) {
        for (i = 0; i < g_native_edit_count; i++) {
            multiline = 0;
            if (g_native_edits[i].hwnd == NULL ||
                    g_native_edits[i].content_editable ||
                    !pcore_native_edit_geometry_info(&g_native_edits[i],
                    &x, &y, &width, &height, &password, NULL) ||
                    PCore_TextInputIsMultiline(g_render_doc,
                    g_native_edits[i].text_index, &multiline) != 0) {
                continue;
            }
            kind = multiline ? 5 : (password ? 4 : 3);
            if (kind == target->kind && x == target->x &&
                    y == target->y && width == target->width &&
                    height == target->height) {
                return g_native_edits[i].hwnd;
            }
        }
    } else if (target->kind == PCORE_FOCUS_TARGET_CONTENTEDITABLE) {
        for (i = 0; i < g_native_edit_count; i++) {
            if (g_native_edits[i].hwnd == NULL ||
                    !g_native_edits[i].content_editable ||
                    !pcore_native_edit_geometry_info(&g_native_edits[i],
                    &x, &y, &width, &height, NULL, NULL)) {
                continue;
            }
            if (x == target->x && y == target->y &&
                    width == target->width && height == target->height) {
                return g_native_edits[i].hwnd;
            }
        }
    } else if (target->kind == 6) {
        for (i = 0; i < g_native_select_count; i++) {
            if (g_native_selects[i].hwnd == NULL ||
                    PCore_SelectInfo(g_render_doc,
                    g_native_selects[i].select_index, &select_info) != 0) {
                continue;
            }
            if (select_info.x == target->x &&
                    select_info.y == target->y &&
                    select_info.width == target->width &&
                    select_info.height == target->height) {
                return g_native_selects[i].hwnd;
            }
        }
    }
    return NULL;
}

static int pcore_sequential_focus_capture_native(HWND control)
{
    PCoreSelectInfo select_info;
    PCoreFocusTargetInfo target;
    unsigned int i;
    unsigned int target_index;
    int multiline;
    int target_kind;
    int x;
    int y;
    int width;
    int height;
    int password;
    char modal_id[PBROWSER_SCRIPT_DIALOG_ID_MAX];
    int scope;

    if (control == NULL || g_render_doc == NULL) {
        return 0;
    }
    scope = pcore_sequential_focus_scope(modal_id, sizeof(modal_id));
    if (scope < 0) {
        pcore_sequential_focus_clear();
        return 0;
    }
    memset(&target, 0, sizeof(target));
    for (i = 0; i < g_native_edit_count; i++) {
        if (g_native_edits[i].hwnd != control) {
            continue;
        }
        if (!pcore_native_edit_geometry_info(&g_native_edits[i],
                &x, &y, &width, &height, &password, NULL)) {
            continue;
        }
        if (g_native_edits[i].content_editable) {
            target_kind = PCORE_FOCUS_TARGET_CONTENTEDITABLE;
        } else {
            multiline = 0;
            if (PCore_TextInputIsMultiline(g_render_doc,
                    g_native_edits[i].text_index, &multiline) != 0) {
                continue;
            }
            target_kind = multiline ? 5 : (password ? 4 : 3);
        }
        for (target_index = 0;
                target_index < PCORE_SEQUENTIAL_FOCUS_MAX;
                target_index++) {
            if (pcore_sequential_focus_info_at(scope > 0 ? modal_id : NULL,
                    target_index, &target) != 0) {
                break;
            }
            if (target.kind == target_kind && target.x == x &&
                    target.y == y && target.width == width &&
                    target.height == height) {
                pcore_sequential_focus_store(target_index, &target);
                return 1;
            }
        }
        break;
    }
    for (i = 0; i < g_native_select_count; i++) {
        if (g_native_selects[i].hwnd != control ||
                PCore_SelectInfo(g_render_doc,
                g_native_selects[i].select_index, &select_info) != 0) {
            continue;
        }
        for (target_index = 0;
                target_index < PCORE_SEQUENTIAL_FOCUS_MAX;
                target_index++) {
            if (pcore_sequential_focus_info_at(scope > 0 ? modal_id : NULL,
                    target_index, &target) != 0) {
                break;
            }
            if (target.kind == 6 && target.x == select_info.x &&
                    target.y == select_info.y &&
                    target.width == select_info.width &&
                    target.height == select_info.height) {
                pcore_sequential_focus_store(target_index, &target);
                return 1;
            }
        }
        break;
    }
    pcore_sequential_focus_clear();
    return 0;
}

static void pcore_sequential_focus_dispatch_change(
        const PCoreFocusTargetInfo *old_target, int old_native)
{
    if (old_target != NULL && !old_native) {
        pcore_browser_script_dispatch_focus_at(
                old_target->x + old_target->width / 2,
                old_target->y + old_target->height / 2, "blur", 0);
        pcore_browser_script_dispatch_focus_at(
                old_target->x + old_target->width / 2,
                old_target->y + old_target->height / 2, "focusout", 1);
    }
}

static void pcore_sequential_focus_prepare_core(
        const PCoreFocusTargetInfo *target)
{
    int x;
    int y;

    if (target == NULL) {
        pcore_toggle_focus_clear();
        pcore_button_focus_clear();
        pcore_disclosure_focus_clear();
        return;
    }
    x = target->x + target->width / 2;
    y = target->y + target->height / 2;
    if (target->kind == 1 || target->kind == 2) {
        (void) pcore_toggle_focus_track_at(x, y);
    } else if (target->kind >= 7 && target->kind <= 9) {
        (void) pcore_button_focus_track_at(x, y);
    } else if (target->kind == PCORE_FOCUS_TARGET_DISCLOSURE) {
        (void) pcore_disclosure_focus_track_at(x, y);
    } else {
        pcore_toggle_focus_clear();
        pcore_button_focus_clear();
        pcore_disclosure_focus_clear();
    }
}

static void pcore_sequential_focus_reveal(HWND hwnd,
        const PCoreFocusTargetInfo *target)
{
    RECT client;
    int viewport_width;
    int viewport_height;
    int target_scroll_x;
    int target_scroll;

    if (hwnd == NULL || target == NULL || !IsWindow(hwnd)) {
        return;
    }
    GetClientRect(hwnd, &client);
    viewport_width = client.right - client.left;
    viewport_height = client.bottom - client.top;
    if (viewport_width <= 0 || viewport_height <= 0) {
        return;
    }
    target_scroll_x = g_scroll_x;
    if (target->x < g_scroll_x + 4) {
        target_scroll_x = target->x - 4;
    } else if (target->x + target->width >
            g_scroll_x + viewport_width - 4) {
        target_scroll_x = target->x + target->width - viewport_width + 4;
    }
    target_scroll = g_scroll_y;
    if (target->y < g_scroll_y + 4) {
        target_scroll = target->y - 4;
    } else if (target->y + target->height >
            g_scroll_y + viewport_height - 4) {
        target_scroll = target->y + target->height - viewport_height + 4;
    }
    if (target_scroll_x != g_scroll_x || target_scroll != g_scroll_y) {
        (void) pcore_scroll_to_xy(hwnd, target_scroll_x, target_scroll);
    }
}

static int pcore_sequential_focus_apply(HWND hwnd, unsigned int index,
        const PCoreFocusTargetInfo *target)
{
    PCoreFocusTargetInfo old_target;
    HWND native_window;
    int old_valid;
    int old_native;
    int new_native;
    int x;
    int y;
    int result;

    if (hwnd == NULL || target == NULL || g_render_doc == NULL ||
            target->width <= 0 || target->height <= 0) {
        return 0;
    }
    old_valid = pcore_sequential_focus_current(&old_target);
    if (old_valid && old_target.kind == target->kind &&
            old_target.x == target->x && old_target.y == target->y &&
            old_target.width == target->width &&
            old_target.height == target->height) {
        return 1;
    }
    old_native = old_valid && pcore_sequential_focus_kind_native(
            old_target.kind) && GetFocus() != hwnd;
    new_native = pcore_sequential_focus_kind_native(target->kind);
    pcore_sequential_focus_dispatch_change(old_valid ? &old_target : NULL,
            old_native);
    pcore_sequential_focus_reveal(hwnd, target);
    if (new_native) {
        native_window = pcore_sequential_focus_native_window(target);
        if (native_window == NULL || !IsWindowEnabled(native_window)) {
            return 0;
        }
        SetFocus(native_window);
        if (GetFocus() != native_window) {
            return 0;
        }
        pcore_sequential_focus_store(index, target);
        return 1;
    }
    SetFocus(hwnd);
    if (GetFocus() != hwnd) {
        return 0;
    }
    x = target->x + target->width / 2;
    y = target->y + target->height / 2;
    result = PCore_InteractionSetAt(g_render_doc, x, y,
            PCORE_INTERACTION_FOCUS);
    if (result < 0) {
        return 0;
    }
    pcore_sequential_focus_prepare_core(target);
    pcore_sequential_focus_store(index, target);
    if (result > 0) {
        pcore_request_interaction_restyle(hwnd);
    }
    pcore_browser_script_dispatch_focus_at(x, y, "focus", 0);
    pcore_browser_script_dispatch_focus_at(x, y, "focusin", 1);
    return 1;
}

/* Apply the document's first eligible autofocus target after layout and
 * native-child creation. Browser remains the owner of id-addressable focus
 * events and nested/page reveal; the id-less path uses Core's explicit
 * interaction setter and the same host platform/event adapter. */
static int pcore_browser_script_autofocus_apply(HWND hwnd)
{
    PCoreFocusTargetInfo target;
    PBrowserScriptFocusRequestInfoEx request;
    PBrowserScriptFocusRequestResult request_result;
    char element_id[PBROWSER_SCRIPT_ACTIVE_ELEMENT_ID_MAX];
    unsigned int index;
    int id_bytes;
    int rc;
    int changed;

    if (g_render_doc == NULL) {
        return 0;
    }
    memset(&target, 0, sizeof(target));
    memset(element_id, 0, sizeof(element_id));
    id_bytes = 0;
    rc = PCore_AutofocusTargetInfo(g_render_doc, &target, element_id,
            sizeof(element_id), &id_bytes);
    if (rc != 0 || target.width <= 0 || target.height <= 0) {
        return 0;
    }
    if (element_id[0] != '\0' && pcore_native_script_active() &&
            g_browser_script_session.bridge != NULL &&
            g_browser_script_session.bridge->session != NULL) {
        memset(&request, 0, sizeof(request));
        request.size = sizeof(request);
        request.element_id = element_id;
        request.focused = 1;
        request.prevent_scroll = 0;
        memset(&request_result, 0, sizeof(request_result));
        request_result.size = sizeof(request_result);
        rc = PBrowser_ScriptSessionDispatchFocusRequestEx(
                g_browser_script_session.bridge->session, &request,
                &request_result);
        if (rc == PSCRIPT_OK) {
            if (pcore_sequential_focus_index_for_target(&target, &index)) {
                pcore_sequential_focus_store(index, &target);
            }
            return 1;
        }
    }
    if (element_id[0] == '\0') {
        changed = PCore_InteractionFocusAutofocus(g_render_doc);
        if (changed < 0) {
            return 0;
        }
        if (pcore_sequential_focus_index_for_target(&target, &index)) {
            pcore_sequential_focus_store(index, &target);
        }
        if (changed == 0) {
            return 1;
        }
        pcore_sequential_focus_reveal(hwnd, &target);
        if (pcore_browser_script_focus_native_target(&target) == 0) {
            if (hwnd != NULL && IsWindow(hwnd)) {
                SetFocus(hwnd);
            }
        }
        if (pcore_native_script_active()) {
            if (PCore_EventDispatchFocus(g_render_doc, "focus", 0, 0,
                    NULL) < 0 || PCore_EventDispatchFocus(g_render_doc,
                    "focusin", 1, 0, NULL) < 0) {
                return 0;
            }
        }
        pcore_request_interaction_restyle(hwnd);
        return 1;
    }
    if (pcore_sequential_focus_index_for_target(&target, &index)) {
        return pcore_sequential_focus_apply(hwnd, index, &target);
    }
    return 0;
}

static int pcore_sequential_focus_move(HWND hwnd, int backwards,
        int dispatch_key, WPARAM wp, LPARAM lp, int system_key)
{
    PCoreFocusTargetInfo current_target;
    PCoreFocusTargetInfo next_target;
    unsigned int count;
    unsigned int current_index;
    unsigned int next_index;
    int current_valid;
    int default_allowed;
    char modal_id[PBROWSER_SCRIPT_DIALOG_ID_MAX];
    int scope;

    if (hwnd == NULL || g_render_doc == NULL) {
        return 0;
    }
    scope = pcore_sequential_focus_scope(modal_id, sizeof(modal_id));
    if (scope < 0) {
        return 1;
    }
    current_valid = pcore_sequential_focus_current(&current_target);
    current_index = g_sequential_focus_index;
    if (dispatch_key && current_valid) {
        default_allowed = pcore_browser_script_dispatch_key_at(
                current_target.x + current_target.width / 2,
                current_target.y + current_target.height / 2,
                "keydown", wp, lp, system_key, 0);
        if (!default_allowed || (lp & 0x40000000L) != 0) {
            return 1;
        }
    }
    count = 0;
    while (count < PCORE_SEQUENTIAL_FOCUS_MAX) {
        memset(&next_target, 0, sizeof(next_target));
        if (pcore_sequential_focus_info_at(scope > 0 ? modal_id : NULL,
                count, &next_target) != 0) {
            break;
        }
        count++;
    }
    if (count == 0) {
        return 0;
    }
    if (!current_valid || current_index >= count) {
        next_index = backwards ? count - 1 : 0;
    } else if (backwards) {
        next_index = (current_index == 0) ? count - 1 :
                current_index - 1;
    } else {
        next_index = (current_index + 1 >= count) ? 0 :
                current_index + 1;
    }
    if (pcore_sequential_focus_info_at(scope > 0 ? modal_id : NULL,
            next_index, &next_target) != 0) {
        return 1;
    }
    (void) pcore_sequential_focus_apply(hwnd, next_index, &next_target);
    return 1;
}

static int pcore_handle_sequential_tab(HWND hwnd, UINT msg, WPARAM wp,
        LPARAM lp, int system_key)
{
    PCoreFocusTargetInfo target;

    if (wp != VK_TAB) {
        return 0;
    }
    if (msg == WM_KEYDOWN || msg == WM_SYSKEYDOWN) {
        return pcore_sequential_focus_move(hwnd,
                GetKeyState(VK_SHIFT) < 0, 1, wp, lp, system_key);
    }
    if (msg == WM_KEYUP || msg == WM_SYSKEYUP) {
        if (pcore_sequential_focus_current(&target)) {
            (void) pcore_browser_script_dispatch_key_at(
                    target.x + target.width / 2,
                    target.y + target.height / 2,
                    "keyup", wp, lp, system_key, 0);
            return 1;
        }
    }
    return 0;
}

static int pcore_handle_sequential_link_keyboard(HWND hwnd, UINT msg,
        WPARAM wp, LPARAM lp, int system_key)
{
    PCoreFocusTargetInfo target;
    char href[1024];
    char link_target[PBROWSER_SCRIPT_ANCHOR_TARGET_MAX];
    char rel[PBROWSER_SCRIPT_ANCHOR_REL_MAX];
    int x;
    int y;

    if (wp != VK_RETURN || !g_sequential_focus_valid ||
            g_sequential_focus_kind != PCORE_FOCUS_TARGET_LINK) {
        return 0;
    }
    if (!pcore_sequential_focus_current(&target)) {
        return 1;
    }
    x = target.x + target.width / 2;
    y = target.y + target.height / 2;
    if (msg == WM_KEYDOWN || msg == WM_SYSKEYDOWN) {
        if (!pcore_browser_script_dispatch_key_at(x, y, "keydown",
                wp, lp, system_key, 0) || (lp & 0x40000000L) != 0) {
            return 1;
        }
        href[0] = '\0';
        link_target[0] = '\0';
        rel[0] = '\0';
        if (PCore_LinkAtEx(g_render_doc, x, y, href, sizeof(href),
                link_target, sizeof(link_target), rel, sizeof(rel)) != 0) {
            return 1;
        }
        if (pcore_native_script_active()) {
            (void) pcore_browser_script_dispatch_anchor_click_at(
                    x, y, href, link_target, rel);
        } else {
            navigate_to(hwnd, href);
        }
        return 1;
    }
    if (msg == WM_KEYUP || msg == WM_SYSKEYUP) {
        (void) pcore_browser_script_dispatch_key_at(x, y, "keyup",
                wp, lp, system_key, 0);
        return 1;
    }
    return 0;
}

static int pcore_form_toggle_activate(int x, int y,
        int product_toggle_started, int *dirty_x, int *dirty_y,
        int *dirty_w, int *dirty_h)
{
    unsigned int index;
    int kind;
    int before_selected;
    int disabled;
    int after_selected;
    int consumed;

    index = 0;
    kind = 0;
    before_selected = 0;
    disabled = 0;
    if (!pcore_form_toggle_control_at(x, y, &index, &kind,
            &before_selected, &disabled)) {
        index = 0;
        kind = 0;
    }
    consumed = PCore_FormActivateAt(g_render_doc, x, y,
            dirty_x, dirty_y, dirty_w, dirty_h);
    if (!consumed || kind == 0 || disabled) {
        if (product_toggle_started) {
            (void) pcore_browser_script_dispatch_native_toggle_phase(
                    index, kind, x, y,
                    PBROWSER_SCRIPT_NATIVE_TOGGLE_CANCEL,
                    disabled, before_selected, before_selected, NULL);
        }
        return consumed;
    }
    after_selected = before_selected;
    if (PCore_FormControlInfo(g_render_doc, index, NULL, NULL, NULL, NULL,
            NULL, &after_selected, NULL) != 0 ||
            after_selected == before_selected) {
        if (product_toggle_started) {
            (void) pcore_browser_script_dispatch_native_toggle_phase(
                    index, kind, x, y,
                    PBROWSER_SCRIPT_NATIVE_TOGGLE_COMMIT,
                    disabled, before_selected, before_selected, NULL);
        }
        return consumed;
    }
    if (product_toggle_started) {
        (void) pcore_browser_script_dispatch_native_toggle_phase(
                index, kind, x, y,
                PBROWSER_SCRIPT_NATIVE_TOGGLE_COMMIT,
                disabled, before_selected, after_selected, NULL);
    } else {
        /* Checkbox/radio input/change are non-cancelable and follow the
         * committed core state. Adapter failures are fail-open: they must
         * not roll back the user's selection or suppress repaint. */
        (void) pcore_browser_script_dispatch_toggle_input_at(x, y);
        (void) pcore_browser_script_dispatch_select_change_at(x, y);
    }
    return consumed;
}

static int pcore_handle_form_toggle(HWND hwnd, int x, int y,
        int product_toggle_started)
{
    unsigned int index;
    int kind;
    int disabled;
    int dirty_x;
    int dirty_y;
    int dirty_w;
    int dirty_h;

    index = 0;
    kind = 0;
    disabled = 0;
    if (!pcore_form_toggle_control_at(x, y, &index, &kind,
            NULL, &disabled)) {
        return 0;
    }
    if (disabled) {
        pcore_toggle_focus_clear();
    } else {
        pcore_toggle_focus_set(index, kind);
    }
    if (!pcore_form_toggle_activate(x, y, product_toggle_started,
            &dirty_x, &dirty_y, &dirty_w, &dirty_h)) {
        return 0;
    }
    pcore_invalidate_form_dirty(hwnd, dirty_x, dirty_y,
            dirty_w, dirty_h);
    pcore_request_interaction_restyle(hwnd);
    return 1;
}

/* A label activation is a trusted activation of its associated toggle. Keep
 * the target click and the state commit in the browser-owned transaction when
 * scripting is active; the host supplies only the hit-tested control and the
 * existing Core mutation/repaint path. Without scripting, preserve the
 * direct click plus Core fallback used by the legacy host path. */
static int pcore_activate_form_toggle(HWND hwnd, int x, int y)
{
    unsigned int index;
    int kind;
    int selected_before;
    int disabled;
    int default_allowed;
    int product_toggle_started;
    int phase_result;

    index = 0;
    kind = 0;
    selected_before = 0;
    disabled = 0;
    if (!pcore_form_toggle_control_at(x, y, &index, &kind,
            &selected_before, &disabled)) {
        return 1;
    }
    if (disabled) {
        /* The label itself has already received its click. A disabled target
         * must not receive a synthetic target click or mutate Core state. */
        pcore_toggle_focus_clear();
        return 1;
    }
    product_toggle_started = 0;
    if (pcore_native_script_active()) {
        default_allowed = 1;
        phase_result = pcore_browser_script_dispatch_native_toggle_phase(
                index, kind, x, y,
                PBROWSER_SCRIPT_NATIVE_TOGGLE_CLICK,
                0, selected_before, selected_before, &default_allowed);
        if (phase_result < 0 ||
                (phase_result > 0 && !default_allowed)) {
            return 1;
        }
        if (phase_result > 0) {
            product_toggle_started = 1;
        }
    }
    if (!product_toggle_started &&
            !pcore_browser_script_dispatch_click_at(x, y)) {
        return 1;
    }
    (void) pcore_handle_form_toggle(hwnd, x, y,
            product_toggle_started);
    return 1;
}

/* Resolve the label target's effective disabled state before synthesising a
 * target click.  Label activation must fail closed for every labelable
 * control, not only the controls that have a dedicated native transaction.
 */
static int pcore_label_target_disabled(int kind, int x, int y)
{
    unsigned int index;
    int left;
    int top;
    int width;
    int height;
    int current_kind;
    int disabled;

    if (g_render_doc == NULL) {
        return 1;
    }
    index = 0;
    while (PCore_FormControlInfo(g_render_doc, index, &left, &top,
            &width, &height, &current_kind, NULL, &disabled) == 0) {
        if (current_kind == kind && width > 0 && height > 0 &&
                x >= left && x < left + width &&
                y >= top && y < top + height) {
            return disabled ? 1 : 0;
        }
        index++;
    }
    return 1;
}

/* Complete the trusted part of label activation for labelable native
 * controls that do not have a specialised CLICK/COMMIT transaction.  The
 * browser layer owns the cancelable target click; the host performs only the
 * native focus or system-picker default action after that click is accepted.
 * The legacy/no-script path keeps its historical focus/picker behavior. */
static int pcore_activate_label_native_control(HWND hwnd, int kind,
        int x, int y)
{
    if ((kind < 3 || kind > 6) && kind != 10) {
        return 0;
    }
    if (pcore_label_target_disabled(kind, x, y)) {
        return 1;
    }
    if (pcore_native_script_active() &&
            !pcore_browser_script_dispatch_click_at(x, y)) {
        return 1;
    }
    if (kind == 10) {
        (void) pcore_handle_file_input(hwnd, x, y);
    } else {
        (void) pcore_focus_native_form_control(kind, x, y);
    }
    return 1;
}

static int pcore_focus_native_form_control(int kind, int x, int y)
{
    PCoreTextInputInfo text_info;
    PCoreSelectInfo select_info;
    unsigned int i;

    if (kind >= 3 && kind <= 5) {
        for (i = 0; i < g_native_edit_count; i++) {
            if (g_native_edits[i].hwnd != NULL &&
                    PCore_TextInputInfo(g_render_doc,
                            g_native_edits[i].text_index,
                            &text_info, NULL, 0) == 0 &&
                    x >= text_info.x &&
                    x < text_info.x + text_info.width &&
                    y >= text_info.y &&
                    y < text_info.y + text_info.height) {
                if (IsWindowEnabled(g_native_edits[i].hwnd)) {
                    SetFocus(g_native_edits[i].hwnd);
                }
                return 1;
            }
        }
    } else if (kind == 6) {
        for (i = 0; i < g_native_select_count; i++) {
            if (g_native_selects[i].hwnd != NULL &&
                    PCore_SelectInfo(g_render_doc,
                            g_native_selects[i].select_index,
                            &select_info) == 0 &&
                    x >= select_info.x &&
                    x < select_info.x + select_info.width &&
                    y >= select_info.y &&
                    y < select_info.y + select_info.height) {
                if (IsWindowEnabled(g_native_selects[i].hwnd)) {
                    SetFocus(g_native_selects[i].hwnd);
                }
                return 1;
            }
        }
    }
    return 0;
}

static void pcore_handle_invalid_form(HWND hwnd,
        const PCoreFormValidationInfo *validation)
{
    RECT client;
    RECT dirty;
    int client_width;
    int client_height;
    int target_scroll_x;
    int target_scroll;
    int left;
    int right;
    int top;
    int bottom;

    if (validation == NULL || validation->valid ||
            validation->invalid_count <= 0) {
        return;
    }
    if (!pcore_browser_script_dispatch_invalid_event_at(
            validation->first_x + validation->first_width / 2,
            validation->first_y + validation->first_height / 2)) {
        return;
    }
    GetClientRect(hwnd, &client);
    client_width = client.right - client.left;
    client_height = client.bottom - client.top;
    left = validation->first_x;
    right = left + validation->first_width;
    target_scroll_x = g_scroll_x;
    if (left < g_scroll_x + 8) {
        target_scroll_x = left - 8;
    } else if (right > g_scroll_x + client_width - 8) {
        target_scroll_x = right - client_width + 8;
    }
    top = validation->first_y;
    bottom = top + validation->first_height;
    target_scroll = g_scroll_y;
    if (top < g_scroll_y + 8) {
        target_scroll = top - 8;
    } else if (bottom > g_scroll_y + client_height - 8) {
        target_scroll = bottom - client_height + 8;
    }
    pcore_scroll_to_xy(hwnd, target_scroll_x, target_scroll);
    pcore_focus_native_form_control(validation->first_control_kind,
            validation->first_x, validation->first_y);
    dirty.left = validation->first_x - g_scroll_x;
    dirty.top = validation->first_y - g_scroll_y;
    dirty.right = validation->first_x - g_scroll_x + validation->first_width;
    dirty.bottom = dirty.top + validation->first_height;
    InvalidateRect(hwnd, &dirty, FALSE);
    MessageBeep(MB_ICONEXCLAMATION);
}

typedef int (*pcore_file_picker_callback)(HWND owner,
        WCHAR *file_path, int file_path_capacity,
        WCHAR *file_title, int file_title_capacity, void *pw);

static int pcore_file_picker_system(HWND owner, WCHAR *file_path,
        int file_path_capacity, WCHAR *file_title, int file_title_capacity,
        void *pw)
{
    OPENFILENAMEEX picker;

    (void) pw;
    if (file_path == NULL || file_path_capacity <= 0 ||
            file_title == NULL || file_title_capacity <= 0) {
        return -1;
    }
    memset(&picker, 0, sizeof(picker));
    picker.lStructSize = sizeof(picker);
    picker.hwndOwner = owner;
    picker.lpstrFilter = L"All files (*.*)\0*.*\0\0";
    picker.lpstrFile = file_path;
    picker.nMaxFile = (DWORD) file_path_capacity;
    picker.lpstrFileTitle = file_title;
    picker.nMaxFileTitle = (DWORD) file_title_capacity;
    picker.lpstrTitle = L"Choose a file";
    picker.Flags = OFN_FILEMUSTEXIST | OFN_PATHMUSTEXIST;
    picker.ExFlags = OFN_EXFLAG_NOFILECREATE;
    /* WM6's GetOpenFileNameEx has no separate cancel/error result. A false
     * return is therefore the user-cancel path; storage/conversion failures
     * are reported after a successful selection. */
    return GetOpenFileNameEx(&picker) ? 1 : 0;
}

static int pcore_file_picker_run(HWND owner, WCHAR *file_path,
        int file_path_capacity, WCHAR *file_title, int file_title_capacity,
        pcore_file_picker_callback callback, void *pw)
{
    int result;

    if (file_path == NULL || file_path_capacity <= 0 ||
            file_title == NULL || file_title_capacity <= 0) {
        return -1;
    }
    if (callback == NULL) {
        callback = pcore_file_picker_system;
    }
    result = callback(owner, file_path, file_path_capacity,
            file_title, file_title_capacity, pw);
    if (result < 0) {
        return -1;
    }
    if (result == 0) {
        return 0;
    }
    file_path[file_path_capacity - 1] = L'\0';
    file_title[file_title_capacity - 1] = L'\0';
    return 1;
}

static int pcore_file_input_commit_selection(HANDLE document,
        unsigned int file_index, const WCHAR *file_path,
        const WCHAR *file_title, PCoreFileInputInfo *out_info)
{
    const WCHAR *display_title;
    char *path_utf8;
    char *title_utf8;

    if (document == NULL || file_path == NULL || file_path[0] == L'\0' ||
            out_info == NULL || PCore_FileInputInfo(document, file_index,
            out_info, NULL, 0, NULL, 0) != 0) {
        return -1;
    }
    display_title = (file_title != NULL && file_title[0] != L'\0') ?
            file_title : file_path;
    path_utf8 = wide_to_utf8_alloc(file_path);
    title_utf8 = wide_to_utf8_alloc(display_title);
    if (path_utf8 == NULL || title_utf8 == NULL ||
            PCore_FileInputSetPath(document, file_index,
                    title_utf8, path_utf8) != 0) {
        free(path_utf8);
        free(title_utf8);
        return -1;
    }
    free(path_utf8);
    free(title_utf8);
    return 0;
}

static int pcore_handle_file_input_index_with_picker(HWND hwnd,
        unsigned int file_index, pcore_file_picker_callback callback,
        void *pw)
{
    PCoreFileInputInfo info;
    WCHAR file_path[MAX_PATH];
    WCHAR file_title[MAX_PATH];
    int picker_result;
    int transaction_started;
    int transaction_result;
    int center_x;
    int center_y;

    if (g_render_doc == NULL || PCore_FileInputInfo(g_render_doc,
            file_index, &info, NULL, 0, NULL, 0) != 0) {
        return 0;
    }
    if (info.disabled) {
        return 1;
    }
    center_x = info.x + info.width / 2;
    center_y = info.y + info.height / 2;
    transaction_started = pcore_browser_script_dispatch_native_file_phase(
            file_index, center_x, center_y,
            PBROWSER_SCRIPT_NATIVE_FILE_SELECTION_BEGIN);
    if (transaction_started < 0) {
        show_error(L"File selection failed",
                "Could not start the browser-owned file selection transaction");
        return 1;
    }
    memset(file_path, 0, sizeof(file_path));
    memset(file_title, 0, sizeof(file_title));
    picker_result = pcore_file_picker_run(hwnd, file_path, MAX_PATH,
            file_title, MAX_PATH, callback, pw);
    if (picker_result < 0) {
        if (transaction_started > 0) {
            (void) pcore_browser_script_dispatch_native_file_phase(
                    file_index, center_x, center_y,
                    PBROWSER_SCRIPT_NATIVE_FILE_SELECTION_CANCEL);
        }
        show_error(L"File picker failed",
                "The system file picker could not be opened");
        return 1;
    }
    if (picker_result == 0) {
        if (transaction_started > 0) {
            (void) pcore_browser_script_dispatch_native_file_phase(
                    file_index, center_x, center_y,
                    PBROWSER_SCRIPT_NATIVE_FILE_SELECTION_CANCEL);
        }
        return 1;
    }
    if (pcore_file_input_commit_selection(g_render_doc, file_index,
            file_path, file_title, &info) != 0) {
        if (transaction_started > 0) {
            (void) pcore_browser_script_dispatch_native_file_phase(
                    file_index, center_x, center_y,
                    PBROWSER_SCRIPT_NATIVE_FILE_SELECTION_CANCEL);
        }
        show_error(L"File selection failed",
                "Could not store the selected file in the form");
        return 1;
    }
    if (transaction_started > 0) {
        transaction_result = pcore_browser_script_dispatch_native_file_phase(
                file_index, center_x, center_y,
                PBROWSER_SCRIPT_NATIVE_FILE_SELECTION_COMMIT);
        if (transaction_result < 0) {
            show_error(L"File event dispatch failed",
                    "The file was stored, but input/change notification failed");
        }
    } else {
        (void) pcore_browser_script_dispatch_file_event_at(
                center_x, center_y, "input");
        (void) pcore_browser_script_dispatch_file_event_at(
                center_x, center_y, "change");
    }
    if (hwnd != NULL) {
        /* DOM textContent setters only mutate the DOM.  The file listeners
         * update the visible event/value nodes, so re-style and lay out the
         * document before repainting instead of invalidating only the native
         * file-control rectangle. */
        if (pcore_restyle_form_state(hwnd, 1) != 0) {
            show_error(L"File selection redraw failed",
                    "The selected file was stored, but the page could not be redrawn");
            InvalidateRect(hwnd, NULL, TRUE);
        }
    }
    return 1;
}

static int pcore_handle_file_input_with_picker(HWND hwnd, int x, int y,
        pcore_file_picker_callback callback, void *pw)
{
    unsigned int file_index;
    int disabled;

    file_index = 0;
    disabled = 0;
    if (!PCore_FileInputAt(g_render_doc, x, y,
            &file_index, &disabled)) {
        return 0;
    }
    if (disabled) {
        return 1;
    }
    return pcore_handle_file_input_index_with_picker(hwnd, file_index,
            callback, pw);
}

static int pcore_handle_file_input(HWND hwnd, int x, int y)
{
    return pcore_handle_file_input_with_picker(hwnd, x, y, NULL, NULL);
}

/* HTMLElement.click() runs inside a synchronous script callback.  Queue the
 * host-owned picker until that callback has returned so the system dialog
 * cannot re-enter script evaluation or core event propagation. */
static int pcore_queue_file_input_picker(
        pcore_browser_script_bridge *bridge, int x, int y)
{
    unsigned int file_index;
    int disabled;
    int accepted;
    int product_result;

    if (bridge == NULL || bridge->document == NULL ||
            bridge->document != g_render_doc || bridge->hwnd == NULL) {
        return 0;
    }
    file_index = 0;
    disabled = 0;
    if (!PCore_FileInputAt(bridge->document, x, y,
            &file_index, &disabled) || disabled) {
        return 0;
    }
    /* Keep this host guard for a non-product/stale bridge, but let the
     * browser session be the source of truth when it is active. */
    if (g_file_picker_active || g_file_picker_pending) {
        return 0;
    }
    accepted = 1;
    product_result = pcore_browser_script_dispatch_native_file_picker_phase(
            bridge, file_index, x, y,
            PBROWSER_SCRIPT_NATIVE_FILE_PICKER_REQUEST, &accepted);
    if (product_result < 0) {
        return -1;
    }
    if (product_result > 0 && !accepted) {
        /* One script turn may call click() repeatedly. The product arbiter
         * coalesces later requests into the first host picker. */
        return 0;
    }
    g_file_picker_pending = 1;
    g_file_picker_pending_document = bridge->document;
    g_file_picker_pending_hwnd = bridge->hwnd;
    g_file_picker_pending_index = file_index;
    if (!PostMessage(bridge->hwnd, WM_PCORE_FILE_PICKER, 0, 0)) {
        pcore_file_picker_clear_pending();
        if (product_result > 0) {
            accepted = 0;
            (void) pcore_browser_script_dispatch_native_file_picker_phase(
                    bridge, file_index, x, y,
                    PBROWSER_SCRIPT_NATIVE_FILE_PICKER_CANCEL,
                    &accepted);
        }
        return -1;
    }
    return 0;
}

static int pcore_process_pending_file_picker(HWND hwnd,
        pcore_file_picker_callback callback, void *pw)
{
    unsigned int file_index;
    int center_x;
    int center_y;
    int accepted;
    int product_result;
    int result;
    PCoreFileInputInfo info;
    pcore_browser_script_bridge *bridge;

    if (!g_file_picker_pending) {
        return 0;
    }
    bridge = g_browser_script_session.bridge;
    if (g_file_picker_pending_hwnd != hwnd ||
            g_file_picker_pending_document != g_render_doc) {
        /* A queued request cannot cross a window/document replacement. */
        accepted = 0;
        (void) pcore_browser_script_dispatch_native_file_picker_phase(
                bridge, g_file_picker_pending_index, 0, 0,
                PBROWSER_SCRIPT_NATIVE_FILE_PICKER_CANCEL, &accepted);
        pcore_file_picker_clear_pending();
        return 0;
    }
    file_index = g_file_picker_pending_index;
    pcore_file_picker_clear_pending();
    if (g_file_picker_active) {
        return 0;
    }
    memset(&info, 0, sizeof(info));
    if (PCore_FileInputInfo(g_render_doc, file_index, &info,
            NULL, 0, NULL, 0) != 0) {
        accepted = 0;
        (void) pcore_browser_script_dispatch_native_file_picker_phase(
                bridge, file_index, 0, 0,
                PBROWSER_SCRIPT_NATIVE_FILE_PICKER_CANCEL, &accepted);
        return 0;
    }
    center_x = info.x + info.width / 2;
    center_y = info.y + info.height / 2;
    accepted = 0;
    product_result = pcore_browser_script_dispatch_native_file_picker_phase(
            bridge, file_index, center_x, center_y,
            PBROWSER_SCRIPT_NATIVE_FILE_PICKER_OPEN, &accepted);
    if (product_result < 0 || (product_result > 0 && !accepted)) {
        accepted = 0;
        (void) pcore_browser_script_dispatch_native_file_picker_phase(
                bridge, file_index, center_x, center_y,
                PBROWSER_SCRIPT_NATIVE_FILE_PICKER_CANCEL, &accepted);
        return 0;
    }
    g_file_picker_active = 1;
    result = pcore_handle_file_input_index_with_picker(hwnd, file_index,
            callback, pw);
    g_file_picker_active = 0;
    if (product_result > 0) {
        accepted = 0;
        if (pcore_browser_script_dispatch_native_file_picker_phase(
                bridge, file_index, center_x, center_y,
                PBROWSER_SCRIPT_NATIVE_FILE_PICKER_CLOSE,
                &accepted) < 0) {
            show_error(L"File picker failed",
                    "Could not close the browser-owned picker request");
        }
    }
    return result;
}

static int pcore_handle_label(HWND hwnd, int x, int y)
{
    unsigned int button_index;
    int target_x;
    int target_y;
    int kind;
    int button_kind;
    int button_disabled;

    if (!PCore_LabelTargetAt(g_render_doc, x, y,
            &target_x, &target_y, &kind)) {
        return 0;
    }
    if (PCore_InteractionSetAt(g_render_doc, target_x, target_y,
            PCORE_INTERACTION_FOCUS) > 0) {
        pcore_request_interaction_restyle(hwnd);
    }
    if (kind == 1 || kind == 2) {
        pcore_button_focus_clear();
        (void) pcore_toggle_focus_track_at(target_x, target_y);
    } else {
        pcore_toggle_focus_clear();
        pcore_button_focus_clear();
    }
    if (kind >= 7 && kind <= 9) {
        button_index = 0;
        button_kind = 0;
        button_disabled = 0;
        if (pcore_form_button_control_at(target_x, target_y,
                &button_index, &button_kind, &button_disabled) &&
                button_kind == kind && !button_disabled) {
            (void) pcore_button_focus_track_at(target_x, target_y);
            (void) pcore_activate_form_button(hwnd, button_index,
                    button_kind, target_x, target_y);
        } else {
            /* A disabled or stale label target must not synthesize a button
             * click or fall through to the window-close fallback. */
            pcore_button_focus_clear();
        }
    } else if (kind == 10) {
        pcore_handle_file_input(hwnd, target_x, target_y);
    } else if (kind == 1 || kind == 2) {
        /* A label activation first dispatches the label click in the
         * window procedure, then synthesizes the target control click. The
         * target click may cancel activation; state/input/change remain
         * owned by the existing form-toggle path. Disabled controls do not
         * receive a synthetic click. */
        (void) pcore_activate_form_toggle(hwnd, target_x, target_y);
    } else {
        (void) pcore_activate_label_native_control(hwnd, kind,
                target_x, target_y);
    }
    return 1;
}

/* Keyboard activation uses the same browser-owned button transaction as a
 * trusted mouse activation. The host owns only the focused Core control and
 * the WM key timing; click/form/default semantics stay in the browser DLL or
 * Core fallback. */
static int pcore_activate_form_button(HWND hwnd, unsigned int index,
        int kind, int x, int y)
{
    PCoreFormValidationInfo validation;
    int left;
    int top;
    int width;
    int height;
    int current_kind;
    int disabled;
    int default_allowed;
    int validation_valid;
    int product_button_started;
    int phase_result;

    if (g_render_doc == NULL ||
            PCore_FormControlInfo(g_render_doc, index, &left, &top,
            &width, &height, &current_kind, NULL, &disabled) != 0 ||
            current_kind != kind || kind < 7 || kind > 9 || disabled ||
            width <= 0 || height <= 0) {
        return 1;
    }
    x = left + width / 2;
    y = top + height / 2;
    product_button_started = 0;
    if (pcore_native_script_active()) {
        default_allowed = 1;
        phase_result = pcore_browser_script_dispatch_native_button_phase(
                index, kind, x, y,
                PBROWSER_SCRIPT_NATIVE_BUTTON_CLICK, 0, 0,
                &default_allowed);
        if (phase_result < 0 ||
                (phase_result > 0 && !default_allowed)) {
            return 1;
        }
        if (phase_result > 0) {
            product_button_started = 1;
        }
    }
    if (!product_button_started) {
        default_allowed = pcore_browser_script_dispatch_click_at(x, y);
        if (!default_allowed) {
            return 1;
        }
    }
    if (product_button_started) {
        validation_valid = 0;
        if (kind == 7 && PCore_FormValidationAt(g_render_doc, x, y,
                &validation) && validation.valid) {
            validation_valid = 1;
        }
        default_allowed = 1;
        phase_result = pcore_browser_script_dispatch_native_button_phase(
                index, kind, x, y,
                PBROWSER_SCRIPT_NATIVE_BUTTON_COMMIT, 0,
                validation_valid, &default_allowed);
        if (phase_result <= 0 || !default_allowed) {
            return 1;
        }
        (void) pcore_handle_form_button_default(hwnd, x, y, kind);
        return 1;
    }
    (void) pcore_handle_form_button(hwnd, x, y);
    return 1;
}

static int pcore_handle_button_keyboard(HWND hwnd, UINT msg,
        WPARAM wp, LPARAM lp, int system_key)
{
    unsigned int index;
    int kind;
    int disabled;
    int x;
    int y;
    int keydown;
    int keyup;

    if (wp != VK_SPACE && wp != VK_RETURN) {
        return 0;
    }
    index = 0;
    kind = 0;
    disabled = 0;
    if (!pcore_button_focus_current(&x, &y, &index, &kind, &disabled)) {
        return 0;
    }
    if (disabled) {
        pcore_button_focus_clear();
        return 0;
    }
    keydown = (msg == WM_KEYDOWN || msg == WM_SYSKEYDOWN);
    keyup = (msg == WM_KEYUP || msg == WM_SYSKEYUP);
    if (keydown) {
        if (!pcore_browser_script_dispatch_key_at(x, y, "keydown",
                wp, lp, system_key, 0)) {
            return 1;
        }
        /* Keep dispatching repeat keydown events to script, but never issue
         * more than one trusted activation for a held physical key. */
        if ((lp & 0x40000000L) != 0) {
            return 1;
        }
        if (wp == VK_SPACE) {
            g_button_space_pending = 1;
            return 1;
        }
        (void) pcore_activate_form_button(hwnd, index, kind, x, y);
        return 1;
    }
    if (keyup) {
        (void) pcore_browser_script_dispatch_key_at(x, y, "keyup",
                wp, lp, system_key, 0);
        if (wp == VK_SPACE && g_button_space_pending) {
            g_button_space_pending = 0;
            (void) pcore_activate_form_button(hwnd, index, kind, x, y);
        }
        return 1;
    }
    return 0;
}

static int pcore_handle_toggle_keyboard(HWND hwnd, UINT msg,
        WPARAM wp, LPARAM lp, int system_key)
{
    unsigned int index;
    int kind;
    int selected_before;
    int disabled;
    int x;
    int y;
    int keydown;
    int keyup;
    int default_allowed;
    int product_toggle_started;
    int phase_result;

    if (wp != VK_SPACE && wp != VK_RETURN) {
        return 0;
    }
    if (!pcore_toggle_focus_current(&x, &y)) {
        return 0;
    }
    keydown = (msg == WM_KEYDOWN || msg == WM_SYSKEYDOWN);
    keyup = (msg == WM_KEYUP || msg == WM_SYSKEYUP);
    if (keydown) {
        if (!pcore_browser_script_dispatch_key_at(x, y, "keydown",
                wp, lp, system_key, 0)) {
            return 1;
        }
        /* A held key must not toggle the control repeatedly. The key event
         * itself still reaches the script bridge for every WM_KEYDOWN. */
        if ((lp & 0x40000000L) != 0) {
            return 1;
        }
        product_toggle_started = 0;
        index = 0;
        kind = 0;
        selected_before = 0;
        disabled = 0;
        if (pcore_native_script_active() &&
                pcore_form_toggle_control_at(x, y, &index, &kind,
                &selected_before, &disabled)) {
            default_allowed = 1;
            phase_result = pcore_browser_script_dispatch_native_toggle_phase(
                    index, kind, x, y,
                    PBROWSER_SCRIPT_NATIVE_TOGGLE_CLICK,
                    disabled, selected_before, selected_before,
                    &default_allowed);
            if (phase_result < 0 ||
                    (phase_result > 0 && !default_allowed)) {
                return 1;
            }
            if (phase_result > 0) {
                product_toggle_started = 1;
            }
        }
        if (!product_toggle_started &&
                !pcore_browser_script_dispatch_click_at(x, y)) {
            return 1;
        }
        (void) pcore_handle_form_toggle(hwnd, x, y,
                product_toggle_started);
        return 1;
    }
    if (keyup) {
        (void) pcore_browser_script_dispatch_key_at(x, y, "keyup",
                wp, lp, system_key, 0);
        return 1;
    }
    return 0;
}

static void pcore_native_toggle_key_probe_run(HWND parent)
{
    int center_x[5];
    int center_y[5];
    int kind[5];
    int disabled[5];
    int left;
    int top;
    int width;
    int height;
    unsigned int index;
    int i;
    int ok;

    if (!g_native_toggle_key_probe || parent == NULL ||
            g_render_doc == NULL) {
        return;
    }
    memset(center_x, 0, sizeof(center_x));
    memset(center_y, 0, sizeof(center_y));
    memset(kind, 0, sizeof(kind));
    memset(disabled, 0, sizeof(disabled));
    ok = 1;
    for (i = 0; i < 5; i++) {
        index = (unsigned int) i;
        if (PCore_FormControlInfo(g_render_doc, index, &left, &top,
                &width, &height, &kind[i], NULL, &disabled[i]) != 0 ||
                width <= 0 || height <= 0) {
            ok = 0;
            continue;
        }
        center_x[i] = left + width / 2;
        center_y[i] = top + height / 2;
    }
    if (kind[0] != 1 || kind[1] != 1 || kind[2] != 2 ||
            kind[3] != 2 || kind[4] != 1 || disabled[0] ||
            disabled[1] || disabled[2] || disabled[3] || !disabled[4]) {
        ok = 0;
    }
    SetFocus(parent);
    if (ok && (PCore_InteractionSetAt(g_render_doc,
            center_x[0], center_y[0], PCORE_INTERACTION_FOCUS) < 0 ||
            !pcore_toggle_focus_track_at(center_x[0], center_y[0]))) {
        ok = 0;
    }
    if (ok) {
        (void) SendMessage(parent, WM_KEYDOWN, VK_SPACE, 0);
        (void) SendMessage(parent, WM_KEYDOWN, VK_SPACE, 0x40000000L);
        (void) SendMessage(parent, WM_KEYUP, VK_SPACE, 0);
    }
    if (ok && (PCore_InteractionSetAt(g_render_doc,
            center_x[1], center_y[1], PCORE_INTERACTION_FOCUS) < 0 ||
            !pcore_toggle_focus_track_at(center_x[1], center_y[1]))) {
        ok = 0;
    }
    if (ok) {
        (void) SendMessage(parent, WM_KEYDOWN, VK_RETURN, 0);
        (void) SendMessage(parent, WM_KEYUP, VK_RETURN, 0);
    }
    if (ok && (PCore_InteractionSetAt(g_render_doc,
            center_x[3], center_y[3], PCORE_INTERACTION_FOCUS) < 0 ||
            !pcore_toggle_focus_track_at(center_x[3], center_y[3]))) {
        ok = 0;
    }
    if (ok) {
        (void) SendMessage(parent, WM_KEYDOWN, VK_SPACE, 0);
        (void) SendMessage(parent, WM_KEYUP, VK_SPACE, 0);
    }
    if (ok && PCore_InteractionSetAt(g_render_doc,
            center_x[4], center_y[4], PCORE_INTERACTION_FOCUS) < 0) {
        ok = 0;
    }
    if (ok && pcore_toggle_focus_track_at(center_x[4], center_y[4])) {
        ok = 0;
    }
    if (ok) {
        (void) SendMessage(parent, WM_KEYDOWN, VK_SPACE, 0);
        (void) SendMessage(parent, WM_KEYUP, VK_SPACE, 0);
    }
    g_native_toggle_key_probe_ok = ok;
    PostMessage(parent, WM_CLOSE, 0, 0);
}

