        open_details_rc = PCore_NodeBox(open_doc, "details", &open_x,
                &open_y, &open_w, &open_h);
        open_summary_rc = PCore_NodeBox(open_doc, "summary", &open_x,
                &open_y, &open_w, &open_h);
        open_p_rc = PCore_NodeBox(open_doc, "p", &open_x, &open_y, &open_w,
                &open_h);
