/* TEST 1102 - bounded custom tabindex ordering and generic targets. */
static BOOL test1102_browser_tabindex_order_contract(void)
{
    static const char HTML[] =
        "<!doctype html><html><head></head><body><div id='root'>"
        "<a id='natural' href='#natural'>Natural</a>"
        "<input id='high' type='text' tabindex='9' value='high'>"
        "<button id='low' type='button' tabindex='2'>Low</button>"
        "<a id='tie' href='#tie' tabindex=' 2 '>Tie</a>"
        "<div id='zero' tabindex='0'>Zero</div>"
        "<div id='generic' tabindex='1'>Generic</div>"
        "<input id='negative' type='text' tabindex='-1' value='negative'>"
        "<input id='malformed' type='text' tabindex='oops' value='malformed'>"
        "<button id='disabled' type='button' tabindex='1' disabled>Disabled"
        "</button>"
        "<a id='empty' href='' tabindex='3'>Custom empty</a>"
        "<div id='result'>idle</div></div></body></html>";
    static const char CSS[] =
        "body{font:14px sans-serif;margin:8px}"
        "#natural,#high,#low,#tie,#zero,#generic,#negative,#malformed,"
        "#disabled,#empty{display:block;width:180px;height:24px;margin:3px}"
        "#result{display:none}";
    static const char *TARGET_IDS[] = {
        "generic", "low", "tie", "empty", "high", "natural", "zero",
        "malformed"
    };
    static const int TARGET_KINDS[] = {
        PCORE_FOCUS_TARGET_GENERIC, 9, PCORE_FOCUS_TARGET_LINK,
        PCORE_FOCUS_TARGET_GENERIC, 3, PCORE_FOCUS_TARGET_LINK,
        PCORE_FOCUS_TARGET_GENERIC, 3
    };
    HANDLE document;
    HANDLE sheet;
    PCoreFocusTargetInfo info;
    int expected_x;
    int expected_y;
    int expected_w;
    int expected_h;
    int generic_x;
    int generic_y;
    unsigned int i;
    char error[512];
    int ok;

    document = NULL;
    sheet = NULL;
    generic_x = 0;
    generic_y = 0;
    memset(error, 0, sizeof(error));
    ok = 1;
    document = PCore_ParseHTML(HTML, sizeof(HTML) - 1);
    if (document == NULL) {
        ok = 0;
        _snprintf(error, sizeof(error) - 1, "parse failed");
    }
    if (ok) {
        sheet = PCore_ParseCSS(CSS, sizeof(CSS) - 1,
                "http://positron.local/tabindex-order.css");
        if (sheet == NULL || PCore_StyleDocument(document, sheet) != 0 ||
                PCore_LayoutDocument(document, 320, 260) != 0) {
            ok = 0;
            _snprintf(error, sizeof(error) - 1,
                    "style/layout failed");
        }
    }
    for (i = 0; ok && i < 8U; i++) {
        memset(&info, 0, sizeof(info));
        expected_x = 0;
        expected_y = 0;
        expected_w = 0;
        expected_h = 0;
        if (PCore_FocusTargetInfo(document, i, &info) != 0 ||
                info.kind != TARGET_KINDS[i] || info.width <= 0 ||
                info.height <= 0 ||
                PCore_FragmentInfoById(document, TARGET_IDS[i],
                &expected_x, &expected_y, &expected_w, &expected_h) != 0 ||
                info.x != expected_x || info.y != expected_y ||
                info.width != expected_w || info.height != expected_h) {
            ok = 0;
            _snprintf(error, sizeof(error) - 1,
                    "order[%u] id=%s kind=%d geom=%d,%d,%d,%d",
                    i, TARGET_IDS[i], info.kind, info.x, info.y,
                    info.width, info.height);
            error[sizeof(error) - 1] = '\0';
            break;
        }
        if (i == 0U) {
            generic_x = info.x + info.width / 2;
            generic_y = info.y + info.height / 2;
        }
    }
    if (ok && PCore_FocusTargetInfo(document, 8U, &info) == 0) {
        ok = 0;
        _snprintf(error, sizeof(error) - 1,
                "excluded negative/disabled targets were returned");
        error[sizeof(error) - 1] = '\0';
    }
    if (ok && (PCore_InteractionSetAt(document, generic_x, generic_y,
            PCORE_INTERACTION_FOCUS) < 0 ||
            PCore_InteractionClear(document, PCORE_INTERACTION_FOCUS) < 0)) {
        ok = 0;
        _snprintf(error, sizeof(error) - 1,
                "generic tabindex interaction failed");
        error[sizeof(error) - 1] = '\0';
    }
    if (sheet != NULL) {
        PCore_FreeStylesheet(sheet);
    }
    if (document != NULL) {
        PCore_FreeDocument(document);
    }
    if (!ok) {
        show_error(L"TEST 1102 FAIL", error[0] != '\0' ? error :
                "tabindex ordering failed");
        return FALSE;
    }
    show_info(L"TEST 1102 OK",
            "Positive tabindex values sort before the stable zero/default"
            " DOM order, negative and disabled targets are excluded, and"
            " arbitrary laid-out elements with valid tabindex values can be"
            " focused through the Core interaction bridge.");
    return TRUE;
}

/* TEST 1103 - bounded dialog lifecycle and cancel/close events. */
static BOOL test1103_browser_dialog_lifecycle_contract(void)
{
    static const char HTML[] =
        "<!doctype html><html><body>"
        "<dialog id='dialog'>Dialog</dialog>"
        "<dialog id='other'>Other</dialog>"
        "<p id='result'>pending</p>"
        "<script>var d=document.getElementById('dialog');"
        "var o=document.getElementById('other');var result='';var events='';"
        "function mark(v){result+=v?'1':'0';}"
        "d.addEventListener('cancel',function(e){events+='cancel:';"
        "events+=e.defaultPrevented?'1;':'0;';});"
        "d.addEventListener('close',function(e){events+='close:';"
        "events+=e.defaultPrevented?'1;':'0;';});"
        "mark(!d.open&&d.returnValue==='');"
        "d.show();mark(d.open);"
        "try{d.show();mark(false);}catch(e){mark(e.name==='InvalidStateError');}"
        "d.close('accepted');mark(!d.open&&d.returnValue==='accepted');"
        "d.showModal();mark(d.open);"
        "d.addEventListener('cancel',function(e){e.preventDefault();"
        "events+='blocked;';},{once:true});"
        "d.requestClose('blocked');mark(d.open&&d.returnValue==='accepted');"
        "d.requestClose('dismissed');mark(!d.open&&d.returnValue==='dismissed');"
        "d.requestClose('ignored');mark(!d.open&&d.returnValue==='dismissed');"
        "d.showModal();try{o.showModal();mark(false);}catch(e){"
        "mark(e.name==='InvalidStateError');}d.close();mark(!d.open&&"
        "d.returnValue==='');o.showModal();mark(o.open);o.close('other');"
        "mark(!o.open&&o.returnValue==='other');"
        "document.getElementById('result').textContent=result+'|'+events;"
        "</script></body></html>";
    HANDLE document;
    char result[512];
    char error[384];
    int executed;
    int ignored;
    int bytes;
    int ok;

    document = NULL;
    memset(result, 0, sizeof(result));
    memset(error, 0, sizeof(error));
    executed = -1;
    ignored = -1;
    bytes = 0;
    ok = 1;
    pcore_browser_script_session_destroy();
    g_render_doc = NULL;
    g_render_sheet = NULL;
    document = PCore_ParseHTML(HTML, sizeof(HTML) - 1);
    if (document == NULL ||
            pcore_browser_execute_inline_scripts(document, 1, &executed,
            &ignored, error, sizeof(error)) != 0 || executed != 1 ||
            ignored != 0 || PCore_NodeTextContentById(document, "result",
            result, sizeof(result), &bytes) != 0 ||
            strcmp(result,
            "111111111111|close:0;cancel:0;blocked;cancel:0;close:0;"
            "close:0;") != 0) {
        ok = 0;
    }
    if (document != NULL) {
        PCore_FreeDocument(document);
    }
    g_render_doc = NULL;
    g_render_sheet = NULL;
    pcore_browser_script_session_destroy();
    if (!ok) {
        if (error[0] == '\0') {
            _snprintf(error, sizeof(error) - 1,
                    "result[%d]=%s executed=%d ignored=%d", bytes,
                    result, executed, ignored);
            error[sizeof(error) - 1] = '\0';
        }
        show_error(L"TEST 1103 FAIL", error);
        return FALSE;
    }
    show_info(L"TEST 1103 OK",
            "Browser dialog elements support bounded show/showModal/close"
            " and requestClose lifecycles, returnValue, modal exclusivity"
            " and cancelable cancel followed by non-cancelable close events.");
    return TRUE;
}

/* TEST 1104 - host-driven Escape requestClose bridge. */
static BOOL test1104_browser_dialog_escape_bridge_contract(void)
{
    static const char HTML[] =
        "<!doctype html><html><body>"
        "<dialog id='dialog'>Dialog</dialog>"
        "<p id='result'>pending</p>"
        "<script>var d=document.getElementById('dialog');"
        "window.events='';window.block=true;"
        "d.addEventListener('cancel',function(e){events+='cancel:';"
        "events+=e.defaultPrevented?'1;':'0;';"
        "if(window.block){e.preventDefault();}});"
        "d.addEventListener('close',function(e){events+='close:';"
        "events+=e.defaultPrevented?'1;':'0;';});"
        "d.showModal();</script></body></html>";
    HANDLE document;
    HANDLE runtime;
    pcore_browser_script_bridge *bridge;
    char result[512];
    char error[384];
    int executed;
    int ignored;
    int bytes;
    int handled;
    int closed;
    int rc;
    int ok;

    document = NULL;
    runtime = NULL;
    bridge = NULL;
    memset(result, 0, sizeof(result));
    memset(error, 0, sizeof(error));
    executed = -1;
    ignored = -1;
    bytes = 0;
    handled = 0;
    closed = 0;
    rc = PSCRIPT_OK;
    ok = 1;
    pcore_browser_script_session_destroy();
    g_render_doc = NULL;
    g_render_sheet = NULL;
    document = PCore_ParseHTML(HTML, sizeof(HTML) - 1);
    if (document == NULL ||
            pcore_browser_execute_scripts(document, 1, 0, NULL, NULL,
            NULL, &executed, &ignored, error, sizeof(error), &runtime,
            &bridge) != 0 || executed != 1 || ignored != 0 ||
            runtime == NULL || bridge == NULL) {
        ok = 0;
    }
    if (ok) {
        g_render_doc = document;
        g_render_sheet = NULL;
        g_doc_h = PCore_DocumentHeight(document);
        g_scroll_y = 0;
        g_browser_script_session.document = document;
        g_browser_script_session.runtime = runtime;
        g_browser_script_session.bridge = bridge;
        runtime = NULL;
        bridge = NULL;
    }
    if (ok) {
        rc = PBrowser_ScriptSessionRequestDialogClose(
                g_browser_script_session.bridge->session, "blocked",
                &handled, &closed);
        if (rc != PSCRIPT_OK || handled != 1 || closed != 0) {
            ok = 0;
            _snprintf(error, sizeof(error) - 1,
                    "blocked rc=%d handled=%d closed=%d", rc, handled,
                    closed);
            error[sizeof(error) - 1] = '\0';
        }
    }
    if (ok && pcore_browser_script_session_evaluate(
            "window.block=false;", -1, error, sizeof(error)) != 0) {
        ok = 0;
    }
    if (ok) {
        handled = 0;
        closed = 0;
        rc = PBrowser_ScriptSessionRequestDialogClose(
                g_browser_script_session.bridge->session, "escape",
                &handled, &closed);
        if (rc != PSCRIPT_OK || handled != 1 || closed != 1) {
            ok = 0;
            _snprintf(error, sizeof(error) - 1,
                    "allowed rc=%d handled=%d closed=%d", rc, handled,
                    closed);
            error[sizeof(error) - 1] = '\0';
        }
    }
    if (ok) {
        handled = 0;
        closed = 0;
        rc = PBrowser_ScriptSessionRequestDialogClose(
                g_browser_script_session.bridge->session, "ignored",
                &handled, &closed);
        if (rc != PSCRIPT_OK || handled != 0 || closed != 0) {
            ok = 0;
            _snprintf(error, sizeof(error) - 1,
                    "inactive rc=%d handled=%d closed=%d", rc, handled,
                    closed);
            error[sizeof(error) - 1] = '\0';
        }
    }
    if (ok && pcore_browser_script_session_evaluate(
            "document.getElementById('result').textContent=events+'|'"
            "+String(d.open)+'|'+d.returnValue;", -1, error,
            sizeof(error)) != 0) {
        ok = 0;
    }
    if (ok && (PCore_NodeTextContentById(document, "result", result,
            sizeof(result), &bytes) != 0 ||
            strcmp(result, "cancel:0;cancel:0;close:0;|false|escape") != 0)) {
        ok = 0;
        if (error[0] == '\0') {
            _snprintf(error, sizeof(error) - 1,
                    "result[%d]=%s", bytes, result);
            error[sizeof(error) - 1] = '\0';
        }
    }
    pcore_browser_script_session_destroy();
    g_render_doc = NULL;
    g_render_sheet = NULL;
    if (runtime != NULL) {
        PScript_Destroy(runtime);
    }
    free(bridge);
    if (document != NULL) {
        PCore_FreeDocument(document);
    }
    if (!ok) {
        show_error(L"TEST 1104 FAIL", error[0] != '\0' ? error :
                "host dialog Escape bridge failed");
        return FALSE;
    }
    show_info(L"TEST 1104 OK",
            "The host can route Escape to the active modal through the"
            " Browser requestClose bridge; cancellation consumes Escape"
            " without closing, while an accepted request commits close and"
            " returnValue, and an inactive session is left untouched.");
    return TRUE;
}

