    sheet = NULL;
    runtime = NULL;
    bridge = NULL;
    result = NULL;
    session_error = NULL;
    memset(error, 0, sizeof(error));
    executed = -1;
    ignored = -1;
    ok = 1;
    pcore_browser_script_session_destroy();
    g_render_doc = NULL;
    g_render_sheet = NULL;
    g_doc_w = 0;
    g_doc_h = 0;
    g_view_w = 0;
    g_view_h = 0;
    g_scroll_x = 0;
    g_scroll_y = 0;
    g_page_scroll_dpi = 96;
