        if (memory_dc != NULL) { DeleteDC(memory_dc); }
        if (screen_dc != NULL) { ReleaseDC(NULL, screen_dc); }
        PCore_FreeStylesheet(hSheet);
        PCore_FreeDocument(hDoc);
        show_error(L"TEST 47 FAIL", "could not create off-screen surface");
