    if (screen_w <= 0) { screen_w = 240; }
    if (screen_h <= 0) { screen_h = 320; }
    hDoc = PCore_ParseHTML(HTML, sizeof(HTML) - 1);
    hSheet = PCore_ParseCSS(CSS, sizeof(CSS) - 1,
            "http://positron.local/table-normalise.css");
