/* -------------------------------------------------------------------- */
/* TEST 136 - bounded successful-GET Browse history and back state       */
/* -------------------------------------------------------------------- */
static BOOL test136_browse_history_back(void)
{
    static const char URL_A[] = "https://example.com/";
    static const char URL_B[] = "https://www.iana.org/help/example-domains";
    static const char URL_C[] = "https://www.iana.org/domains/reserved";
    static const char URL_D[] = "https://www.iana.org/domains";
    const char *target;
    const char *current;
    int target_index;
    int ok;
    char error[256];

    ok = 1;
    target_index = -1;
    pcore_browse_history_reset();
    pcore_browse_history_commit_navigation(URL_A, 1, -1);
    pcore_browse_history_commit_navigation(URL_B, 1, -1);
    pcore_browse_history_commit_navigation(URL_C, 1, -1);
    pcore_browse_history_commit_navigation("https://post.invalid/", 2, -1);
    target = pcore_browse_history_back_target(&target_index);
    current = pcore_browse_history_current();
    if (g_browse_history.count != 3 || g_browse_history.index != 2 ||
            target == NULL || strcmp(target, URL_B) != 0 ||
            target_index != 1 || current == NULL ||
            strcmp(current, URL_C) != 0) {
        ok = 0;
    }
    if (ok) {
        /* Merely asking for a back target models a failed reload: the
         * committed position must remain on C until success is reported. */
        current = pcore_browse_history_current();
        if (current == NULL || strcmp(current, URL_C) != 0) {
            ok = 0;
        }
    }
    if (ok) {
        pcore_browse_history_commit_navigation(target, 1, target_index);
        pcore_browse_history_commit_navigation(URL_D, 1, -1);
        current = pcore_browse_history_current();
        if (g_browse_history.count != 3 || g_browse_history.index != 2 ||
                strcmp(g_browse_history.entries[0], URL_A) != 0 ||
                strcmp(g_browse_history.entries[1], URL_B) != 0 ||
                strcmp(g_browse_history.entries[2], URL_D) != 0 ||
                current == NULL || strcmp(current, URL_D) != 0) {
            ok = 0;
        }
    }
    if (ok) {
        target = pcore_browse_history_back_target(&target_index);
        if (target == NULL || strcmp(target, URL_B) != 0 ||
                pcore_browse_history_commit_target(target_index) != 0) {
            ok = 0;
        }
    }
    if (ok) {
        target = pcore_browse_history_back_target(&target_index);
        if (target == NULL || strcmp(target, URL_A) != 0 ||
                pcore_browse_history_commit_target(target_index) != 0 ||
                pcore_browse_history_back_target(&target_index) != NULL) {
            ok = 0;
        }
    }
    current = pcore_browse_history_current();
    if (!ok) {
        _snprintf(error, sizeof(error) - 1,
                "count/index=%d/%d target=%d current=%s",
                g_browse_history.count, g_browse_history.index,
                target_index, (current != NULL) ? current : "(null)");
        error[sizeof(error) - 1] = '\0';
        pcore_browse_history_reset();
        show_error(L"TEST 136 FAIL", error);
        return FALSE;
    }
    pcore_browse_history_reset();
    show_info(L"TEST 136 OK",
            "Browse history records only successful GET commits, leaves\n"
            "the position unchanged on a failed back reload, and truncates\n"
            "the forward branch after a new navigation.");
    return TRUE;
}

/* -------------------------------------------------------------------- */
/* TEST 137 - browser script location identity and deferred history.back */
/* -------------------------------------------------------------------- */
static BOOL test137_browser_script_navigation(void)
{
    static const char URL_A[] = "https://example.com/";
    static const char URL_B[] =
        "https://www.iana.org/help/example-domains?from=script#target";
    static const char HTML[] =
        "<!doctype html><html><head><script>"
        "document.getElementById('result').textContent="
        "location.href+'|'+document.URL+'|'+document.documentURI+'|'"
        "+String(window===this)+'|'"
        "+String(document.location===location)+'|'+String(location)+'|'"
        "+String(typeof __pcoreDocumentUrl);"
        "history.back();"
        "</script></head><body><p id='result'>idle</p></body></html>";
    HANDLE document;
    HANDLE runtime;
    pcore_browser_script_bridge *bridge;
    const char *target;
    char expected[1024];
    char result[1024];
    char error[512];
    int result_bytes;
    int target_index;
    int executed;
    int ignored;
    int ok;

    document = NULL;
    runtime = NULL;
    bridge = NULL;
    result_bytes = 0;
    target_index = -1;
    executed = -1;
    ignored = -1;
    ok = 1;
    memset(expected, 0, sizeof(expected));
    memset(result, 0, sizeof(result));
    memset(error, 0, sizeof(error));
    pcore_browse_history_reset();
    pcore_browse_history_commit_navigation(URL_A, 1, -1);
    pcore_browse_history_commit_navigation(URL_B, 1, -1);
    _snprintf(expected, sizeof(expected) - 1,
            "%s|%s|%s|true|true|%s|undefined",
            URL_B, URL_B, URL_B, URL_B);
    expected[sizeof(expected) - 1] = '\0';
    document = PCore_ParseHTML(HTML, sizeof(HTML) - 1);
    if (document == NULL ||
            pcore_browser_execute_scripts(document, 1, 0, URL_B,
            NULL, NULL, &executed, &ignored, error, sizeof(error),
            &runtime, &bridge) != 0 || executed != 1 || ignored != 0 ||
            PCore_NodeTextContentById(document, "result", result,
            sizeof(result), &result_bytes) != 0 ||
            strcmp(result, expected) != 0 || bridge == NULL ||
            bridge->navigation_kind != PCORE_SCRIPT_NAVIGATION_BACK ||
            bridge->navigation_url != NULL ||
            PScript_GetNativeFunctionCount(runtime) != PSCRIPT_MAX_NATIVE_FUNCTIONS) {
        ok = 0;
    }
    target = pcore_browse_history_back_target(&target_index);
    if (target == NULL || strcmp(target, URL_A) != 0 ||
            target_index != 0 || g_browse_history.index != 1) {
        ok = 0;
    }
    if (bridge != NULL) { pcore_browser_script_bridge_destroy(bridge); }
    free(bridge);
    if (runtime != NULL) { PScript_Destroy(runtime); }
    if (document != NULL) { PCore_FreeDocument(document); }
    pcore_browse_history_reset();
    if (!ok) {
        if (error[0] == '\0') {
            _snprintf(error, sizeof(error) - 1,
                    "result[%d]=%s exec/ignore=%d/%d target=%d",
                    result_bytes, result, executed, ignored, target_index);
            error[sizeof(error) - 1] = '\0';
        }
        show_error(L"TEST 137 FAIL", error);
        return FALSE;
    }
    show_info(L"TEST 137 OK",
            "The page context exposes one canonical URL through location\n"
            "and document, while history.back queues navigation without\n"
            "mutating the committed history position synchronously.");
    return TRUE;
}

