    static const char BACK_RESULT[] =
        "P2|https://example.com/app/dir/#fragment|"
        "Hhttps://example.com/app/dir/?x=3#final>"
        "https://example.com/app/dir/#fragment|"
        "https://example.com/app/dir/#fragment|2|4";
