        "clearInterval(c);"
        "var r0=__pcoreRunTimers(0);var r5=__pcoreRunTimers(5);"
        "var r10=__pcoreRunTimers(10);"
        "var r20=__pcoreRunTimers(20);"
        "document.getElementById('result').textContent=r0+'|'+zero+'|'"
        "+r5+'|'+ticks+'|'+r10+'|'+ten+'|'+ticks+'|'+r20+'|'"
        "+String(a>0&&b>0&&c>0);";
